#[cfg(windows)]
thread_local! {
    static FAIL_CROSS_VOLUME_REPLACE_AFTER_PARTIAL_STAGE_WRITE: std::cell::RefCell<Option<std::sync::mpsc::SyncSender<(std::path::PathBuf, Vec<u8>)>>> = const { std::cell::RefCell::new(None) };
    static FAIL_CROSS_VOLUME_REPLACE_BEFORE_STAGE_FLUSH: std::cell::RefCell<Option<std::sync::mpsc::SyncSender<(std::path::PathBuf, Vec<u8>)>>> = const { std::cell::RefCell::new(None) };
}

#[cfg(windows)]
pub(super) fn arm_cross_volume_replace_stage_flush_failure_for_test(
    observed_stage: std::sync::mpsc::SyncSender<(std::path::PathBuf, Vec<u8>)>,
) {
    FAIL_CROSS_VOLUME_REPLACE_BEFORE_STAGE_FLUSH.with(|slot| {
        assert!(
            slot.borrow_mut().replace(observed_stage).is_none(),
            "stage flush failure is armed once per executor thread"
        );
    });
}

#[cfg(windows)]
pub(super) fn take_cross_volume_replace_stage_flush_failure_for_test(
    ledger: &crate::operations::journal::JournalCrossVolumeMoveReplace,
) -> bool {
    use std::os::windows::ffi::OsStringExt;
    FAIL_CROSS_VOLUME_REPLACE_BEFORE_STAGE_FLUSH.with(|slot| {
        let Some(sender) = slot.borrow_mut().take() else {
            return false;
        };
        let path = std::path::PathBuf::from(std::ffi::OsString::from_wide(&ledger.stage.units));
        let bytes =
            std::fs::read(&path).expect("complete stage is readable before injected flush failure");
        assert!(
            !bytes.is_empty(),
            "injected flush failure follows the complete non-empty stage write"
        );
        sender
            .send((path, bytes))
            .expect("Shell test observes complete stage before held-handle cleanup");
        true
    })
}

#[cfg(windows)]
pub(super) fn arm_cross_volume_replace_partial_stage_write_failure_for_test(
    observed_stage: std::sync::mpsc::SyncSender<(std::path::PathBuf, Vec<u8>)>,
) {
    FAIL_CROSS_VOLUME_REPLACE_AFTER_PARTIAL_STAGE_WRITE.with(|slot| {
        assert!(
            slot.borrow_mut().replace(observed_stage).is_none(),
            "partial stage failure is armed once per executor thread"
        );
    });
}

#[cfg(windows)]
pub(super) fn take_cross_volume_replace_partial_stage_write_failure_for_test(
    ledger: &crate::operations::journal::JournalCrossVolumeMoveReplace,
) -> bool {
    use std::os::windows::ffi::OsStringExt;
    FAIL_CROSS_VOLUME_REPLACE_AFTER_PARTIAL_STAGE_WRITE.with(|slot| {
        let Some(sender) = slot.borrow_mut().take() else {
            return false;
        };
        let path = std::path::PathBuf::from(std::ffi::OsString::from_wide(&ledger.stage.units));
        let bytes =
            std::fs::read(&path).expect("real stage chunk is readable before injected failure");
        assert!(
            !bytes.is_empty(),
            "injected failure follows a successful non-empty stage write"
        );
        sender
            .send((path, bytes))
            .expect("Shell test observes the written stage before held-handle cleanup");
        true
    })
}
use crate::operations::model::{
    ConflictDecision, OperationRequest, OperationService, ServiceEvent,
};

#[test]
fn seven_zip_extract_dispatch_fails_closed_without_touching_sibling_outputs() {
    use crate::operations::model::{SevenZipExtractGuard, SevenZipExtractSourceGuard};
    let root = tempfile::tempdir().unwrap();
    let sources = [root.path().join("first.7z"), root.path().join("second.7z")];
    for source in &sources {
        std::fs::write(source, b"archive bytes").unwrap();
    }
    let guards: Vec<_> = sources
        .iter()
        .map(|source| {
            crate::operations::model::test_zip_create_guard(source, &source.with_extension(""))
        })
        .collect();
    let parent =
        crate::operations::model::test_zip_create_guard(&sources[0], &root.path().join("unused"));
    let request = OperationRequest::extract_7z_many(
        sources.to_vec(),
        SevenZipExtractGuard {
            destination_parent_identity: parent.destination_parent_identity,
            sources: guards
                .iter()
                .map(|guard| SevenZipExtractSourceGuard {
                    source_identity: guard.source_identity.clone(),
                    source_kind: guard.source_kind,
                    entry_name: guard.entry_name.clone(),
                })
                .collect(),
            provider_revision: 1,
            provider_binding: crate::archive_provider::ArchiveOperationBinding {
                executable: crate::archive_provider::ArchiveFileHint {
                    path: root.path().join("7z.exe"),
                    identity: crate::archive_provider::ArchiveFileIdentity {
                        volume_serial: 1,
                        file_index: 700,
                    },
                },
                zip_dll: crate::archive_provider::ArchiveFileHint {
                    path: root.path().join("7z.dll"),
                    identity: crate::archive_provider::ArchiveFileIdentity {
                        volume_serial: 1,
                        file_index: 701,
                    },
                },
            },
        },
    )
    .unwrap();
    let mut service = OperationService::default();
    let token = service.submit(request).unwrap();
    let command = service.start_next().unwrap();
    let (_controls_tx, controls_rx) = std::sync::mpsc::channel();
    let mut terminal = None;
    execute_prepare(command, &AtomicBool::new(false), &controls_rx, |fact| {
        if let ExecutorFact::Terminal {
            token: actual,
            report,
        } = fact
        {
            assert_eq!(actual, token);
            terminal = service.terminal(actual, report);
        }
    });
    let committed = terminal.expect("the disabled executor returns one terminal result");
    let ServiceEvent::TerminalCommitted { report, .. } = committed;
    assert_eq!(report.outcome, TerminalOutcome::Failed);
    assert_eq!(report.final_counters.total_items, Some(2));
    assert_eq!(report.final_counters.processed_items, 2);
    assert_eq!(report.receipts.len(), 2);
    assert!(
        report
            .receipts
            .iter()
            .all(|receipt| receipt.outcome == ItemOutcome::Failed)
    );
    for source in &sources {
        assert!(source.exists());
        assert!(!source.with_extension("").exists());
    }
}

#[test]
fn uncertain_trash_result_requests_reconcile_without_becoming_a_change() {
    let unknown_receipt = ItemReceipt {
        item: ItemId(0),
        outcome: ItemOutcome::Unknown,
        detail: Some("Shell mutation outcome is uncertain".into()),
        created_folder_path: None,
        created_archive_path: None,
        move_receipt: None,
        replace_receipt: None,
        copy_undo: None,
    };
    let source = PathBuf::from(r"C:\source\item.txt");

    assert!(has_uncertain_trash_result(
        OperationKind::Trash,
        std::slice::from_ref(&unknown_receipt),
    ));
    assert_eq!(unknown_receipt.outcome, ItemOutcome::Unknown);
    assert_eq!(
        change_hints(OperationKind::Trash, &[source], None),
        vec![FsChangeHint {
            directory: PathBuf::from(r"C:\source"),
        }]
    );

    let known_failure = ItemReceipt {
        outcome: ItemOutcome::Failed,
        ..unknown_receipt
    };
    assert!(!has_uncertain_trash_result(
        OperationKind::Trash,
        &[known_failure],
    ));
}

fn uncertain_trash_adapter(
    _source: &std::path::Path,
    _accepted: &super::super::model::TrashSourceGuard,
    _tag: Option<u32>,
    _cancelled: &AtomicBool,
) -> Result<super::super::trash::TrashReceipt, CopyError> {
    Err(CopyError::Unknown(
        "injected Shell mutation uncertainty".into(),
    ))
}

#[test]
fn uncertain_trash_executor_report_hints_source_without_receipt_or_confirmed_change() {
    let root = tempfile::tempdir().unwrap();
    let source = root.path().join("item.txt");
    std::fs::write(&source, b"item").unwrap();
    let mut service = OperationService::default();
    let token = service
        .submit(OperationRequest {
            kind: OperationKind::Trash,
            virtual_source: None,
            sources: vec![source.clone()],
            destination: None,
            move_identity_guard: None,
            clipboard_move_source_evidence: None,
            rename_reparse_guard: None,
            move_destination_identity_guard: None,
            move_replace_source_evidence: None,
            trash_source_guards: Some(vec![super::super::model::TrashSourceGuard {
                identity: crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &source,
                    crate::directory::EntryKind::File,
                )
                .unwrap(),
                reparse_candidate: false,
            }]),
            source_cleanup_identity_guard: None,
            initial_conflict_policy: None,
            copy_destination_identity_guard: None,
            create_parent_directory_identity_guard: None,
            zip_create_guard: None,
            shortcut_create_guard: None,
            seven_zip_create_guard: None,
            seven_zip_extract_guard: None,
            origin: None,
            batch_rename_plan: None,
        })
        .unwrap();
    let command = service.start_next().unwrap();
    assert!(service.prepared(token));
    let (_control, controls) = std::sync::mpsc::channel();
    let mut terminal = None;
    let mut trash_receipts = 0;

    execute_prepare_inner_with_lease(
        command,
        &AtomicBool::new(false),
        &controls,
        None,
        |fact| match fact {
            ExecutorFact::Terminal {
                token: actual,
                report,
            } => {
                assert_eq!(actual, token);
                terminal = service.terminal(actual, report);
            }
            ExecutorFact::TrashReceipt { .. } => trash_receipts += 1,
            _ => {}
        },
        || {},
        uncertain_trash_adapter,
    );

    let report = match terminal.unwrap() {
        crate::operations::model::ServiceEvent::TerminalCommitted { report, .. } => report,
    };
    assert_eq!(report.outcome, TerminalOutcome::Unknown);
    assert_eq!(report.receipts.len(), 1);
    assert_eq!(report.receipts[0].outcome, ItemOutcome::Unknown);
    assert_eq!(report.final_counters.processed_items, 0);
    assert_eq!(trash_receipts, 0);
    assert_eq!(
        report.change_hints,
        vec![FsChangeHint {
            directory: root.path().to_path_buf(),
        }]
    );
}

#[test]
fn create_7z_executor_is_fail_closed_and_does_not_create_output() {
    let root = tempfile::tempdir().unwrap();
    let source = root.path().join("empty.txt");
    std::fs::write(&source, []).unwrap();
    let output = root.path().join("result.7z");
    let source_facts = crate::operations::model::test_zip_create_guard(&source, &output);
    let provider_hint = |name: &str, index| crate::archive_provider::ArchiveFileHint {
        path: root.path().join(name),
        identity: crate::archive_provider::ArchiveFileIdentity {
            volume_serial: 1,
            file_index: index,
        },
    };
    let request = OperationRequest::create_7z(
        vec![source.clone()],
        output.clone(),
        crate::operations::model::SevenZipCreateGuard {
            destination_parent_identity: source_facts.destination_parent_identity,
            sources: vec![crate::operations::model::SevenZipCreateSourceGuard {
                source_identity: source_facts.source_identity,
                source_kind: source_facts.source_kind,
                entry_name: source_facts.entry_name,
            }],
            provider_revision: 7,
            provider_binding: crate::archive_provider::ArchiveOperationBinding {
                executable: provider_hint("7z.exe", 2),
                zip_dll: provider_hint("7z.dll", 3),
            },
        },
    )
    .unwrap();
    let mut service = OperationService::default();
    service.submit(request).unwrap();
    let command = service.start_next().unwrap();
    let (_control_sender, controls) = std::sync::mpsc::channel();
    let (sender, receiver) = std::sync::mpsc::channel();
    execute_prepare(command, &AtomicBool::new(false), &controls, |fact| {
        sender.send(fact).unwrap()
    });
    let facts = receiver.try_iter().collect::<Vec<_>>();
    assert!(
        matches!(facts.as_slice(), [ExecutorFact::Terminal { report, .. }]
        if report.outcome == TerminalOutcome::Failed
            && report.receipts.len() == 1
            && report.receipts[0].item == ItemId(0)
            && report.receipts[0].outcome == ItemOutcome::Failed)
    );
    assert!(!output.exists());
    assert_eq!(
        std::fs::read_dir(root.path()).unwrap().count(),
        1,
        "only the original source remains"
    );
}

