#[cfg(windows)]
fn run_trash_preflight(request: OperationRequest) {
    let mut service = OperationService::default();
    service.submit(request).unwrap();
    let command = service.start_next().unwrap();
    let (_control, controls) = std::sync::mpsc::channel();
    execute_prepare_inner_with_lease(
        command,
        &AtomicBool::new(false),
        &controls,
        None,
        |_| {},
        || {},
        unexpected_trash_adapter,
    );
}

#[cfg(windows)]
fn queued_trash_request(
    source: PathBuf,
    guard: Option<Vec<crate::directory::EntrySourceIdentity>>,
) -> OperationRequest {
    OperationRequest {
        kind: OperationKind::Trash,
        virtual_source: None,
        sources: vec![source],
        destination: None,
        batch_rename_plan: None,
        move_identity_guard: None,
        clipboard_move_source_evidence: None,
        rename_reparse_guard: None,
        move_destination_identity_guard: None,
        move_replace_source_evidence: None,
        trash_source_guards: guard.map(|guards| {
            guards
                .into_iter()
                .map(|identity| super::super::model::TrashSourceGuard {
                    identity,
                    reparse_candidate: false,
                })
                .collect()
        }),
        source_cleanup_identity_guard: None,
        initial_conflict_policy: None,
        copy_destination_identity_guard: None,
        create_parent_directory_identity_guard: None,
        zip_create_guard: None,
        shortcut_create_guard: None,
        seven_zip_create_guard: None,
        seven_zip_extract_guard: None,
        origin: None,
    }
}

#[cfg(windows)]
#[test]
fn queued_trash_rejects_replaced_file_before_adapter() {
    let root = tempfile::tempdir().unwrap();
    let source = root.path().join("item.txt");
    std::fs::write(&source, b"accepted file").unwrap();
    let identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
        &source,
        crate::directory::EntryKind::File,
    )
    .unwrap();
    std::fs::remove_file(&source).unwrap();
    std::fs::write(&source, b"replacement file").unwrap();

    run_trash_preflight(queued_trash_request(source.clone(), Some(vec![identity])));
    assert_eq!(std::fs::read(source).unwrap(), b"replacement file");
}

#[cfg(windows)]
#[test]
fn queued_trash_rejects_replaced_folder_before_adapter() {
    let root = tempfile::tempdir().unwrap();
    let source = root.path().join("folder");
    std::fs::create_dir(&source).unwrap();
    std::fs::write(source.join("accepted.txt"), b"accepted").unwrap();
    let identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
        &source,
        crate::directory::EntryKind::Folder,
    )
    .unwrap();
    std::fs::remove_dir_all(&source).unwrap();
    std::fs::create_dir(&source).unwrap();
    std::fs::write(source.join("replacement.txt"), b"replacement").unwrap();

    run_trash_preflight(queued_trash_request(source.clone(), Some(vec![identity])));
    assert_eq!(
        std::fs::read(source.join("replacement.txt")).unwrap(),
        b"replacement"
    );
}

#[cfg(windows)]
#[test]
fn trash_revalidates_each_source_after_prior_adapter_interleaving() {
    let root = local_ntfs_fixture();
    let first = root.path().join("first.txt");
    let second = root.path().join("second.txt");
    std::fs::write(&first, b"first").unwrap();
    std::fs::write(&second, b"accepted second").unwrap();
    let first_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
        &first,
        crate::directory::EntryKind::File,
    )
    .unwrap();
    let second_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
        &second,
        crate::directory::EntryKind::File,
    )
    .unwrap();
    let request = OperationRequest {
        kind: OperationKind::Trash,
        virtual_source: None,
        sources: vec![first.clone(), second.clone()],
        destination: None,
        batch_rename_plan: None,
        move_identity_guard: None,
        clipboard_move_source_evidence: None,
        rename_reparse_guard: None,
        move_destination_identity_guard: None,
        move_replace_source_evidence: None,
        trash_source_guards: Some(
            vec![first_identity, second_identity]
                .into_iter()
                .map(|identity| super::super::model::TrashSourceGuard {
                    identity,
                    reparse_candidate: false,
                })
                .collect(),
        ),
        source_cleanup_identity_guard: None,
        initial_conflict_policy: None,
        copy_destination_identity_guard: None,
        create_parent_directory_identity_guard: None,
        zip_create_guard: None,
        shortcut_create_guard: None,
        seven_zip_create_guard: None,
        seven_zip_extract_guard: None,
        origin: None,
    };
    let mut service = OperationService::default();
    service.submit(request).unwrap();
    let command = service.start_next().unwrap();
    let (_control, controls) = std::sync::mpsc::channel();
    let mut adapter_calls = 0;
    let mut facts = Vec::new();
    execute_prepare_inner_with_lease(
        command,
        &AtomicBool::new(false),
        &controls,
        None,
        |fact| facts.push(fact),
        || {},
        |source, _, _, _| {
            adapter_calls += 1;
            assert_eq!(source, first);
            std::fs::remove_file(&second).unwrap();
            std::fs::write(&second, b"replacement second").unwrap();
            Err(CopyError::Io("injected adapter interleaving".into()))
        },
    );

    assert_eq!(adapter_calls, 1);
    assert_eq!(std::fs::read(second).unwrap(), b"replacement second");
    let terminal = facts
        .into_iter()
        .find_map(|fact| match fact {
            ExecutorFact::Terminal { report, .. } => Some(report),
            _ => None,
        })
        .expect("Trash worker should emit one terminal report");
    assert_eq!(terminal.outcome, TerminalOutcome::Failed);
    assert_eq!(terminal.receipts.len(), 2);
    assert_eq!(terminal.receipts[0].outcome, ItemOutcome::Failed);
    assert_eq!(terminal.receipts[1].outcome, ItemOutcome::Failed);
    assert_eq!(
        terminal.receipts[1].detail.as_deref(),
        Some("Trash source identity changed before adapter dispatch")
    );
}

#[cfg(windows)]
#[test]
#[ignore = "mutates the current user's Recycle Bin; verifies the accepted identity guard"]
fn ignored_trash_path_substitution_aborts_before_recycling_replacement() {
    use crate::operations::trash;
    use std::os::windows::ffi::OsStrExt;
    use std::sync::{Arc, Mutex};

    struct FixtureRecovery {
        root: Option<tempfile::TempDir>,
        root_path: PathBuf,
        path: PathBuf,
        accepted_a_path: PathBuf,
        accepted_a_identity: crate::directory::EntrySourceIdentity,
        replacement_b_identity: Option<crate::directory::EntrySourceIdentity>,
        armed: bool,
    }

    impl FixtureRecovery {
        fn move_no_replace(source: &Path, destination: &Path) -> Result<(), String> {
            let source_wide: Vec<u16> = source.as_os_str().encode_wide().chain(Some(0)).collect();
            let destination_wide: Vec<u16> = destination
                .as_os_str()
                .encode_wide()
                .chain(Some(0))
                .collect();
            unsafe {
                ::windows::Win32::Storage::FileSystem::MoveFileW(
                    ::windows::core::PCWSTR(source_wide.as_ptr()),
                    ::windows::core::PCWSTR(destination_wide.as_ptr()),
                )
            }
            .map_err(|error| {
                format!(
                    "no-replace move {} -> {}: {error}",
                    source.display(),
                    destination.display()
                )
            })
        }

        fn path_identity(
            path: &Path,
        ) -> Result<Option<crate::directory::EntrySourceIdentity>, String> {
            match std::fs::symlink_metadata(path) {
                Ok(_) => crate::directory::EntrySourceIdentity::from_path_no_follow(
                    path,
                    crate::directory::EntryKind::File,
                )
                .map(Some)
                .ok_or_else(|| {
                    format!(
                        "could not capture no-follow identity for existing path {}; preserving fixture root",
                        path.display()
                    )
                }),
                Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
                Err(error) => Err(format!("inspect {}: {error}", path.display())),
            }
        }

        fn verify_accepted_a_path(&self) -> Result<(), String> {
            match Self::path_identity(&self.accepted_a_path)? {
                None => Ok(()),
                Some(identity) if identity == self.accepted_a_identity => Ok(()),
                Some(identity) => Err(format!(
                    "accepted A path {} contains unproven identity {:?}; preserving fixture root",
                    self.accepted_a_path.display(),
                    identity
                )),
            }
        }

        fn restore_matching_item(&mut self) -> Result<(), String> {
            let items = ::trash::os_limited::list().map_err(|error| error.to_string())?;
            let matching: Vec<_> = items
                .into_iter()
                .filter(|item| item.original_path() == self.path)
                .collect();
            let item_ids = matching
                .iter()
                .map(|item| {
                    format!(
                        "{} at {}",
                        item.id.to_string_lossy(),
                        item.original_path().display()
                    )
                })
                .collect::<Vec<_>>();
            if matching.len() > 1 {
                return Err(format!(
                    "multiple Recycle Bin items match fixture path {}: {}; left them untouched",
                    self.path.display(),
                    item_ids.join(", ")
                ));
            }

            let current_identity = Self::path_identity(&self.path)?;
            if let Some(item) = matching.into_iter().next() {
                let displaced_occupant = if let Some(current_identity) = current_identity {
                    let Some(replacement_identity) = self.replacement_b_identity.as_ref() else {
                        return Err(format!(
                            "fixture path {} is occupied but B identity was not captured; matching Recycle Bin item(s): {}",
                            self.path.display(),
                            item_ids.join(", ")
                        ));
                    };
                    if &current_identity != replacement_identity {
                        return Err(format!(
                            "fixture path {} is occupied by an unproven object (identity {:?}, expected B {:?}); matching Recycle Bin item(s): {}",
                            self.path.display(),
                            current_identity,
                            replacement_identity,
                            item_ids.join(", ")
                        ));
                    }
                    let quarantine = (0..100)
                        .map(|suffix| {
                            self.path
                                .with_file_name(format!("fixture-recovery-occupant-{suffix}.tmp"))
                        })
                        .find(|candidate| {
                            candidate.starts_with(&self.root_path)
                                && matches!(
                                    std::fs::symlink_metadata(candidate),
                                    Err(error) if error.kind() == std::io::ErrorKind::NotFound
                                )
                        })
                        .ok_or_else(|| {
                            "could not find an unused fixture sibling path".to_owned()
                        })?;
                    Self::move_no_replace(&self.path, &quarantine)?;
                    let quarantined_identity = Self::path_identity(&quarantine)?.ok_or_else(|| {
                        format!(
                            "quarantine path {} disappeared after moving B; preserving fixture root",
                            quarantine.display()
                        )
                    })?;
                    if &quarantined_identity != replacement_identity {
                        return Err(format!(
                            "quarantine path {} contains identity {:?}, expected B {:?}; preserving fixture root",
                            quarantine.display(),
                            quarantined_identity,
                            replacement_identity
                        ));
                    }
                    Some(quarantine)
                } else {
                    None
                };
                trash::restore_recovered_item_for_test(item.id, &self.path)
                    .map_err(|error| {
                        if let Some(quarantine) = displaced_occupant {
                            if let Err(rollback_error) = Self::move_no_replace(&quarantine, &self.path) {
                                return format!(
                                    "restore exact fixture Recycle Bin item(s) {} failed ({error:?}); B remains at {} because rollback to {} failed: {rollback_error}",
                                    item_ids.join(", "),
                                    quarantine.display(),
                                    self.path.display()
                                );
                            }
                        }
                        format!(
                            "restore exact fixture Recycle Bin item(s) {}: {error:?}",
                            item_ids.join(", ")
                        )
                    })?;
                let restored_identity = Self::path_identity(&self.path)?.ok_or_else(|| {
                    format!(
                        "exact Recycle Bin item {} at {} restored no object; preserving fixture root",
                        item_ids.join(", "),
                        self.path.display()
                    )
                })?;
                if Some(&restored_identity) != self.replacement_b_identity.as_ref()
                    && restored_identity != self.accepted_a_identity
                {
                    return Err(format!(
                        "exact Recycle Bin item(s) {} restored unproven identity {:?} at {}; preserving fixture root",
                        item_ids.join(", "),
                        restored_identity,
                        self.path.display()
                    ));
                }
                self.verify_accepted_a_path()?;
                self.armed = false;
                return Ok(());
            }

            // A panic between renaming A and creating B must return only the proven A object.
            match current_identity {
                Some(identity) => {
                    if Some(&identity) != self.replacement_b_identity.as_ref() {
                        return Err(format!(
                            "fixture path {} contains an unproven object without a matching receipt; preserving fixture root",
                            self.path.display()
                        ));
                    }
                    self.verify_accepted_a_path()?;
                }
                None => {
                    if Self::path_identity(&self.accepted_a_path)?
                        != Some(self.accepted_a_identity.clone())
                    {
                        return Err(format!(
                            "accepted A identity is unavailable at {}; preserving fixture root",
                            self.accepted_a_path.display()
                        ));
                    }
                    Self::move_no_replace(&self.accepted_a_path, &self.path)?;
                    if Self::path_identity(&self.path)? != Some(self.accepted_a_identity.clone()) {
                        return Err(format!(
                            "accepted A did not reach fixture path {}; preserving fixture root",
                            self.path.display()
                        ));
                    }
                }
            }
            self.armed = false;
            Ok(())
        }
    }

    impl Drop for FixtureRecovery {
        fn drop(&mut self) {
            if self.armed {
                if let Err(error) = self.restore_matching_item() {
                    let preserved_path = self.root.take().map(|root| root.keep());
                    eprintln!(
                        "Trash path-substitution fixture recovery failed for {}: {error}; fixture root preserved at {}",
                        self.path.display(),
                        preserved_path.as_ref().map_or_else(
                            || self.root_path.display().to_string(),
                            |path| path.display().to_string()
                        )
                    );
                }
            }
        }
    }

    let root = local_ntfs_fixture();
    let volume_root = root.path().ancestors().last().unwrap();
    let root_wide: Vec<u16> = volume_root
        .as_os_str()
        .encode_wide()
        .chain(Some(0))
        .collect();
    let mut filesystem_name = [0u16; 32];
    let volume_is_ntfs = unsafe {
        ::windows::Win32::Storage::FileSystem::GetVolumeInformationW(
            ::windows::core::PCWSTR(root_wide.as_ptr()),
            None,
            None,
            None,
            None,
            Some(&mut filesystem_name),
        )
    }
    .is_ok()
        && String::from_utf16_lossy(&filesystem_name)
            .trim_end_matches('\0')
            .eq_ignore_ascii_case("NTFS");
    const DRIVE_FIXED: u32 = 3;
    let volume_is_fixed = unsafe {
        ::windows::Win32::Storage::FileSystem::GetDriveTypeW(::windows::core::PCWSTR(
            root_wide.as_ptr(),
        )) == DRIVE_FIXED
    };
    assert!(
        !root.path().to_string_lossy().starts_with(r"\\") && volume_is_ntfs && volume_is_fixed,
        "diagnostic requires a local NTFS TempDir fixture, got {}",
        root.path().display()
    );

    let source = root.path().join("fixture.txt");
    let moved_a = root.path().join("accepted-object-a.txt");
    let bytes_a = b"accepted object A";
    let bytes_b = b"replacement object B";
    std::fs::write(&source, bytes_a).unwrap();
    let identity_a = crate::directory::EntrySourceIdentity::from_path_no_follow(
        &source,
        crate::directory::EntryKind::File,
    )
    .unwrap();
    let root_path = root.path().to_path_buf();
    let recovery = Arc::new(Mutex::new(FixtureRecovery {
        root: Some(root),
        root_path,
        path: source.clone(),
        accepted_a_path: moved_a.clone(),
        accepted_a_identity: identity_a.clone(),
        replacement_b_identity: None,
        armed: false,
    }));
    let request = queued_trash_request(source.clone(), Some(vec![identity_a.clone()]));
    let mut service = OperationService::default();
    service.submit(request).unwrap();
    let command = service.start_next().unwrap();
    let (_control, controls) = std::sync::mpsc::channel();
    let mut facts = Vec::new();
    let mut identity_b_before_callback = None;
    let mut identity_a_at_side_path = None;
    let recovery_for_adapter = recovery.clone();

    execute_prepare_with_trash_identity_adapter_for_test(
        command,
        &AtomicBool::new(false),
        &controls,
        |fact| facts.push(fact),
        |path, accepted| {
            // Executor identity admission has already succeeded. Arm recovery before any path
            // substitution and carry the exact admission-time guard into the real Shell adapter.
            assert_eq!(accepted, &identity_a, "pass through the accepted identity");
            recovery_for_adapter
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .armed = true;
            std::fs::rename(path, &moved_a).unwrap();
            identity_a_at_side_path = Some(
                crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &moved_a,
                    crate::directory::EntryKind::File,
                )
                .unwrap(),
            );
            assert_eq!(identity_a_at_side_path.as_ref(), Some(&identity_a));
            std::fs::write(path, bytes_b).unwrap();
            let identity_b = crate::directory::EntrySourceIdentity::from_path_no_follow(
                path,
                crate::directory::EntryKind::File,
            )
            .unwrap();
            recovery_for_adapter
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .replacement_b_identity = Some(identity_b.clone());
            assert_ne!(
                identity_a, identity_b,
                "A and B must be distinct filesystem objects"
            );
            assert_eq!(std::fs::read(&moved_a).unwrap(), bytes_a);
            assert_eq!(std::fs::read(path).unwrap(), bytes_b);
            identity_b_before_callback = Some(identity_b);

            trash::move_to_trash_with_identity(path, accepted)
        },
    );

    let replacement_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
        &source,
        crate::directory::EntryKind::File,
    )
    .unwrap();
    assert_eq!(std::fs::read(&source).unwrap(), bytes_b);
    assert_eq!(std::fs::read(&moved_a).unwrap(), bytes_a);
    assert_eq!(
        crate::directory::EntrySourceIdentity::from_path_no_follow(
            &moved_a,
            crate::directory::EntryKind::File,
        )
        .as_ref(),
        identity_a_at_side_path.as_ref(),
        "renamed accepted A retains its captured filesystem identity"
    );
    let identity_b = identity_b_before_callback.expect("capture replacement B identity");
    assert_ne!(identity_a, identity_b);
    assert_eq!(replacement_identity, identity_b);
    recovery
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .verify_accepted_a_path()
        .expect("accepted A remains at its fixture sibling");
    let trash_receipt_facts = facts
        .iter()
        .filter(|fact| matches!(fact, ExecutorFact::TrashReceipt { .. }))
        .count();

    let mut terminal_facts: Vec<_> = facts
        .into_iter()
        .filter_map(|fact| match fact {
            ExecutorFact::Terminal { report, .. } => Some(report),
            _ => None,
        })
        .collect();
    assert_eq!(
        terminal_facts.len(),
        1,
        "exactly one terminal fact is expected"
    );
    let terminal = terminal_facts.pop().unwrap();
    assert_eq!(terminal.outcome, TerminalOutcome::Unknown);
    assert_eq!(terminal.receipts.len(), 1);
    assert_eq!(terminal.receipts[0].outcome, ItemOutcome::Unknown);
    assert_eq!(
        trash_receipt_facts, 0,
        "callback abort must not create an undo claim"
    );
    recovery
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .armed = false;
}

#[cfg(windows)]
#[test]
fn trash_source_guard_shape_and_kind_mismatches_fail_closed() {
    let root = local_ntfs_fixture();
    let file = root.path().join("item.txt");
    std::fs::write(&file, b"item").unwrap();
    let file_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
        &file,
        crate::directory::EntryKind::File,
    )
    .unwrap();

    let missing_guard = queued_trash_request(file.clone(), None);
    assert!(!trash_source_guards_are_well_formed(&missing_guard));
    run_trash_preflight(missing_guard);
    let misaligned_guard = queued_trash_request(
        file.clone(),
        Some(vec![file_identity.clone(), file_identity.clone()]),
    );
    assert!(!trash_source_guards_are_well_formed(&misaligned_guard));
    run_trash_preflight(misaligned_guard);

    let folder = root.path().join("folder");
    std::fs::create_dir(&folder).unwrap();
    let folder_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
        &folder,
        crate::directory::EntryKind::Folder,
    )
    .unwrap();
    let mut kind_mismatch = queued_trash_request(folder.clone(), Some(vec![file_identity.clone()]));
    assert!(trash_source_guards_are_well_formed(&kind_mismatch));
    assert!(!trash_source_identity_matches(
        &folder,
        &super::super::model::TrashSourceGuard {
            identity: file_identity.clone(),
            reparse_candidate: false,
        },
    ));
    run_trash_preflight(kind_mismatch.clone());
    kind_mismatch.trash_source_guards = Some(vec![super::super::model::TrashSourceGuard {
        identity: folder_identity.clone(),
        reparse_candidate: false,
    }]);
    assert!(trash_source_guards_are_well_formed(&kind_mismatch));
    assert!(trash_source_identity_matches(
        &folder,
        kind_mismatch
            .trash_source_guards
            .as_ref()
            .unwrap()
            .first()
            .unwrap(),
    ));

    let ordinary_guard = super::super::model::TrashSourceGuard {
        identity: folder_identity.clone(),
        reparse_candidate: false,
    };
    let junction_guard = super::super::model::TrashSourceGuard {
        identity: folder_identity.clone(),
        reparse_candidate: true,
    };
    let mut mixed = kind_mismatch.clone();
    mixed.sources = vec![folder.clone(), folder.clone()];
    mixed.trash_source_guards = Some(vec![ordinary_guard.clone(), junction_guard.clone()]);
    assert!(
        trash_source_guards_are_well_formed(&mixed),
        "mixed batches are admitted"
    );
    mixed.trash_source_guards = Some(vec![junction_guard.clone(), junction_guard]);
    assert!(
        trash_source_guards_are_well_formed(&mixed),
        "homogeneous candidate batches are admitted"
    );

    let backing = root.path().join("backing");
    let junction = root.path().join("junction");
    std::fs::create_dir(&backing).unwrap();
    let backing_payload = backing.join("payload.txt");
    std::fs::write(&backing_payload, b"junction backing data").unwrap();
    let status = std::process::Command::new("cmd.exe")
        .args(["/C", "mklink", "/J"])
        .arg(&junction)
        .arg(&backing)
        .status()
        .unwrap();
    assert!(status.success(), "mklink /J must create the test junction");
    let raw_target = std::fs::read_link(&junction).unwrap();
    let junction_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
        &junction,
        crate::directory::EntryKind::Folder,
    )
    .unwrap();
    let mut junction_request =
        queued_trash_request(junction.clone(), Some(vec![junction_identity]));
    junction_request.trash_source_guards.as_mut().unwrap()[0].reparse_candidate = true;
    assert!(trash_source_guards_are_well_formed(&junction_request));
    assert!(trash_source_identity_matches(
        &junction_request.sources[0],
        &junction_request.trash_source_guards.as_ref().unwrap()[0],
    ));
    assert_eq!(
        super::super::trash::admit_source(
            &junction_request.sources[0],
            &junction_request.trash_source_guards.as_ref().unwrap()[0],
        )
        .unwrap(),
        Some(0xA000_0003)
    );
    assert!(std::fs::symlink_metadata(&junction).is_ok());
    assert_eq!(std::fs::read_link(&junction).unwrap(), raw_target);
    assert!(backing.is_dir());
    assert_eq!(
        std::fs::read(&backing_payload).unwrap(),
        b"junction backing data"
    );
}

