#[cfg(windows)]
#[derive(Debug, PartialEq, Eq)]
enum ManifestBarrierFailure {
    BeforePublish(CopyError),
    AfterPublish(CopyError),
}

#[cfg(windows)]
fn spawn_manifest_barrier(
    token: AttemptToken,
    source: PathBuf,
    stage_path: PathBuf,
    destination: PathBuf,
    cancelled: std::sync::Arc<AtomicBool>,
) -> (
    std::sync::mpsc::Receiver<ExecutorFact>,
    std::sync::mpsc::Sender<WorkerControl>,
    std::thread::JoinHandle<Result<(), ManifestBarrierFailure>>,
) {
    let (fact_sender, fact_receiver) = std::sync::mpsc::channel();
    let (control_sender, controls) = std::sync::mpsc::channel();
    let worker = std::thread::spawn(move || {
        let mut source_pins = windows::preflight_pinned_source_tree(&source, &cancelled)
            .expect("pin source tree on worker");
        let stage = windows::create_attempt_staging_root(&stage_path)
            .expect("create staging root on worker");
        let staged = windows::stage_pinned_source_tree(&mut source_pins, stage, &cancelled)
            .expect("stage source tree on worker");
        windows::register_manifest_then_publish(
            token,
            ItemId(0),
            &source,
            &destination,
            &source_pins,
            staged,
            &cancelled,
            &controls,
            &mut |fact| {
                let _ = fact_sender.send(fact);
            },
        )
        .map(|published| drop(published))
        .map_err(|failure| match failure {
            windows::PublishTreeFailure::BeforePublish(error) => {
                ManifestBarrierFailure::BeforePublish(error)
            }
            windows::PublishTreeFailure::AfterPublish { error, .. } => {
                ManifestBarrierFailure::AfterPublish(error)
            }
        })
    });
    (fact_receiver, control_sender, worker)
}

#[cfg(windows)]
#[test]
fn pinned_source_tree_captures_two_level_manifest_and_blocks_path_reuse() {
    use crate::operations::journal::JournalDirectoryNodeKind;

    let fixture = local_ntfs_fixture();
    let root = fixture.path().join("source");
    std::fs::create_dir(&root).unwrap();
    std::fs::create_dir(root.join("nested")).unwrap();
    std::fs::write(root.join("root.txt"), b"root content").unwrap();
    std::fs::write(root.join("nested").join("leaf.bin"), b"nested content").unwrap();

    let pinned = windows::preflight_pinned_source_tree(&root, &AtomicBool::new(false)).unwrap();
    assert!(!pinned.root_identity.is_empty());
    let mut paths: Vec<_> = pinned
        .entries
        .iter()
        .map(|entry| {
            (
                entry.relative_components.clone(),
                entry.node_kind,
                entry.source_identity.clone(),
            )
        })
        .collect();
    paths.sort_by(|left, right| left.0.cmp(&right.0));
    assert_eq!(paths.len(), 3);
    assert_eq!(
        paths[0].0,
        vec!["nested".encode_utf16().collect::<Vec<_>>()]
    );
    assert_eq!(paths[0].1, JournalDirectoryNodeKind::Directory);
    assert_eq!(
        paths[1].0,
        vec![
            "nested".encode_utf16().collect::<Vec<_>>(),
            "leaf.bin".encode_utf16().collect()
        ]
    );
    assert_eq!(paths[1].1, JournalDirectoryNodeKind::File);
    assert_eq!(
        paths[2].0,
        vec!["root.txt".encode_utf16().collect::<Vec<_>>()]
    );
    assert_eq!(paths[2].1, JournalDirectoryNodeKind::File);
    assert!(paths.iter().all(|entry| !entry.2.is_empty()));
    assert!(
        pinned
            .entries
            .iter()
            .filter(|entry| entry.node_kind == JournalDirectoryNodeKind::File)
            .all(|entry| entry.content_fact.starts_with("sha256:"))
    );

    assert!(std::fs::rename(root.join("root.txt"), root.join("renamed.txt")).is_err());
    drop(pinned);
    std::fs::rename(root.join("root.txt"), root.join("renamed.txt")).unwrap();
}

#[cfg(windows)]
#[test]
fn pinned_source_tree_iterative_dfs_handles_sixty_levels_with_hashing() {
    use crate::operations::journal::JournalDirectoryNodeKind;
    use sha2::Digest;
    use std::io::{Read, Seek, SeekFrom};

    let fixture = local_ntfs_fixture();
    let root = fixture.path().join("deep");
    std::fs::create_dir(&root).unwrap();

    let depth = 60;
    let mut leaf_parent = root.clone();
    for _ in 0..depth {
        leaf_parent.push("d");
        std::fs::create_dir(&leaf_parent).unwrap();
    }
    let leaf_path = leaf_parent.join("f");
    let payload = b"iterative traversal payload";
    std::fs::write(&leaf_path, payload).unwrap();

    let mut pinned = windows::preflight_pinned_source_tree(&root, &AtomicBool::new(false)).unwrap();
    assert_eq!(pinned.entries.len(), depth + 1);
    for (index, entry) in pinned.entries.iter().take(depth).enumerate() {
        assert_eq!(entry.node_kind, JournalDirectoryNodeKind::Directory);
        assert_eq!(entry.relative_components.len(), index + 1);
        assert!(
            entry
                .relative_components
                .iter()
                .all(|name| name == &[b'd' as u16])
        );
    }
    let leaf = pinned.entries.last().unwrap();
    assert_eq!(leaf.node_kind, JournalDirectoryNodeKind::File);
    assert_eq!(leaf.relative_components.len(), depth + 1);
    assert_eq!(leaf.relative_components.last().unwrap(), &[b'f' as u16]);
    let expected_hash = format!("sha256:{:x}", sha2::Sha256::digest(payload));
    assert_eq!(leaf.content_fact, expected_hash);

    let handle_index = leaf.handle_index;
    let Some(windows::PinnedSourceHandle::File(file)) = pinned._handles[handle_index].as_mut()
    else {
        panic!("deep leaf should retain its opened file handle");
    };
    assert_eq!(file.stream_position().unwrap(), payload.len() as u64);
    file.seek(SeekFrom::Start(0)).unwrap();
    let mut held_content = Vec::new();
    file.read_to_end(&mut held_content).unwrap();
    assert_eq!(held_content, payload);

    drop(pinned);
    std::fs::rename(&leaf_path, leaf_parent.join("released"))
        .expect("dropping the tree must release the deep file pin");
}

#[cfg(windows)]
#[test]
fn pinned_source_tree_stages_two_level_contents_from_held_handles() {
    let fixture = local_ntfs_fixture();
    let staging_fixture = local_ntfs_fixture();
    let root = fixture.path().join("source");
    let staging = staging_fixture.path().join("staging");
    std::fs::create_dir(&root).unwrap();
    std::fs::create_dir(root.join("nested")).unwrap();
    std::fs::create_dir(root.join("empty")).unwrap();
    std::fs::write(root.join("root.txt"), b"root bytes").unwrap();
    std::fs::write(root.join("nested").join("leaf.bin"), b"leaf bytes").unwrap();
    let mut pinned = windows::preflight_pinned_source_tree(&root, &AtomicBool::new(false)).unwrap();
    let held_file = pinned
        .entries
        .iter()
        .find(|entry| {
            entry.relative_components == vec!["root.txt".encode_utf16().collect::<Vec<_>>()]
        })
        .unwrap()
        .handle_index;
    let source_path = root.join("root.txt");
    let moved_aside = root.join("original.txt");
    // The no-delete-sharing source pin blocks a path rename/reuse while the
    // copy reads the already captured handle.
    assert!(std::fs::rename(&source_path, &moved_aside).is_err());
    let staging_lease = windows::create_attempt_staging_root(&staging).unwrap();
    let staged =
        windows::stage_pinned_source_tree(&mut pinned, staging_lease, &AtomicBool::new(false))
            .unwrap();
    assert_eq!(
        std::fs::read(staging.join("root.txt")).unwrap(),
        b"root bytes"
    );
    assert_eq!(
        std::fs::read(staging.join("nested").join("leaf.bin")).unwrap(),
        b"leaf bytes"
    );
    assert!(staging.join("nested").is_dir());
    assert_eq!(std::fs::read(&source_path).unwrap(), b"root bytes");
    assert!(std::fs::read(moved_aside).is_err());
    assert!(!staged.root_identity.is_empty());
    assert_eq!(staged.nodes.len(), pinned.entries.len());
    assert!(staged.nodes.iter().all(|node| !node.identity.is_empty()));
    let moved_root = fixture.path().join("staging-renamed");
    assert!(std::fs::rename(&staging, &moved_root).is_err());
    assert!(std::os::windows::fs::symlink_dir(fixture.path().join("source"), &staging).is_err());
    assert!(matches!(
        pinned._handles[held_file],
        Some(windows::PinnedSourceHandle::File(_))
    ));
}

#[cfg(windows)]
#[test]
fn pinned_source_tree_stage_collision_fails_without_changing_source() {
    let fixture = local_ntfs_fixture();
    let root = fixture.path().join("source");
    let staging = fixture.path().join("staging");
    std::fs::create_dir(&root).unwrap();
    std::fs::write(root.join("file.txt"), b"untouched").unwrap();
    std::fs::create_dir(&staging).unwrap();
    std::fs::write(staging.join("collision"), b"owned by attempt").unwrap();
    let _pinned = windows::preflight_pinned_source_tree(&root, &AtomicBool::new(false)).unwrap();

    assert!(windows::create_attempt_staging_root(&staging).is_err());
    assert_eq!(std::fs::read(root.join("file.txt")).unwrap(), b"untouched");
    assert_eq!(
        std::fs::read(staging.join("collision")).unwrap(),
        b"owned by attempt"
    );
    assert!(!staging.join("file.txt").exists());
}

#[cfg(windows)]
#[test]
fn pinned_source_tree_stage_cancellation_after_a_chunk_keeps_source_intact() {
    let fixture = local_ntfs_fixture();
    let staging_fixture = local_ntfs_fixture();
    let root = fixture.path().join("source");
    let staging = staging_fixture.path().join("staging");
    let source = root.join("large.bin");
    let bytes = vec![0x5a; 1024 * 1024];
    std::fs::create_dir(&root).unwrap();
    std::fs::write(&source, &bytes).unwrap();
    let mut pinned = windows::preflight_pinned_source_tree(&root, &AtomicBool::new(false)).unwrap();
    let cancelled = AtomicBool::new(false);
    let staging_lease = windows::create_attempt_staging_root(&staging).unwrap();

    let result = windows::stage_pinned_source_tree_with_chunk_hook(
        &mut pinned,
        staging_lease,
        &cancelled,
        || cancelled.store(true, Ordering::Release),
    );
    assert!(matches!(result, Err(CopyError::Cancelled)));
    assert_eq!(std::fs::read(source).unwrap(), bytes);
    assert!(!staging.exists(), "cancelled staging tree must be removed");
}

#[cfg(windows)]
#[test]
fn directory_move_manifest_exact_durable_ack_is_required_before_publish() {
    let fixture = local_ntfs_fixture();
    let (source, stage_path, destination) = directory_move_paths(&fixture);
    let (token, _) = directory_move_test_tokens(&source, destination.parent().unwrap());
    let cancelled = std::sync::Arc::new(AtomicBool::new(false));
    let (facts, controls, worker) = spawn_manifest_barrier(
        token,
        source.clone(),
        stage_path,
        destination.clone(),
        cancelled,
    );
    let ExecutorFact::DirectoryMoveManifestIntent {
        token: fact_token,
        ledger,
    } = facts.recv().unwrap()
    else {
        panic!("worker must emit the manifest intent before waiting");
    };
    assert_eq!(fact_token, token);
    assert_eq!(ledger.item, 0);
    assert_eq!(
        ledger.source,
        crate::operations::journal::JournalPath::from_path(&source)
    );
    assert_eq!(
        ledger.destination,
        crate::operations::journal::JournalPath::from_path(&destination)
    );
    let root = ledger.root.as_ref().expect("captured root identities");
    assert!(!root.source_identity.is_empty());
    assert!(!root.destination_identity.is_empty());
    assert!(!root.disposition_recorded);
    assert!(ledger.children.iter().all(|child| {
        !child.source_identity.is_empty()
            && !child.destination_identity.is_empty()
            && !child.content_fact.is_empty()
            && !child.disposition_recorded
    }));
    assert!(!destination.exists(), "root stays staged before exact ack");
    use crate::operations::journal::{
        JournalAttempt, JournalKind, JournalPath, JournalState, JournalStore, JournalWriter,
        RecoveryItem,
    };
    let journal_fixture = tempfile::tempdir().unwrap();
    let journal_path = journal_fixture.path().join("journal.json");
    let journal = JournalWriter::start(JournalStore::open(journal_path.clone()).unwrap());
    let key = format!("{}:{}", token.job_id().value(), token.attempt_id().value());
    let record = JournalAttempt {
        created_folder_path: None,
        created_archive_path: None,
        zip_create: None,
        seven_zip_create: None,
        seven_zip_create_handles: None,
        seven_zip_extract_batch: None,
        seven_zip_extract_receipts: Vec::new(),
        zip_extract: None,
        zip_extract_items: Vec::new(),
        zip_extract_receipts: Vec::new(),
        key: key.clone(),
        kind: JournalKind::Move,
        state: JournalState::Running,
        sources: vec![ledger.source.clone()],
        destination: Some(JournalPath::from_path(destination.parent().unwrap())),
        batch_rename_plan: Vec::new(),
        batch_rename_completed: Vec::new(),
        replace_backup: None,
        cross_volume_move_replace: None,
        directory_move_replace_rename: None,
        rename_stage: None,
        directory_moves: Vec::new(),
        copy_replace_cleanups: Vec::new(),
        copy_directory_publications: Vec::new(),
        copy_directory_stage: None,
        receipts_recorded: false,
        virtual_source_name: None,
        virtual_source_size: None,
        virtual_sources: Vec::new(),
        virtual_item_status: Vec::new(),
        terminal_outcome: None,
    };
    let journal_result = journal.upsert_with_reply(record).recv_blocking().unwrap();
    assert!(journal_result.is_ok(), "{journal_result:?}");
    assert!(
        journal
            .register_directory_move(key, ledger.clone())
            .recv_blocking()
            .unwrap()
            .is_ok()
    );
    let reopened = JournalStore::open(journal_path).unwrap();
    assert!(matches!(
        reopened.recoveries().as_slice(),
        [RecoveryItem::RecoveryRequired(attempt)]
            if attempt.directory_moves.as_slice() == [ledger.clone()]
    ));
    controls
        .send(WorkerControl::DirectoryMoveManifestJournaledExact { token, ledger })
        .unwrap();
    assert!(worker.join().unwrap().is_ok());
    assert!(destination.join("payload.txt").exists());
    assert_eq!(
        std::fs::read(source.join("payload.txt")).unwrap(),
        b"durable barrier payload"
    );
}

#[cfg(windows)]
#[test]
fn cross_volume_directory_move_records_two_item_ledgers_and_keeps_file_semantics() {
    use crate::operations::journal::{
        JournalAttempt, JournalKind, JournalPath, JournalState, JournalStore,
        JournalTerminalOutcome, JournalWriter,
    };

    let Some(destination_volume) = cross_volume_test_root() else {
        return;
    };
    let source_volume = local_ntfs_fixture();
    if !cross_volume_test_has_different_drive(source_volume.path(), &destination_volume) {
        eprintln!("skipping directory Move test: destination must differ from source volume");
        return;
    }
    let Ok(destination_root) = tempfile::Builder::new()
        .prefix("gpui-filer-directory-move-")
        .tempdir_in(&destination_volume)
    else {
        eprintln!("skipping directory Move test: destination volume is not writable");
        return;
    };

    let first = source_volume.path().join("first");
    std::fs::create_dir(&first).unwrap();
    std::fs::create_dir(first.join("nested")).unwrap();
    std::fs::write(first.join("nested/one.bin"), vec![7; 80_000]).unwrap();
    let second = source_volume.path().join("second");
    std::fs::create_dir(&second).unwrap();
    std::fs::write(second.join("two.bin"), vec![9; 72_000]).unwrap();
    let loose_file = source_volume.path().join("loose.txt");
    std::fs::write(&loose_file, b"ordinary file item").unwrap();
    let sources = vec![first.clone(), second.clone(), loose_file.clone()];
    let destination = destination_root.path().to_path_buf();
    let destination_identity = crate::directory::EntrySourceIdentity::from_path(
        &destination,
        crate::directory::EntryKind::Folder,
    )
    .unwrap()
    .filesystem_identity();
    let move_guard = preflight_local_move_guard(&sources, &destination_identity).unwrap();

    let mut service = OperationService::default();
    let token = service
        .submit(OperationRequest {
            kind: OperationKind::Move,
            virtual_source: None,
            sources: sources.clone(),
            destination: Some(destination.clone()),
            batch_rename_plan: None,
            move_identity_guard: Some(move_guard.clone()),
            clipboard_move_source_evidence: None,
            rename_reparse_guard: None,
            move_destination_identity_guard: None,
            move_replace_source_evidence: None,
            trash_source_guards: None,
            source_cleanup_identity_guard: None,
            initial_conflict_policy: None,
            copy_destination_identity_guard: None,
            create_parent_directory_identity_guard: None,
            zip_create_guard: None,
            shortcut_create_guard: None,
            seven_zip_create_guard: None,
            seven_zip_extract_guard: None,
            origin: None,
        })
        .unwrap();
    let key = format!("{}:{}", token.job_id().value(), token.attempt_id().value());
    let journal_fixture = tempfile::tempdir().unwrap();
    let journal_path = journal_fixture.path().join("journal.json");
    let writer = JournalWriter::start(JournalStore::open(journal_path.clone()).unwrap());
    let mut initial = JournalAttempt {
        created_folder_path: None,
        created_archive_path: None,
        zip_create: None,
        seven_zip_create: None,
        seven_zip_create_handles: None,
        seven_zip_extract_batch: None,
        seven_zip_extract_receipts: Vec::new(),
        zip_extract: None,
        zip_extract_items: Vec::new(),
        zip_extract_receipts: Vec::new(),
        key: key.clone(),
        kind: JournalKind::Move,
        state: JournalState::Running,
        sources: sources
            .iter()
            .map(|path| JournalPath::from_path(path))
            .collect(),
        destination: Some(JournalPath::from_path(&destination)),
        batch_rename_plan: Vec::new(),
        batch_rename_completed: Vec::new(),
        replace_backup: None,
        cross_volume_move_replace: None,
        directory_move_replace_rename: None,
        rename_stage: None,
        directory_moves: Vec::new(),
        copy_replace_cleanups: Vec::new(),
        copy_directory_publications: Vec::new(),
        copy_directory_stage: None,
        receipts_recorded: false,
        virtual_source_name: None,
        virtual_source_size: None,
        virtual_sources: Vec::new(),
        virtual_item_status: Vec::new(),
        terminal_outcome: None,
    };
    assert!(
        writer
            .upsert_with_reply(initial.clone())
            .recv_blocking()
            .unwrap()
            .is_ok()
    );

    let (control_sender, controls) = std::sync::mpsc::channel();
    let mut route_fact = |fact: ExecutorFact| {
        let control = match fact {
            ExecutorFact::DirectoryMoveManifestIntent { token, ledger } => {
                assert!(
                    writer
                        .register_directory_move(key.clone(), ledger.clone())
                        .recv_blocking()
                        .unwrap()
                        .is_ok()
                );
                WorkerControl::DirectoryMoveManifestJournaledExact { token, ledger }
            }
            ExecutorFact::DirectoryMoveChildIntent {
                token,
                item,
                intent,
            } => {
                assert!(
                    writer
                        .record_directory_move_intent(key.clone(), item.0, intent.clone())
                        .recv_blocking()
                        .unwrap()
                        .is_ok()
                );
                WorkerControl::DirectoryMoveChildIntentJournaledExact {
                    token,
                    item,
                    intent,
                }
            }
            ExecutorFact::DirectoryMoveChildDisposition {
                token,
                item,
                intent,
            } => {
                assert!(
                    writer
                        .record_directory_move_receipt(key.clone(), item.0, intent.clone())
                        .recv_blocking()
                        .unwrap()
                        .is_ok()
                );
                WorkerControl::DirectoryMoveChildReceiptJournaledExact {
                    token,
                    item,
                    intent,
                }
            }
            ExecutorFact::DirectoryMoveRootIntent {
                token,
                item,
                intent,
            } => {
                assert!(
                    writer
                        .record_directory_move_root_intent(key.clone(), item.0, intent.clone())
                        .recv_blocking()
                        .unwrap()
                        .is_ok()
                );
                WorkerControl::DirectoryMoveRootIntentJournaledExact {
                    token,
                    item,
                    intent,
                }
            }
            ExecutorFact::DirectoryMoveRootDisposition {
                token,
                item,
                intent,
            } => {
                assert!(
                    writer
                        .record_directory_move_root_receipt(key.clone(), item.0, intent.clone())
                        .recv_blocking()
                        .unwrap()
                        .is_ok()
                );
                WorkerControl::DirectoryMoveRootReceiptJournaledExact {
                    token,
                    item,
                    intent,
                }
            }
            ExecutorFact::DirectoryMoveComplete { token, item } => {
                assert!(
                    writer
                        .complete_directory_move(key.clone(), item.0)
                        .recv_blocking()
                        .unwrap()
                        .is_ok()
                );
                WorkerControl::DirectoryMoveCompleteJournaledExact { token, item }
            }
            other => panic!("unexpected directory Move fact: {other:?}"),
        };
        control_sender.send(control).unwrap();
    };
    let mut staged_bytes = 0_u64;
    for (item, source) in [(ItemId(0), &first), (ItemId(1), &second)] {
        let destination_path = destination.join(source.file_name().unwrap());
        windows::move_cross_volume_directory(
            token,
            item,
            source,
            &destination_path,
            &move_guard.source_identities[item.0 as usize],
            &destination_identity,
            &AtomicBool::new(false),
            &controls,
            &mut |bytes| staged_bytes = staged_bytes.saturating_add(bytes),
            &mut route_fact,
        )
        .unwrap();
    }
    move_file(
        &loose_file,
        &destination.join("loose.txt"),
        &AtomicBool::new(false),
        |_| {},
    )
    .unwrap();
    assert_eq!(staged_bytes, 152_000);
    assert!(!first.exists() && !second.exists() && !loose_file.exists());
    assert_eq!(
        std::fs::read(destination.join("first/nested/one.bin"))
            .unwrap()
            .len(),
        80_000
    );
    assert_eq!(
        std::fs::read(destination.join("second/two.bin"))
            .unwrap()
            .len(),
        72_000
    );
    assert_eq!(
        std::fs::read(destination.join("loose.txt")).unwrap(),
        b"ordinary file item"
    );

    initial.state = JournalState::Terminal;
    initial.receipts_recorded = true;
    initial.terminal_outcome = Some(JournalTerminalOutcome::Succeeded);
    assert!(
        writer
            .upsert_with_reply(initial)
            .recv_blocking()
            .unwrap()
            .is_ok()
    );
    drop(writer);
    assert!(
        JournalStore::open(journal_path)
            .unwrap()
            .recoveries()
            .is_empty()
    );
}

#[cfg(windows)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RootIntentAckMode {
    ExactWithExternalChild,
    Mismatched,
    MismatchedReceipt,
    ReceiptPersistenceFailure,
}

#[cfg(windows)]
#[test]
fn cross_volume_directory_move_root_delete_failure_keeps_durable_partial_state() {
    run_cross_volume_directory_move_root_intent_ack_case(RootIntentAckMode::ExactWithExternalChild);
}

#[cfg(windows)]
#[test]
fn cross_volume_directory_move_rejects_mismatched_root_intent_ack() {
    run_cross_volume_directory_move_root_intent_ack_case(RootIntentAckMode::Mismatched);
}

#[cfg(windows)]
#[test]
fn cross_volume_directory_move_rejects_mismatched_root_receipt_ack() {
    run_cross_volume_directory_move_root_intent_ack_case(RootIntentAckMode::MismatchedReceipt);
}

#[cfg(windows)]
#[test]
fn cross_volume_directory_move_root_receipt_persist_failure_keeps_pending_intent() {
    run_cross_volume_directory_move_root_intent_ack_case(
        RootIntentAckMode::ReceiptPersistenceFailure,
    );
}

#[cfg(windows)]
fn run_cross_volume_directory_move_root_intent_ack_case(mode: RootIntentAckMode) {
    use crate::operations::journal::{
        JournalAttempt, JournalDirectoryChildIntent, JournalDirectoryNodeKind,
        JournalDirectoryRootIntent, JournalKind, JournalPath, JournalState, JournalStore,
        JournalWriter, RecoveryItem,
    };

    let Some(destination_volume) = cross_volume_test_root() else {
        return;
    };
    let source_volume = local_ntfs_fixture();
    if !cross_volume_test_has_different_drive(source_volume.path(), &destination_volume) {
        eprintln!(
            "skipping directory Move root-failure test: destination must differ from source volume"
        );
        return;
    }
    let destination_prefix = match mode {
        RootIntentAckMode::ExactWithExternalChild => "gpui-filer-directory-move-root-failure-",
        RootIntentAckMode::Mismatched => "gpui-filer-directory-move-root-ack-mismatch-",
        RootIntentAckMode::MismatchedReceipt => {
            "gpui-filer-directory-move-root-receipt-ack-mismatch-"
        }
        RootIntentAckMode::ReceiptPersistenceFailure => {
            "gpui-filer-directory-move-root-receipt-persist-failure-"
        }
    };
    let Ok(destination_root) = tempfile::Builder::new()
        .prefix(destination_prefix)
        .tempdir_in(&destination_volume)
    else {
        eprintln!(
            "skipping directory Move root-intent ACK test: destination volume is not writable"
        );
        return;
    };

    let source = source_volume.path().join("source-tree");
    std::fs::create_dir(&source).unwrap();
    let child = source.join("child.bin");
    let child_bytes = vec![0x5a; 4096];
    std::fs::write(&child, &child_bytes).unwrap();
    let external = source.join("appeared-after-manifest.bin");
    let destination = destination_root.path().to_path_buf();
    let destination_identity = crate::directory::EntrySourceIdentity::from_path(
        &destination,
        crate::directory::EntryKind::Folder,
    )
    .unwrap()
    .filesystem_identity();
    let sources = vec![source.clone()];
    let move_guard = preflight_local_move_guard(&sources, &destination_identity).unwrap();

    let mut service = OperationService::default();
    let token = service
        .submit(OperationRequest {
            kind: OperationKind::Move,
            virtual_source: None,
            sources: sources.clone(),
            destination: Some(destination.clone()),
            batch_rename_plan: None,
            move_identity_guard: Some(move_guard.clone()),
            clipboard_move_source_evidence: None,
            rename_reparse_guard: None,
            move_destination_identity_guard: None,
            move_replace_source_evidence: None,
            trash_source_guards: None,
            source_cleanup_identity_guard: None,
            initial_conflict_policy: None,
            copy_destination_identity_guard: None,
            create_parent_directory_identity_guard: None,
            zip_create_guard: None,
            shortcut_create_guard: None,
            seven_zip_create_guard: None,
            seven_zip_extract_guard: None,
            origin: None,
        })
        .unwrap();
    let key = format!("{}:{}", token.job_id().value(), token.attempt_id().value());
    let journal_fixture = tempfile::tempdir().unwrap();
    let journal_path = journal_fixture.path().join("journal.json");
    let writer = JournalWriter::start(JournalStore::open(journal_path.clone()).unwrap());
    let initial = JournalAttempt {
        created_folder_path: None,
        created_archive_path: None,
        zip_create: None,
        seven_zip_create: None,
        seven_zip_create_handles: None,
        seven_zip_extract_batch: None,
        seven_zip_extract_receipts: Vec::new(),
        zip_extract: None,
        zip_extract_items: Vec::new(),
        zip_extract_receipts: Vec::new(),
        key: key.clone(),
        kind: JournalKind::Move,
        state: JournalState::Running,
        sources: sources
            .iter()
            .map(|path| JournalPath::from_path(path))
            .collect(),
        destination: Some(JournalPath::from_path(&destination)),
        batch_rename_plan: Vec::new(),
        batch_rename_completed: Vec::new(),
        replace_backup: None,
        cross_volume_move_replace: None,
        directory_move_replace_rename: None,
        rename_stage: None,
        directory_moves: Vec::new(),
        copy_replace_cleanups: Vec::new(),
        copy_directory_publications: Vec::new(),
        copy_directory_stage: None,
        receipts_recorded: false,
        virtual_source_name: None,
        virtual_source_size: None,
        virtual_sources: Vec::new(),
        virtual_item_status: Vec::new(),
        terminal_outcome: None,
    };
    writer
        .upsert_with_reply(initial)
        .recv_blocking()
        .unwrap()
        .unwrap();

    let (control_sender, controls) = std::sync::mpsc::channel();
    let mut injected_external_identity = None;
    let mut observed_child_receipt = false;
    let mut observed_root_intent = false;
    let mut observed_root_disposition = false;
    let mut expected_child_receipt: Option<JournalDirectoryChildIntent> = None;
    let mut expected_root_intent: Option<JournalDirectoryRootIntent> = None;
    let mut receipt_write_error: Option<String> = None;
    let mut journal_bytes_before_failed_receipt: Option<Vec<u8>> = None;
    let mut journal_delete_share_blocker: Option<std::fs::File> = None;
    let mut route_fact = |fact: ExecutorFact| {
        let control = match fact {
            ExecutorFact::DirectoryMoveManifestIntent { token, ledger } => {
                writer
                    .register_directory_move(key.clone(), ledger.clone())
                    .recv_blocking()
                    .unwrap()
                    .unwrap();
                WorkerControl::DirectoryMoveManifestJournaledExact { token, ledger }
            }
            ExecutorFact::DirectoryMoveChildIntent {
                token,
                item,
                intent,
            } => {
                writer
                    .record_directory_move_intent(key.clone(), item.0, intent.clone())
                    .recv_blocking()
                    .unwrap()
                    .unwrap();
                WorkerControl::DirectoryMoveChildIntentJournaledExact {
                    token,
                    item,
                    intent,
                }
            }
            ExecutorFact::DirectoryMoveChildDisposition {
                token,
                item,
                intent,
            } => {
                writer
                    .record_directory_move_receipt(key.clone(), item.0, intent.clone())
                    .recv_blocking()
                    .unwrap()
                    .unwrap();
                observed_child_receipt = true;
                expected_child_receipt = Some(intent.clone());
                WorkerControl::DirectoryMoveChildReceiptJournaledExact {
                    token,
                    item,
                    intent,
                }
            }
            ExecutorFact::DirectoryMoveRootIntent {
                token,
                item,
                intent,
            } => {
                assert!(
                    observed_child_receipt,
                    "root intent must follow a durable child receipt"
                );
                writer
                    .record_directory_move_root_intent(key.clone(), item.0, intent.clone())
                    .recv_blocking()
                    .unwrap()
                    .unwrap();
                observed_root_intent = true;
                expected_root_intent = Some(intent.clone());
                match mode {
                    RootIntentAckMode::ExactWithExternalChild => {
                        std::fs::write(&external, b"external writer").unwrap();
                        injected_external_identity = Some(
                            crate::directory::EntrySourceIdentity::from_path_no_follow(
                                &external,
                                crate::directory::EntryKind::File,
                            )
                            .unwrap()
                            .filesystem_identity(),
                        );
                        WorkerControl::DirectoryMoveRootIntentJournaledExact {
                            token,
                            item,
                            intent,
                        }
                    }
                    RootIntentAckMode::Mismatched => {
                        let mut mismatched_ack = intent;
                        mismatched_ack.source_identity.push_str("-mismatched-ack");
                        WorkerControl::DirectoryMoveRootIntentJournaledExact {
                            token,
                            item,
                            intent: mismatched_ack,
                        }
                    }
                    RootIntentAckMode::MismatchedReceipt => {
                        WorkerControl::DirectoryMoveRootIntentJournaledExact {
                            token,
                            item,
                            intent,
                        }
                    }
                    RootIntentAckMode::ReceiptPersistenceFailure => {
                        WorkerControl::DirectoryMoveRootIntentJournaledExact {
                            token,
                            item,
                            intent,
                        }
                    }
                }
            }
            ExecutorFact::DirectoryMoveRootDisposition {
                token,
                item,
                intent,
            } => {
                observed_root_disposition = true;
                match mode {
                    RootIntentAckMode::MismatchedReceipt => {
                        writer
                            .record_directory_move_root_receipt(key.clone(), item.0, intent.clone())
                            .recv_blocking()
                            .unwrap()
                            .unwrap();
                        let mut mismatched_receipt = intent;
                        mismatched_receipt
                            .source_identity
                            .push_str("-mismatched-receipt");
                        WorkerControl::DirectoryMoveRootReceiptJournaledExact {
                            token,
                            item,
                            intent: mismatched_receipt,
                        }
                    }
                    RootIntentAckMode::ReceiptPersistenceFailure => {
                        use ::windows::Win32::Storage::FileSystem::{
                            FILE_SHARE_READ, FILE_SHARE_WRITE,
                        };
                        use std::os::windows::fs::OpenOptionsExt;

                        let blocker = std::fs::OpenOptions::new()
                            .read(true)
                            .write(true)
                            .share_mode(FILE_SHARE_READ.0 | FILE_SHARE_WRITE.0)
                            .open(&journal_path)
                            .unwrap();
                        let before = std::fs::read(&journal_path).unwrap();
                        let result = writer
                            .record_directory_move_root_receipt(key.clone(), item.0, intent)
                            .recv_blocking()
                            .unwrap();
                        let Err(error) = result else {
                            panic!("delete-share blocker should reject ReplaceFileW");
                        };
                        assert!(
                            error.contains("replace failed"),
                            "root receipt should fail at journal publication: {error}"
                        );
                        assert!(blocker.metadata().is_ok());
                        journal_bytes_before_failed_receipt = Some(before.clone());
                        assert_eq!(std::fs::read(&journal_path).unwrap(), before);
                        receipt_write_error = Some(error);
                        journal_delete_share_blocker = Some(blocker);
                        assert!(journal_delete_share_blocker.is_some());
                        WorkerControl::Cancel
                    }
                    _ => panic!("root disposition is unexpected for mode {mode:?}"),
                }
            }
            other => panic!("unexpected directory Move fact: {other:?}"),
        };
        control_sender.send(control).unwrap();
    };

    let destination_path = destination.join("source-tree");
    let result = windows::move_cross_volume_directory(
        token,
        ItemId(0),
        &source,
        &destination_path,
        &move_guard.source_identities[0],
        &destination_identity,
        &AtomicBool::new(false),
        &controls,
        &mut |_| {},
        &mut route_fact,
    );
    drop(route_fact);
    assert!(
        matches!(result, Err(CopyError::Partial(_))),
        "unexpected result: {result:?}"
    );
    assert!(observed_root_intent);
    assert_eq!(
        observed_root_disposition,
        matches!(
            mode,
            RootIntentAckMode::MismatchedReceipt | RootIntentAckMode::ReceiptPersistenceFailure
        )
    );
    assert!(
        !child.exists(),
        "the receipted manifested child should be deleted"
    );
    if matches!(
        mode,
        RootIntentAckMode::MismatchedReceipt | RootIntentAckMode::ReceiptPersistenceFailure
    ) {
        assert!(
            !source.exists(),
            "the disposed source root should be absent"
        );
    } else {
        assert!(
            source.is_dir(),
            "failed root deletion must retain the source directory"
        );
        assert_eq!(
            crate::directory::EntrySourceIdentity::from_path(
                &source,
                crate::directory::EntryKind::Folder,
            )
            .unwrap()
            .filesystem_identity(),
            move_guard.source_identities[0]
        );
    }
    match mode {
        RootIntentAckMode::ExactWithExternalChild => {
            let external_identity_after =
                crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &external,
                    crate::directory::EntryKind::File,
                )
                .unwrap()
                .filesystem_identity();
            assert_eq!(injected_external_identity, Some(external_identity_after));
        }
        RootIntentAckMode::Mismatched => assert_eq!(std::fs::read_dir(&source).unwrap().count(), 0),
        RootIntentAckMode::MismatchedReceipt | RootIntentAckMode::ReceiptPersistenceFailure => {}
    }
    assert_eq!(
        std::fs::read(destination_path.join("child.bin")).unwrap(),
        child_bytes
    );

    if mode == RootIntentAckMode::ReceiptPersistenceFailure {
        assert!(
            receipt_write_error
                .as_deref()
                .is_some_and(|error| error.contains("replace failed")),
            "root receipt publication failure should be observed"
        );
        let journal_bytes_after_failed_receipt = std::fs::read(&journal_path).unwrap();
        assert_eq!(
            journal_bytes_after_failed_receipt.as_slice(),
            journal_bytes_before_failed_receipt
                .as_deref()
                .expect("journal bytes should be snapshotted before failed receipt")
        );
        assert!(journal_delete_share_blocker.is_some());
        drop(journal_delete_share_blocker.take());
    }
    drop(writer);

    let reopened = JournalStore::open(journal_path.clone()).unwrap();
    let recoveries = reopened.recoveries();
    let [RecoveryItem::RecoveryRequired(record)] = recoveries.as_slice() else {
        panic!("incomplete directory Move must reopen as recovery-required");
    };
    assert_eq!(record.key, key);
    assert_eq!(record.state, JournalState::RecoveryRequired);
    assert_eq!(record.terminal_outcome, None);
    let [ledger] = record.directory_moves.as_slice() else {
        panic!("reopened journal must retain exactly one directory manifest");
    };
    assert_eq!(ledger.item, 0);
    assert_eq!(ledger.pending, None);
    assert!(!ledger.cleanup_complete);
    assert_eq!(ledger.children.len(), 1);
    assert_eq!(ledger.children[0].node_kind, JournalDirectoryNodeKind::File);
    assert!(ledger.children[0].disposition_recorded);
    let child_receipt = expected_child_receipt.expect("child receipt should be observed");
    let destination_child_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
        &destination_path.join("child.bin"),
        crate::directory::EntryKind::File,
    )
    .unwrap()
    .filesystem_identity();
    assert_eq!(ledger.children[0].ordinal, child_receipt.ordinal);
    assert_eq!(
        ledger.children[0].relative_components,
        child_receipt.relative_components
    );
    assert_eq!(
        ledger.children[0].source_identity,
        child_receipt.source_identity
    );
    assert_eq!(
        ledger.children[0].destination_identity,
        child_receipt.destination_identity
    );
    assert_eq!(ledger.children[0].content_fact, child_receipt.content_fact);
    let (destination_volume, destination_index) =
        destination_child_identity.windows_parts().unwrap();
    assert_eq!(
        format!("{destination_volume}:{destination_index:016x}"),
        child_receipt.destination_identity
    );
    let root = ledger
        .root
        .as_ref()
        .expect("root intent should be journaled");
    if mode == RootIntentAckMode::MismatchedReceipt {
        assert_eq!(root.pending, None);
        assert!(root.disposition_recorded);
        let original_root_intent = expected_root_intent
            .as_ref()
            .expect("original root intent should be retained");
        assert_eq!(root.source_identity, original_root_intent.source_identity);
        assert_eq!(
            root.destination_identity,
            original_root_intent.destination_identity
        );
        assert!(!source.exists());
    } else if mode == RootIntentAckMode::ReceiptPersistenceFailure {
        assert_eq!(root.pending, expected_root_intent);
        assert!(!root.disposition_recorded);
        let original_root_intent = expected_root_intent
            .as_ref()
            .expect("original root intent should be retained");
        assert_eq!(root.source_identity, original_root_intent.source_identity);
        assert_eq!(
            root.destination_identity,
            original_root_intent.destination_identity
        );
        assert!(!source.exists());
    } else {
        assert_eq!(root.pending, expected_root_intent);
        assert!(!root.disposition_recorded);
        assert!(source.is_dir());
    }
    assert!(!child.exists());
    if mode == RootIntentAckMode::ExactWithExternalChild {
        assert_eq!(std::fs::read(&external).unwrap(), b"external writer");
    }
    assert_eq!(
        std::fs::read(destination_path.join("child.bin")).unwrap(),
        child_bytes
    );
    let reopened_again = JournalStore::open(journal_path.clone()).unwrap();
    let reopened_again_recoveries = reopened_again.recoveries();
    let [RecoveryItem::RecoveryRequired(reopened_again_record)] =
        reopened_again_recoveries.as_slice()
    else {
        panic!("second reopen must remain recovery-required");
    };
    assert_eq!(reopened_again_record.state, JournalState::RecoveryRequired);
    assert_eq!(reopened_again_record.terminal_outcome, None);
    let [reopened_again_ledger] = reopened_again_record.directory_moves.as_slice() else {
        panic!("second reopen must retain exactly one directory manifest");
    };
    assert_eq!(reopened_again_ledger, ledger);
    assert_eq!(reopened_again_ledger.pending, None);
    assert!(!reopened_again_ledger.cleanup_complete);
    assert_eq!(reopened_again_ledger.children.len(), 1);
    assert!(reopened_again_ledger.children[0].disposition_recorded);
    let reopened_again_root = reopened_again_ledger
        .root
        .as_ref()
        .expect("second reopen must retain the root record");
    if mode == RootIntentAckMode::MismatchedReceipt {
        assert_eq!(reopened_again_root.pending, None);
        assert!(reopened_again_root.disposition_recorded);
        let original_root_intent = expected_root_intent
            .as_ref()
            .expect("original root intent should be retained");
        assert_eq!(
            reopened_again_root.source_identity,
            original_root_intent.source_identity
        );
        assert_eq!(
            reopened_again_root.destination_identity,
            original_root_intent.destination_identity
        );
    } else if mode == RootIntentAckMode::ReceiptPersistenceFailure {
        assert_eq!(reopened_again_root.pending, expected_root_intent);
        assert!(!reopened_again_root.disposition_recorded);
        let original_root_intent = expected_root_intent
            .as_ref()
            .expect("original root intent should be retained");
        assert_eq!(
            reopened_again_root.source_identity,
            original_root_intent.source_identity
        );
        assert_eq!(
            reopened_again_root.destination_identity,
            original_root_intent.destination_identity
        );
    }
    assert_eq!(
        source.exists(),
        !matches!(
            mode,
            RootIntentAckMode::MismatchedReceipt | RootIntentAckMode::ReceiptPersistenceFailure
        )
    );
    assert!(!child.exists());
    if mode == RootIntentAckMode::ExactWithExternalChild {
        assert_eq!(std::fs::read(&external).unwrap(), b"external writer");
    }
    assert_eq!(
        std::fs::read(destination_path.join("child.bin")).unwrap(),
        child_bytes
    );
    assert_eq!(
        crate::directory::EntrySourceIdentity::from_path_no_follow(
            &destination_path.join("child.bin"),
            crate::directory::EntryKind::File,
        )
        .unwrap()
        .filesystem_identity(),
        destination_child_identity
    );
}

#[cfg(windows)]
const DIRECTORY_MOVE_RECEIPT_CRASH_CHILD_ENV: &str =
    "GPUI_FILER_DIRECTORY_MOVE_RECEIPT_CRASH_CHILD";

#[cfg(windows)]
const DIRECTORY_MOVE_CRASH_BOUNDARY_ENV: &str = "GPUI_FILER_DIRECTORY_MOVE_CRASH_BOUNDARY";

#[cfg(windows)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum DirectoryMoveCrashBoundary {
    RootReceipt,
    Complete,
}

#[cfg(windows)]
fn directory_move_root_receipt_crash_child() {
    use crate::operations::journal::{
        JournalAttempt, JournalDirectoryChildIntent, JournalDirectoryRootIntent, JournalKind,
        JournalPath, JournalState, JournalStore, JournalWriter,
    };
    let source = PathBuf::from(std::env::var_os("GPUI_FILER_DIRECTORY_MOVE_CRASH_SOURCE").unwrap());
    let destination_root = PathBuf::from(
        std::env::var_os("GPUI_FILER_DIRECTORY_MOVE_CRASH_DESTINATION_ROOT").unwrap(),
    );
    let journal_path =
        PathBuf::from(std::env::var_os("GPUI_FILER_DIRECTORY_MOVE_CRASH_JOURNAL").unwrap());
    let checkpoint_path =
        PathBuf::from(std::env::var_os("GPUI_FILER_DIRECTORY_MOVE_CRASH_CHECKPOINT").unwrap());
    let boundary = match std::env::var(DIRECTORY_MOVE_CRASH_BOUNDARY_ENV).as_deref() {
        Ok("root-receipt") => DirectoryMoveCrashBoundary::RootReceipt,
        Ok("complete") => DirectoryMoveCrashBoundary::Complete,
        other => panic!("unexpected directory Move crash boundary: {other:?}"),
    };
    let destination_identity = crate::directory::EntrySourceIdentity::from_path(
        &destination_root,
        crate::directory::EntryKind::Folder,
    )
    .unwrap()
    .filesystem_identity();
    let sources = vec![source.clone()];
    let move_guard = preflight_local_move_guard(&sources, &destination_identity).unwrap();
    let mut service = OperationService::default();
    let token = service
        .submit(OperationRequest {
            kind: OperationKind::Move,
            virtual_source: None,
            sources: sources.clone(),
            destination: Some(destination_root.clone()),
            batch_rename_plan: None,
            move_identity_guard: Some(move_guard.clone()),
            clipboard_move_source_evidence: None,
            rename_reparse_guard: None,
            move_destination_identity_guard: None,
            move_replace_source_evidence: None,
            trash_source_guards: None,
            source_cleanup_identity_guard: None,
            initial_conflict_policy: None,
            copy_destination_identity_guard: None,
            create_parent_directory_identity_guard: None,
            zip_create_guard: None,
            shortcut_create_guard: None,
            seven_zip_create_guard: None,
            seven_zip_extract_guard: None,
            origin: None,
        })
        .unwrap();
    let key = format!("{}:{}", token.job_id().value(), token.attempt_id().value());
    let writer = JournalWriter::start(JournalStore::open(journal_path).unwrap());
    writer
        .upsert_with_reply(JournalAttempt {
            created_folder_path: None,
            created_archive_path: None,
            zip_create: None,
            seven_zip_create: None,
            seven_zip_create_handles: None,
            seven_zip_extract_batch: None,
            seven_zip_extract_receipts: Vec::new(),
            zip_extract: None,
            zip_extract_items: Vec::new(),
            zip_extract_receipts: Vec::new(),
            key: key.clone(),
            kind: JournalKind::Move,
            state: JournalState::Running,
            sources: sources
                .iter()
                .map(|path| JournalPath::from_path(path))
                .collect(),
            destination: Some(JournalPath::from_path(&destination_root)),
            batch_rename_plan: Vec::new(),
            batch_rename_completed: Vec::new(),
            replace_backup: None,
            cross_volume_move_replace: None,
            directory_move_replace_rename: None,
            rename_stage: None,
            directory_moves: Vec::new(),
            copy_replace_cleanups: Vec::new(),
            copy_directory_publications: Vec::new(),
            copy_directory_stage: None,
            receipts_recorded: false,
            virtual_source_name: None,
            virtual_source_size: None,
            virtual_sources: Vec::new(),
            virtual_item_status: Vec::new(),
            terminal_outcome: None,
        })
        .recv_blocking()
        .unwrap()
        .unwrap();

    let (control_sender, controls) = std::sync::mpsc::channel();
    let mut child_receipt: Option<JournalDirectoryChildIntent> = None;
    let mut root_intent: Option<JournalDirectoryRootIntent> = None;
    let mut route_fact = |fact: ExecutorFact| {
        let control = match fact {
            ExecutorFact::DirectoryMoveManifestIntent { token, ledger } => {
                writer
                    .register_directory_move(key.clone(), ledger.clone())
                    .recv_blocking()
                    .unwrap()
                    .unwrap();
                WorkerControl::DirectoryMoveManifestJournaledExact { token, ledger }
            }
            other => match other {
                ExecutorFact::DirectoryMoveChildIntent {
                    token,
                    item,
                    intent,
                } => {
                    writer
                        .record_directory_move_intent(key.clone(), item.0, intent.clone())
                        .recv_blocking()
                        .unwrap()
                        .unwrap();
                    WorkerControl::DirectoryMoveChildIntentJournaledExact {
                        token,
                        item,
                        intent,
                    }
                }
                ExecutorFact::DirectoryMoveChildDisposition {
                    token,
                    item,
                    intent,
                } => {
                    writer
                        .record_directory_move_receipt(key.clone(), item.0, intent.clone())
                        .recv_blocking()
                        .unwrap()
                        .unwrap();
                    child_receipt = Some(intent.clone());
                    WorkerControl::DirectoryMoveChildReceiptJournaledExact {
                        token,
                        item,
                        intent,
                    }
                }
                ExecutorFact::DirectoryMoveRootIntent {
                    token,
                    item,
                    intent,
                } => {
                    writer
                        .record_directory_move_root_intent(key.clone(), item.0, intent.clone())
                        .recv_blocking()
                        .unwrap()
                        .unwrap();
                    root_intent = Some(intent.clone());
                    WorkerControl::DirectoryMoveRootIntentJournaledExact {
                        token,
                        item,
                        intent,
                    }
                }
                ExecutorFact::DirectoryMoveRootDisposition {
                    token,
                    item,
                    intent,
                } => {
                    writer
                        .record_directory_move_root_receipt(key.clone(), item.0, intent.clone())
                        .recv_blocking()
                        .unwrap()
                        .unwrap();
                    let receipt = (
                        key.clone(),
                        root_intent
                            .as_ref()
                            .expect("root intent should precede its receipt"),
                        child_receipt
                            .as_ref()
                            .expect("child receipt should precede root receipt"),
                    );
                    if boundary == DirectoryMoveCrashBoundary::RootReceipt {
                        write_directory_move_crash_checkpoint(&checkpoint_path, &receipt);
                        let (_release_sender, release_receiver) = std::sync::mpsc::channel::<()>();
                        let _ = release_receiver.recv();
                    }
                    WorkerControl::DirectoryMoveRootReceiptJournaledExact {
                        token,
                        item,
                        intent,
                    }
                }
                ExecutorFact::DirectoryMoveComplete { token, item } => {
                    if boundary != DirectoryMoveCrashBoundary::Complete {
                        panic!("worker must not complete before the exact root receipt ACK");
                    }
                    writer
                        .complete_directory_move(key.clone(), item.0)
                        .recv_blocking()
                        .unwrap()
                        .unwrap();
                    let receipt = (
                        key.clone(),
                        root_intent
                            .as_ref()
                            .expect("root intent should precede completion"),
                        child_receipt
                            .as_ref()
                            .expect("child receipt should precede completion"),
                    );
                    write_directory_move_crash_checkpoint(&checkpoint_path, &receipt);
                    let (_release_sender, release_receiver) = std::sync::mpsc::channel::<()>();
                    let _ = release_receiver.recv();
                    WorkerControl::DirectoryMoveCompleteJournaledExact { token, item }
                }
                other => panic!("unexpected directory Move crash-child fact: {other:?}"),
            },
        };
        control_sender.send(control).unwrap();
    };

    let result = windows::move_cross_volume_directory(
        token,
        ItemId(0),
        &source,
        &destination_root.join("source-tree"),
        &move_guard.source_identities[0],
        &destination_identity,
        &AtomicBool::new(false),
        &controls,
        &mut |_| {},
        &mut route_fact,
    );
    panic!("crash child escaped its durable ACK barrier: {result:?}");
}

#[cfg(windows)]
fn write_directory_move_crash_checkpoint(
    checkpoint_path: &std::path::Path,
    receipt: &(
        String,
        &crate::operations::journal::JournalDirectoryRootIntent,
        &crate::operations::journal::JournalDirectoryChildIntent,
    ),
) {
    use std::io::Write;

    let checkpoint_temp_path = checkpoint_path.with_extension("json.tmp");
    let mut checkpoint = std::fs::File::create(&checkpoint_temp_path).unwrap();
    checkpoint
        .write_all(&serde_json::to_vec(receipt).unwrap())
        .unwrap();
    checkpoint.sync_all().unwrap();
    drop(checkpoint);
    std::fs::rename(&checkpoint_temp_path, checkpoint_path).unwrap();
}

#[cfg(windows)]
#[test]
fn directory_move_child_crash_after_durable_root_receipt() {
    run_directory_move_child_crash_case(DirectoryMoveCrashBoundary::RootReceipt);
}

#[cfg(windows)]
#[test]
fn directory_move_child_crash_after_durable_completion_before_ack() {
    run_directory_move_child_crash_case(DirectoryMoveCrashBoundary::Complete);
}

#[cfg(windows)]
fn run_directory_move_child_crash_case(boundary: DirectoryMoveCrashBoundary) {
    use crate::operations::journal::{
        JournalDirectoryChildIntent, JournalDirectoryNodeKind, JournalDirectoryRootIntent,
        JournalState, JournalStore, RecoveryItem,
    };
    use std::{
        process::{Child, Command, Stdio},
        thread,
        time::{Duration, Instant},
    };

    if std::env::var_os(DIRECTORY_MOVE_RECEIPT_CRASH_CHILD_ENV).is_some() {
        directory_move_root_receipt_crash_child();
        return;
    }

    struct ChildGuard(Child);
    impl Drop for ChildGuard {
        fn drop(&mut self) {
            let _ = self.0.kill();
            let _ = self.0.wait();
        }
    }

    let Some(destination_volume) = cross_volume_test_root() else {
        return;
    };
    let source_volume = local_ntfs_fixture();
    if !cross_volume_test_has_different_drive(source_volume.path(), &destination_volume) {
        eprintln!("skipping directory Move crash test: destination must differ from source volume");
        return;
    }
    let Ok(destination_root) = tempfile::Builder::new()
        .prefix("gpui-filer-directory-move-receipt-crash-")
        .tempdir_in(&destination_volume)
    else {
        eprintln!("skipping directory Move crash test: destination volume is not writable");
        return;
    };
    let source = source_volume.path().join("source-tree");
    std::fs::create_dir(&source).unwrap();
    let source_child = source.join("child.bin");
    let child_bytes = b"durable child receipt before root receipt crash";
    std::fs::write(&source_child, child_bytes).unwrap();
    let destination = destination_root.path().join("source-tree");
    let journal_fixture = tempfile::tempdir().unwrap();
    let journal_path = journal_fixture.path().join("directory-move-journal.json");
    let checkpoint_path = journal_fixture
        .path()
        .join("directory-move-receipt-checkpoint.json");

    let mut child = ChildGuard(
        Command::new(std::env::current_exe().unwrap())
            .arg("--exact")
            .arg(match boundary {
                DirectoryMoveCrashBoundary::RootReceipt => {
                    "operations::executor::tests::directory_move_child_crash_after_durable_root_receipt"
                }
                DirectoryMoveCrashBoundary::Complete => {
                    "operations::executor::tests::directory_move_child_crash_after_durable_completion_before_ack"
                }
            })
            .arg("--nocapture")
            .env(DIRECTORY_MOVE_RECEIPT_CRASH_CHILD_ENV, "1")
            .env(
                DIRECTORY_MOVE_CRASH_BOUNDARY_ENV,
                match boundary {
                    DirectoryMoveCrashBoundary::RootReceipt => "root-receipt",
                    DirectoryMoveCrashBoundary::Complete => "complete",
                },
            )
            .env("GPUI_FILER_DIRECTORY_MOVE_CRASH_SOURCE", &source)
            .env(
                "GPUI_FILER_DIRECTORY_MOVE_CRASH_DESTINATION_ROOT",
                destination_root.path(),
            )
            .env("GPUI_FILER_DIRECTORY_MOVE_CRASH_JOURNAL", &journal_path)
            .env(
                "GPUI_FILER_DIRECTORY_MOVE_CRASH_CHECKPOINT",
                &checkpoint_path,
            )
            .stdout(Stdio::null())
            .stderr(Stdio::piped())
            .spawn()
            .unwrap(),
    );
    let deadline = Instant::now() + Duration::from_secs(45);
    while !checkpoint_path.exists() && Instant::now() < deadline {
        if let Some(status) = child.0.try_wait().unwrap() {
            use std::io::Read;
            let mut stderr = String::new();
            if let Some(mut pipe) = child.0.stderr.take() {
                let _ = pipe.read_to_string(&mut stderr);
            }
            panic!("crash child exited before its durable checkpoint: {status}; stderr={stderr}");
        }
        thread::sleep(Duration::from_millis(25));
    }
    assert!(
        checkpoint_path.exists(),
        "directory Move child missed its durable checkpoint"
    );
    let checkpoint: (
        String,
        JournalDirectoryRootIntent,
        JournalDirectoryChildIntent,
    ) = serde_json::from_slice(&std::fs::read(&checkpoint_path).unwrap()).unwrap();
    assert!(destination.is_dir());

    let _ = child.0.kill();
    let status = child.0.wait().unwrap();
    assert!(!status.success(), "child was expected to be terminated");
    assert!(
        !source.exists(),
        "source root is removed after child handle teardown"
    );
    assert!(!source_child.exists());
    let destination_child = destination.join("child.bin");
    assert_eq!(std::fs::read(&destination_child).unwrap(), child_bytes);
    let destination_child_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
        &destination_child,
        crate::directory::EntryKind::File,
    )
    .unwrap()
    .filesystem_identity();
    let (destination_volume, destination_file_index) = destination_child_identity
        .windows_parts()
        .expect("destination child identity should be a Windows file identity");
    let destination_child_identity_text =
        format!("{destination_volume}:{destination_file_index:016x}");
    assert_eq!(
        destination_child_identity_text,
        checkpoint.2.destination_identity
    );

    let persisted_attempts: serde_json::Value =
        serde_json::from_slice(&std::fs::read(&journal_path).unwrap()).unwrap();
    let persisted_attempt = persisted_attempts["attempts"]
        .as_array()
        .unwrap()
        .iter()
        .find(|attempt| attempt["key"] == checkpoint.0)
        .unwrap();
    assert_eq!(persisted_attempt["state"], "running");
    assert!(persisted_attempt["terminal_outcome"].is_null());

    let reopened = JournalStore::open(journal_path.clone()).unwrap();
    let recoveries = reopened.recoveries();
    let [RecoveryItem::RecoveryRequired(record)] = recoveries.as_slice() else {
        panic!("directory Move completion without worker ACK must remain recovery-required");
    };
    assert_eq!(record.key, checkpoint.0);
    assert_eq!(record.state, JournalState::RecoveryRequired);
    assert_eq!(record.terminal_outcome, None);
    let [ledger] = record.directory_moves.as_slice() else {
        panic!("reopened journal must retain exactly one directory manifest");
    };
    assert_eq!(ledger.pending, None);
    assert_eq!(
        ledger.cleanup_complete,
        boundary == DirectoryMoveCrashBoundary::Complete
    );
    assert_eq!(ledger.children.len(), 1);
    assert!(ledger.children[0].disposition_recorded);
    assert_eq!(ledger.children[0].node_kind, JournalDirectoryNodeKind::File);
    assert_eq!(
        ledger.children[0].source_identity,
        checkpoint.2.source_identity
    );
    assert_eq!(
        ledger.children[0].destination_identity,
        checkpoint.2.destination_identity
    );
    assert_eq!(ledger.children[0].content_fact, checkpoint.2.content_fact);
    let root = ledger.root.as_ref().expect("root facts should be retained");
    assert_eq!(root.pending, None);
    assert!(root.disposition_recorded);
    assert_eq!(root.source_identity, checkpoint.1.source_identity);
    assert_eq!(root.destination_identity, checkpoint.1.destination_identity);
    assert_eq!(std::fs::read(&destination_child).unwrap(), child_bytes);
    assert_eq!(
        crate::directory::EntrySourceIdentity::from_path_no_follow(
            &destination_child,
            crate::directory::EntryKind::File,
        )
        .unwrap()
        .filesystem_identity(),
        destination_child_identity
    );

    let reopened_again = JournalStore::open(journal_path.clone()).unwrap();
    let recoveries_again = reopened_again.recoveries();
    let [RecoveryItem::RecoveryRequired(record_again)] = recoveries_again.as_slice() else {
        panic!("second reopen must remain recovery-required");
    };
    assert_eq!(record_again.state, JournalState::RecoveryRequired);
    assert_eq!(record_again.terminal_outcome, None);
    let [ledger_again] = record_again.directory_moves.as_slice() else {
        panic!("second reopen must retain exactly one directory manifest");
    };
    assert_eq!(ledger_again, ledger);
    assert_eq!(ledger_again.pending, None);
    assert_eq!(
        ledger_again.cleanup_complete,
        boundary == DirectoryMoveCrashBoundary::Complete
    );
    assert!(ledger_again.children[0].disposition_recorded);
    let root_again = ledger_again.root.as_ref().unwrap();
    assert_eq!(root_again.pending, None);
    assert!(root_again.disposition_recorded);
    assert_eq!(root_again.source_identity, checkpoint.1.source_identity);
    assert_eq!(
        root_again.destination_identity,
        checkpoint.1.destination_identity
    );
    assert!(!source.exists());
    assert!(!source_child.exists());
    assert_eq!(std::fs::read(&destination_child).unwrap(), child_bytes);
    assert_eq!(
        crate::directory::EntrySourceIdentity::from_path_no_follow(
            &destination_child,
            crate::directory::EntryKind::File,
        )
        .unwrap()
        .filesystem_identity(),
        destination_child_identity
    );

    let persisted_attempts_again: serde_json::Value =
        serde_json::from_slice(&std::fs::read(&journal_path).unwrap()).unwrap();
    let persisted_attempt_again = persisted_attempts_again["attempts"]
        .as_array()
        .unwrap()
        .iter()
        .find(|attempt| attempt["key"] == checkpoint.0)
        .unwrap();
    assert_eq!(persisted_attempt_again["state"], "running");
    assert!(persisted_attempt_again["terminal_outcome"].is_null());
}

#[cfg(windows)]
#[test]
fn worker_fact_transport_routes_real_move_progress_into_runtime() {
    use crate::operations::{
        journal::{JournalStore, JournalWriter},
        model::TerminalOutcome,
        runtime::OperationRuntime,
        transport::WorkerFactTransport,
    };
    use std::{
        future::Future,
        sync::Arc,
        task::{Context, Poll, Wake, Waker},
    };

    fn test_block_on<F: Future>(future: F) -> F::Output {
        struct ThreadWake(std::thread::Thread);
        impl Wake for ThreadWake {
            fn wake(self: Arc<Self>) {
                self.0.unpark();
            }
            fn wake_by_ref(self: &Arc<Self>) {
                self.0.unpark();
            }
        }

        let waker = Waker::from(Arc::new(ThreadWake(std::thread::current())));
        let mut context = Context::from_waker(&waker);
        let mut future = std::pin::pin!(future);
        loop {
            match future.as_mut().poll(&mut context) {
                Poll::Ready(output) => return output,
                Poll::Pending => std::thread::park(),
            }
        }
    }

    struct WorkerGuard {
        runtime: Option<OperationRuntime>,
        transport: Option<WorkerFactTransport>,
        worker: Option<std::thread::JoinHandle<()>>,
        cancellation: crate::operations::runtime::Cancellation,
        pause_release: Option<std::sync::mpsc::Sender<()>>,
    }

    impl WorkerGuard {
        fn runtime(&mut self) -> &mut OperationRuntime {
            self.runtime.as_mut().expect("runtime is live")
        }

        fn transport(&self) -> &WorkerFactTransport {
            self.transport.as_ref().expect("transport is live")
        }

        fn release_progress_pause(&mut self) {
            if let Some(release) = self.pause_release.take() {
                let _ = release.send(());
            }
        }

        fn join(&mut self) {
            if let Some(worker) = self.worker.take() {
                worker.join().unwrap();
            }
        }
    }

    impl Drop for WorkerGuard {
        fn drop(&mut self) {
            self.cancellation
                .store(true, std::sync::atomic::Ordering::Release);
            self.release_progress_pause();
            // unwind中のjoin前に、送信待ちとjournal ACK待ちの両経路を閉じる。
            self.transport.take();
            self.runtime.take();
            if let Some(worker) = self.worker.take() {
                let _ = worker.join();
            }
        }
    }

    let Some(destination_volume) = cross_volume_test_root() else {
        return;
    };
    let source_volume = local_ntfs_fixture();
    if !cross_volume_test_has_different_drive(source_volume.path(), &destination_volume) {
        eprintln!("skipping directory Move test: destination must differ from source volume");
        return;
    }
    let Ok(destination_root) = tempfile::Builder::new()
        .prefix("gpui-filer-worker-move-")
        .tempdir_in(&destination_volume)
    else {
        eprintln!("skipping directory Move test: destination volume is not writable");
        return;
    };

    let first = source_volume.path().join("first");
    std::fs::create_dir(&first).unwrap();
    std::fs::create_dir(first.join("nested")).unwrap();
    let first_bytes = vec![7; 80_000];
    std::fs::write(first.join("nested/one.bin"), &first_bytes).unwrap();
    let second = source_volume.path().join("second");
    std::fs::create_dir(&second).unwrap();
    let second_bytes = vec![9; 72_000];
    std::fs::write(second.join("two.bin"), &second_bytes).unwrap();
    let loose_file = source_volume.path().join("loose.txt");
    let loose_bytes = b"ordinary file item";
    std::fs::write(&loose_file, loose_bytes).unwrap();
    let sources = vec![first.clone(), second.clone(), loose_file.clone()];
    let destination = destination_root.path().to_path_buf();

    let mut runtime = OperationRuntime::new(OperationService::default());
    let token = runtime
        .submit(OperationRequest {
            kind: OperationKind::Move,
            virtual_source: None,
            sources: sources.clone(),
            destination: Some(destination.clone()),
            batch_rename_plan: None,
            move_identity_guard: None,
            clipboard_move_source_evidence: None,
            rename_reparse_guard: None,
            move_destination_identity_guard: None,
            move_replace_source_evidence: None,
            trash_source_guards: None,
            source_cleanup_identity_guard: None,
            initial_conflict_policy: None,
            copy_destination_identity_guard: None,
            create_parent_directory_identity_guard: None,
            zip_create_guard: None,
            shortcut_create_guard: None,
            seven_zip_create_guard: None,
            seven_zip_extract_guard: None,
            origin: None,
        })
        .unwrap();
    let start = runtime.start_next().unwrap();
    let mut initial = runtime.journal_attempt(token).unwrap();
    let journal_fixture = tempfile::tempdir().unwrap();
    let journal_path = journal_fixture.path().join("journal.json");
    let writer = JournalWriter::start(JournalStore::open(journal_path.clone()).unwrap());
    writer
        .upsert_with_reply(initial.clone())
        .recv_blocking()
        .unwrap()
        .unwrap();

    let (transport, facts_sender) = WorkerFactTransport::new(token);
    let (terminal_sender_tx, terminal_sender_rx) = std::sync::mpsc::channel();
    let (pause_release, pause_receiver) = std::sync::mpsc::channel();
    let cancellation = start.cancellation.clone();
    let worker = std::thread::spawn(move || {
        let mut paused_after_progress = false;
        let mut terminal_published = false;
        execute_prepare_with_source_cleanup_lease(
            start.command,
            &start.cancellation,
            &start.controls,
            start.source_cleanup_lease,
            |fact| {
                let is_progress = matches!(fact, ExecutorFact::Progress { .. });
                terminal_published |= matches!(fact, ExecutorFact::Terminal { .. });
                facts_sender.publish(fact);
                if is_progress && !paused_after_progress {
                    paused_after_progress = true;
                    let _ = pause_receiver.recv();
                }
            },
        );
        if terminal_published {
            let _ = terminal_sender_tx.send(facts_sender.clone());
        }
    });
    let mut guard = WorkerGuard {
        runtime: Some(runtime),
        transport: Some(transport),
        worker: Some(worker),
        cancellation,
        pause_release: Some(pause_release),
    };
    let mut progress = Vec::new();
    let mut last_accepted_sequence = 0;
    let terminal_commit = loop {
        let fact = test_block_on(guard.transport().recv())
            .expect("worker transport remains open until terminal");
        match fact {
            ExecutorFact::DirectoryMoveManifestIntent {
                token: fact_token,
                ledger,
            } => {
                assert_eq!(fact_token, token);
                assert!(
                    guard
                        .runtime()
                        .commit_fact(ExecutorFact::DirectoryMoveManifestIntent {
                            token: fact_token,
                            ledger: ledger.clone(),
                        })
                        .is_none()
                );
                writer
                    .register_directory_move(initial.key.clone(), ledger.clone())
                    .recv_blocking()
                    .unwrap()
                    .unwrap();
                assert!(
                    guard
                        .runtime()
                        .acknowledge_directory_move_manifest(token, &ledger)
                );
            }
            ExecutorFact::DirectoryMoveChildIntent {
                token: fact_token,
                item,
                intent,
            } => {
                assert!(
                    guard
                        .runtime()
                        .commit_fact(ExecutorFact::DirectoryMoveChildIntent {
                            token: fact_token,
                            item,
                            intent: intent.clone(),
                        })
                        .is_none()
                );
                writer
                    .record_directory_move_intent(initial.key.clone(), item.0, intent.clone())
                    .recv_blocking()
                    .unwrap()
                    .unwrap();
                assert!(
                    guard
                        .runtime()
                        .acknowledge_directory_move_child_intent(token, item, &intent)
                );
            }
            ExecutorFact::DirectoryMoveChildDisposition {
                token: fact_token,
                item,
                intent,
            } => {
                assert!(
                    guard
                        .runtime()
                        .commit_fact(ExecutorFact::DirectoryMoveChildDisposition {
                            token: fact_token,
                            item,
                            intent: intent.clone(),
                        })
                        .is_none()
                );
                writer
                    .record_directory_move_receipt(initial.key.clone(), item.0, intent.clone())
                    .recv_blocking()
                    .unwrap()
                    .unwrap();
                assert!(
                    guard
                        .runtime()
                        .acknowledge_directory_move_child_receipt(token, item, &intent)
                );
            }
            ExecutorFact::DirectoryMoveRootIntent {
                token: fact_token,
                item,
                intent,
            } => {
                assert!(
                    guard
                        .runtime()
                        .commit_fact(ExecutorFact::DirectoryMoveRootIntent {
                            token: fact_token,
                            item,
                            intent: intent.clone(),
                        })
                        .is_none()
                );
                writer
                    .record_directory_move_root_intent(initial.key.clone(), item.0, intent.clone())
                    .recv_blocking()
                    .unwrap()
                    .unwrap();
                assert!(
                    guard
                        .runtime()
                        .acknowledge_directory_move_root_intent(token, item, &intent)
                );
            }
            ExecutorFact::DirectoryMoveRootDisposition {
                token: fact_token,
                item,
                intent,
            } => {
                assert!(
                    guard
                        .runtime()
                        .commit_fact(ExecutorFact::DirectoryMoveRootDisposition {
                            token: fact_token,
                            item,
                            intent: intent.clone(),
                        })
                        .is_none()
                );
                writer
                    .record_directory_move_root_receipt(initial.key.clone(), item.0, intent.clone())
                    .recv_blocking()
                    .unwrap()
                    .unwrap();
                assert!(
                    guard
                        .runtime()
                        .acknowledge_directory_move_root_receipt(token, item, &intent)
                );
            }
            ExecutorFact::DirectoryMoveComplete {
                token: fact_token,
                item,
            } => {
                assert!(
                    guard
                        .runtime()
                        .commit_fact(ExecutorFact::DirectoryMoveComplete {
                            token: fact_token,
                            item,
                        })
                        .is_none()
                );
                writer
                    .complete_directory_move(initial.key.clone(), item.0)
                    .recv_blocking()
                    .unwrap()
                    .unwrap();
                assert!(
                    guard
                        .runtime()
                        .acknowledge_directory_move_complete(token, item)
                );
            }
            ExecutorFact::Progress {
                token: fact_token,
                update,
            } => {
                assert!(guard.runtime().commit_progress(fact_token, &update));
                assert!(update.sequence > last_accepted_sequence);
                assert!(update.counters.processed_bytes > 0);
                assert_eq!(
                    guard.runtime().job(token).unwrap().attempts[0].state,
                    crate::operations::model::AttemptState::Running
                );
                last_accepted_sequence = update.sequence;
                progress.push(update);
                guard.release_progress_pause();
            }
            ExecutorFact::Terminal {
                token: fact_token,
                report,
            } => {
                assert_eq!(fact_token, token);
                assert_eq!(report.outcome, TerminalOutcome::Succeeded);
                let candidate = guard
                    .runtime()
                    .directory_move_terminal_candidate(token, &report)
                    .unwrap();
                writer
                    .upsert_with_reply(candidate)
                    .recv_blocking()
                    .unwrap()
                    .unwrap();
                break guard
                    .runtime()
                    .commit_directory_move_terminal(token, report, true);
            }
            other => {
                let _ = guard.runtime().commit_fact(other);
            }
        }
    };
    // worker終了後に遅延progress用senderを受け取り、transportを閉じる。
    guard.join();
    let late_sender = terminal_sender_rx
        .recv()
        .expect("a terminal publication returns the late-progress sender");
    let terminal_snapshot = guard.runtime().job(token).unwrap().attempts[0].clone();
    late_sender.publish(ExecutorFact::Progress {
        token,
        update: crate::operations::model::ProgressUpdate {
            sequence: u64::MAX,
            counters: crate::operations::model::ProgressCounters {
                processed_bytes: u64::MAX,
                ..Default::default()
            },
            current_item: Some(ItemId(0)),
        },
    });
    let late_fact =
        test_block_on(guard.transport().recv()).expect("late mailbox progress remains drainable");
    let ExecutorFact::Progress {
        token: late_token,
        update: late_update,
    } = late_fact
    else {
        panic!("expected late progress after terminal, got {late_fact:?}");
    };
    assert!(!guard.runtime().commit_progress(late_token, &late_update));
    assert_eq!(
        guard.runtime().job(token).unwrap().attempts[0],
        terminal_snapshot
    );
    drop(late_sender);
    assert!(test_block_on(guard.transport().recv()).is_none());
    let crate::operations::model::ServiceEvent::TerminalCommitted { report, .. } =
        terminal_commit.unwrap().event;
    assert_eq!(report.outcome, TerminalOutcome::Succeeded);
    assert_eq!(report.receipts.len(), 3);
    assert!(report.receipts.iter().all(|receipt| {
        receipt.outcome == crate::operations::model::ItemOutcome::Completed
            && receipt.move_receipt.as_ref().is_some_and(|move_receipt| {
                move_receipt.destination_published && move_receipt.source_removed
            })
    }));
    assert_eq!(report.final_counters.total_items, Some(3));
    assert_eq!(report.final_counters.processed_items, 3);
    assert_eq!(
        report.final_counters.processed_bytes,
        152_000 + loose_bytes.len() as u64
    );
    assert!(!progress.is_empty());
    assert!(!first.exists() && !second.exists() && !loose_file.exists());
    assert_eq!(
        std::fs::read(destination.join("first/nested/one.bin")).unwrap(),
        first_bytes
    );
    assert_eq!(
        std::fs::read(destination.join("second/two.bin")).unwrap(),
        second_bytes
    );
    assert_eq!(
        std::fs::read(destination.join("loose.txt")).unwrap(),
        loose_bytes
    );
    initial.state = crate::operations::journal::JournalState::Terminal;
    initial.receipts_recorded = true;
    initial.terminal_outcome = Some(crate::operations::journal::JournalTerminalOutcome::Succeeded);
    writer
        .upsert_with_reply(initial)
        .recv_blocking()
        .unwrap()
        .unwrap();
    drop(writer);
    assert!(
        JournalStore::open(journal_path)
            .unwrap()
            .recoveries()
            .is_empty()
    );
}

#[cfg(windows)]
#[test]
fn worker_fact_transport_routes_real_copy_progress_into_runtime() {
    use crate::operations::{
        model::{AttemptState, ItemOutcome, OperationKind, OperationRequest, TerminalOutcome},
        runtime::OperationRuntime,
        transport::WorkerFactTransport,
    };
    use std::{
        future::Future,
        sync::Arc,
        task::{Context, Poll, Wake, Waker},
    };

    fn block_on<F: Future>(future: F) -> F::Output {
        struct ThreadWake(std::thread::Thread);
        impl Wake for ThreadWake {
            fn wake(self: Arc<Self>) {
                self.0.unpark();
            }
            fn wake_by_ref(self: &Arc<Self>) {
                self.0.unpark();
            }
        }

        let waker = Waker::from(Arc::new(ThreadWake(std::thread::current())));
        let mut context = Context::from_waker(&waker);
        let mut future = std::pin::pin!(future);
        loop {
            match future.as_mut().poll(&mut context) {
                Poll::Ready(output) => return output,
                Poll::Pending => std::thread::park(),
            }
        }
    }

    struct WorkerGuard {
        transport: Option<WorkerFactTransport>,
        worker: Option<std::thread::JoinHandle<()>>,
        cancellation: crate::operations::runtime::Cancellation,
        progress_release: Option<std::sync::mpsc::SyncSender<()>>,
    }

    impl Drop for WorkerGuard {
        fn drop(&mut self) {
            self.cancellation
                .store(true, std::sync::atomic::Ordering::Release);
            if let Some(release) = self.progress_release.take() {
                let _ = release.try_send(());
            }
            self.transport.take();
            if let Some(worker) = self.worker.take() {
                let _ = worker.join();
            }
        }
    }

    let root = tempfile::tempdir().unwrap();
    let source = root.path().join("source.bin");
    let destination_root = root.path().join("destination");
    std::fs::create_dir(&destination_root).unwrap();
    let source_bytes = (0..1024 * 1024)
        .map(|index| (index % 251) as u8)
        .collect::<Vec<_>>();
    std::fs::write(&source, &source_bytes).unwrap();

    let mut runtime = OperationRuntime::new(crate::operations::model::OperationService::default());
    let token = runtime
        .submit(OperationRequest {
            kind: OperationKind::Copy,
            virtual_source: None,
            sources: vec![source.clone()],
            destination: Some(destination_root.clone()),
            batch_rename_plan: None,
            move_identity_guard: None,
            clipboard_move_source_evidence: None,
            rename_reparse_guard: None,
            move_destination_identity_guard: None,
            move_replace_source_evidence: None,
            trash_source_guards: None,
            source_cleanup_identity_guard: None,
            initial_conflict_policy: None,
            copy_destination_identity_guard: None,
            create_parent_directory_identity_guard: None,
            zip_create_guard: None,
            shortcut_create_guard: None,
            seven_zip_create_guard: None,
            seven_zip_extract_guard: None,
            origin: None,
        })
        .unwrap();
    let start = runtime.start_next().unwrap();
    let (transport, facts_sender) = WorkerFactTransport::new(token);
    let (progress_release, progress_resume) = std::sync::mpsc::sync_channel(1);
    let cancellation = start.cancellation.clone();
    let worker = std::thread::spawn(move || {
        let mut paused_after_positive_progress = false;
        execute_prepare(
            start.command,
            &start.cancellation,
            &start.controls,
            |fact| {
                let pause_after_publish = matches!(
                    &fact,
                    ExecutorFact::Progress { update, .. }
                        if update.counters.processed_bytes > 0
                            && !paused_after_positive_progress
                );
                facts_sender.publish(fact);
                if pause_after_publish {
                    paused_after_positive_progress = true;
                    let _ = progress_resume.recv();
                }
            },
        )
    });
    let mut guard = WorkerGuard {
        transport: Some(transport),
        worker: Some(worker),
        cancellation,
        progress_release: Some(progress_release),
    };

    let mut accepted_sequences = Vec::new();
    let mut captured_progress = None;
    let terminal_report = loop {
        let fact = block_on(guard.transport.as_ref().unwrap().recv())
            .expect("worker transport remains open through terminal");
        match fact {
            ExecutorFact::Progress {
                token: fact_token,
                update,
            } => {
                assert_eq!(fact_token, token);
                assert_eq!(
                    runtime.job(token).unwrap().attempts[0].state,
                    AttemptState::Running
                );
                assert!(update.counters.processed_bytes > 0);
                assert!(runtime.commit_progress(fact_token, &update));
                accepted_sequences.push(update.sequence);
                captured_progress = Some(update);
                if let Some(release) = guard.progress_release.take() {
                    release.try_send(()).unwrap();
                }
            }
            ExecutorFact::Terminal {
                token: fact_token,
                report,
            } => {
                assert_eq!(fact_token, token);
                assert!(
                    runtime
                        .commit_fact(ExecutorFact::Terminal {
                            token: fact_token,
                            report: report.clone(),
                        })
                        .is_some()
                );
                break report;
            }
            other => panic!("unexpected Copy worker fact: {other:?}"),
        }
    };
    guard.worker.take().unwrap().join().unwrap();

    assert!(!accepted_sequences.is_empty());
    assert!(accepted_sequences[0] > 0);
    assert!(accepted_sequences.windows(2).all(|pair| pair[0] < pair[1]));
    assert_eq!(terminal_report.outcome, TerminalOutcome::Succeeded);
    assert_eq!(terminal_report.receipts.len(), 1);
    assert_eq!(terminal_report.receipts[0].outcome, ItemOutcome::Completed);
    assert_eq!(terminal_report.final_counters.processed_items, 1);
    assert_eq!(
        terminal_report.final_counters.processed_bytes,
        source_bytes.len() as u64
    );
    assert_eq!(
        captured_progress
            .as_ref()
            .expect("accepted Copy progress was captured")
            .counters
            .processed_items,
        1
    );
    let terminal_snapshot = runtime.job(token).unwrap().attempts[0].clone();
    assert_eq!(terminal_snapshot.state, AttemptState::Terminal);
    assert_eq!(terminal_snapshot.terminal.as_ref(), Some(&terminal_report));

    let mut late_progress = captured_progress.unwrap();
    late_progress.sequence += 1;
    late_progress.counters.processed_bytes += 1;
    assert!(!runtime.commit_progress(token, &late_progress));
    assert_eq!(runtime.job(token).unwrap().attempts[0], terminal_snapshot);
    assert_eq!(std::fs::read(&source).unwrap(), source_bytes);
    assert_eq!(
        std::fs::read(destination_root.join("source.bin")).unwrap(),
        source_bytes
    );
}

#[cfg(windows)]
#[test]
fn cross_volume_keep_both_journals_selected_candidate_guarded_and_guardless() {
    use crate::operations::journal::{JournalPath, JournalStore, JournalWriter};

    let Some(destination_volume) = cross_volume_test_root() else {
        return;
    };
    let source_volume = local_ntfs_fixture();
    if !cross_volume_test_has_different_drive(source_volume.path(), &destination_volume) {
        eprintln!("skipping directory Move test: destination must differ from source volume");
        return;
    }
    for guarded in [false, true] {
        let source_parent = local_ntfs_fixture();
        let Ok(destination_parent) = tempfile::Builder::new()
            .prefix("gpui-filer-keep-both-")
            .tempdir_in(&destination_volume)
        else {
            eprintln!("skipping directory Move test: destination volume is not writable");
            return;
        };
        let source = source_parent.path().join("item");
        std::fs::create_dir(&source).unwrap();
        let requested_destination = destination_parent.path().join("item");
        std::fs::create_dir(&requested_destination).unwrap();
        std::fs::write(requested_destination.join("existing.txt"), b"existing").unwrap();
        let occupied_candidate = destination_parent.path().join("item (2)");
        std::fs::create_dir(&occupied_candidate).unwrap();
        std::fs::write(occupied_candidate.join("kept.txt"), b"kept").unwrap();
        let candidate = destination_parent.path().join("item (3)");
        let destination_identity = filesystem_identity(
            destination_parent.path(),
            crate::directory::EntryKind::Folder,
        );
        let move_identity_guard = guarded
            .then(|| preflight_local_move_guard(&[source.clone()], &destination_identity).unwrap());
        let mut runtime =
            crate::operations::runtime::OperationRuntime::new(OperationService::default());
        let token = runtime
            .submit(OperationRequest {
                kind: OperationKind::Move,
                virtual_source: None,
                sources: vec![source.clone()],
                destination: Some(destination_parent.path().to_path_buf()),
                batch_rename_plan: None,
                move_identity_guard,
                clipboard_move_source_evidence: None,
                rename_reparse_guard: None,
                move_destination_identity_guard: None,
                move_replace_source_evidence: None,
                trash_source_guards: None,
                source_cleanup_identity_guard: None,
                initial_conflict_policy: None,
                copy_destination_identity_guard: None,
                create_parent_directory_identity_guard: None,
                zip_create_guard: None,
                shortcut_create_guard: None,
                seven_zip_create_guard: None,
                seven_zip_extract_guard: None,
                origin: None,
            })
            .unwrap();
        let start = runtime.start_next().unwrap();
        let initial = runtime.journal_attempt(token).unwrap();
        let key = initial.key.clone();
        let journal_fixture = tempfile::tempdir().unwrap();
        let journal_path = journal_fixture.path().join("journal.json");
        let writer = JournalWriter::start(JournalStore::open(journal_path.clone()).unwrap());
        writer
            .upsert_with_reply(initial.clone())
            .recv_blocking()
            .unwrap()
            .unwrap();
        let (facts_sender, facts) = std::sync::mpsc::channel();
        let worker = std::thread::spawn(move || {
            execute_prepare_with_source_cleanup_lease(
                start.command,
                &start.cancellation,
                &start.controls,
                start.source_cleanup_lease,
                |fact| facts_sender.send(fact).unwrap(),
            );
        });
        let conflict = facts.recv().unwrap();
        assert!(
            matches!(&conflict, ExecutorFact::Conflict { token: actual, .. } if *actual == token)
        );
        assert!(runtime.commit_fact(conflict).is_none());
        let conflict_token = runtime
            .job(token)
            .unwrap()
            .attempts
            .last()
            .unwrap()
            .pending_conflict
            .as_ref()
            .unwrap()
            .token;
        assert!(runtime.resolve_conflict(conflict_token, ConflictDecision::KeepBoth, false));

        let mut selected_ledger = None;
        let terminal_report = loop {
            match facts.recv().unwrap() {
                ExecutorFact::DirectoryMoveManifestIntent {
                    token: fact_token,
                    ledger,
                } => {
                    assert_eq!(fact_token, token);
                    assert_eq!(ledger.destination, JournalPath::from_path(&candidate));
                    assert!(
                        runtime
                            .commit_fact(ExecutorFact::DirectoryMoveManifestIntent {
                                token,
                                ledger: ledger.clone(),
                            })
                            .is_none()
                    );
                    writer
                        .register_directory_move(key.clone(), ledger.clone())
                        .recv_blocking()
                        .unwrap()
                        .unwrap();
                    selected_ledger = Some(ledger.clone());
                    assert!(runtime.acknowledge_directory_move_manifest(token, &ledger));
                }
                ExecutorFact::DirectoryMoveRootIntent {
                    token: fact_token,
                    item,
                    intent,
                } => {
                    assert_eq!(fact_token, token);
                    assert!(
                        runtime
                            .commit_fact(ExecutorFact::DirectoryMoveRootIntent {
                                token,
                                item,
                                intent: intent.clone(),
                            })
                            .is_none()
                    );
                    writer
                        .record_directory_move_root_intent(key.clone(), item.0, intent.clone())
                        .recv_blocking()
                        .unwrap()
                        .unwrap();
                    assert!(runtime.acknowledge_directory_move_root_intent(token, item, &intent));
                }
                ExecutorFact::DirectoryMoveRootDisposition {
                    token: fact_token,
                    item,
                    intent,
                } => {
                    assert_eq!(fact_token, token);
                    assert!(
                        runtime
                            .commit_fact(ExecutorFact::DirectoryMoveRootDisposition {
                                token,
                                item,
                                intent: intent.clone(),
                            })
                            .is_none()
                    );
                    writer
                        .record_directory_move_root_receipt(key.clone(), item.0, intent.clone())
                        .recv_blocking()
                        .unwrap()
                        .unwrap();
                    assert!(runtime.acknowledge_directory_move_root_receipt(token, item, &intent));
                }
                ExecutorFact::DirectoryMoveComplete {
                    token: fact_token,
                    item,
                } => {
                    assert_eq!(fact_token, token);
                    assert!(
                        runtime
                            .commit_fact(ExecutorFact::DirectoryMoveComplete { token, item })
                            .is_none()
                    );
                    writer
                        .complete_directory_move(key.clone(), item.0)
                        .recv_blocking()
                        .unwrap()
                        .unwrap();
                    assert!(runtime.acknowledge_directory_move_complete(token, item));
                }
                fact @ ExecutorFact::Progress { .. } => {
                    runtime.commit_fact(fact);
                }
                fact @ ExecutorFact::MoveGuardResolved { .. } => {
                    runtime.commit_fact(fact);
                }
                fact @ ExecutorFact::GuardedMoveNoEffectProof { .. } => {
                    runtime.commit_fact(fact);
                }
                ExecutorFact::Terminal {
                    token: fact_token,
                    report,
                } => {
                    assert_eq!(fact_token, token);
                    assert_eq!(report.outcome, TerminalOutcome::Succeeded);
                    assert_eq!(
                        report.receipts[0]
                            .move_receipt
                            .as_ref()
                            .unwrap()
                            .destination,
                        candidate
                    );
                    let terminal_record = runtime
                        .directory_move_terminal_candidate(token, &report)
                        .expect("Runtime must reserve success after durable Complete ACK");
                    writer
                        .upsert_with_reply(terminal_record)
                        .recv_blocking()
                        .unwrap()
                        .unwrap();
                    assert!(matches!(
                        runtime
                            .commit_directory_move_terminal(token, report.clone(), true)
                            .unwrap()
                            .event,
                        crate::operations::model::ServiceEvent::TerminalCommitted { report, .. }
                            if report.outcome == TerminalOutcome::Succeeded
                    ));
                    break report;
                }
                other => panic!("unexpected Keep Both fact: {other:?}"),
            }
        };
        worker.join().unwrap();
        assert!(selected_ledger.is_some());
        assert_eq!(terminal_report.outcome, TerminalOutcome::Succeeded);
        assert!(!source.exists());
        assert_eq!(
            std::fs::read(requested_destination.join("existing.txt")).unwrap(),
            b"existing"
        );
        assert_eq!(
            std::fs::read(occupied_candidate.join("kept.txt")).unwrap(),
            b"kept"
        );
        assert!(candidate.is_dir());
        drop(writer);

        let bytes = std::fs::read(&journal_path).unwrap();
        let document: serde_json::Value = serde_json::from_slice(&bytes).unwrap();
        let ledger_json = &document["attempts"][0]["directory_moves"][0];
        let persisted_units = ledger_json["destination"]["units"]
            .as_array()
            .unwrap()
            .iter()
            .map(|unit| unit.as_u64().unwrap() as u16)
            .collect::<Vec<_>>();
        assert_eq!(persisted_units, JournalPath::from_path(&candidate).units);

        assert_eq!(
            selected_ledger.unwrap().destination,
            JournalPath::from_path(&candidate)
        );
    }
}

#[cfg(windows)]
#[test]
fn directory_move_manifest_stale_or_mismatched_ack_never_publishes() {
    for mismatch in ["attempt", "root identity", "manifest"] {
        let fixture = local_ntfs_fixture();
        let (source, stage_path, destination) = directory_move_paths(&fixture);
        let (token, other_token) =
            directory_move_test_tokens(&source, destination.parent().unwrap());
        let ack_token = if mismatch == "attempt" {
            other_token
        } else {
            token
        };
        let cancelled = std::sync::Arc::new(AtomicBool::new(false));
        let (facts, controls, worker) = spawn_manifest_barrier(
            token,
            source.clone(),
            stage_path.clone(),
            destination.clone(),
            cancelled,
        );
        let ExecutorFact::DirectoryMoveManifestIntent { ledger, .. } = facts.recv().unwrap() else {
            panic!("worker must emit manifest intent");
        };
        assert!(!destination.exists());
        let mut ack_ledger = ledger;
        match mismatch {
            "root identity" => ack_ledger
                .root
                .as_mut()
                .unwrap()
                .destination_identity
                .push_str("-stale"),
            "manifest" => ack_ledger.destination.units.push(0),
            _ => {}
        }
        controls
            .send(WorkerControl::DirectoryMoveManifestJournaledExact {
                token: ack_token,
                ledger: ack_ledger,
            })
            .unwrap();
        let worker_result = worker.join().unwrap();
        assert!(
            matches!(
                &worker_result,
                Err(ManifestBarrierFailure::BeforePublish(CopyError::Cancelled))
            ),
            "mismatched journal ack ({mismatch}) must cancel after successful stage cleanup; worker result: {worker_result:?}"
        );
        assert!(!destination.exists());
        assert!(
            !stage_path.exists(),
            "mismatched journal ack ({mismatch}) must clean the stage; worker result: {worker_result:?}"
        );
        assert_eq!(
            std::fs::read(source.join("payload.txt")).unwrap(),
            b"durable barrier payload"
        );
    }
}

#[cfg(windows)]
#[test]
fn directory_move_manifest_cancel_or_missing_ack_never_publishes() {
    for cancel_before_ack in [false, true] {
        let fixture = local_ntfs_fixture();
        let (source, stage_path, destination) = directory_move_paths(&fixture);
        let (token, _) = directory_move_test_tokens(&source, destination.parent().unwrap());
        let cancelled = std::sync::Arc::new(AtomicBool::new(false));
        let (facts, controls, worker) = spawn_manifest_barrier(
            token,
            source.clone(),
            stage_path.clone(),
            destination.clone(),
            cancelled.clone(),
        );
        let ExecutorFact::DirectoryMoveManifestIntent { ledger, .. } = facts.recv().unwrap() else {
            panic!("worker must emit manifest intent");
        };
        assert!(!destination.exists());
        if cancel_before_ack {
            cancelled.store(true, Ordering::Release);
            controls
                .send(WorkerControl::DirectoryMoveManifestJournaledExact { token, ledger })
                .unwrap();
        } else {
            drop(controls);
        }
        assert!(matches!(worker.join().unwrap(), Err(_)));
        assert!(!destination.exists());
        assert!(
            !stage_path.exists(),
            "missing/cancelled journal ack must clean the stage"
        );
        assert_eq!(
            std::fs::read(source.join("payload.txt")).unwrap(),
            b"durable barrier payload"
        );
    }
}

