#[cfg(windows)]
#[test]
fn pinned_source_tree_publish_reopens_and_retains_exact_published_children() {
    let fixture = local_ntfs_fixture();
    let destination_fixture = local_ntfs_fixture();
    let source_root = fixture.path().join("source");
    let staging_root = destination_fixture.path().join("staging");
    let published_root = destination_fixture.path().join("published");
    std::fs::create_dir(&source_root).unwrap();
    std::fs::create_dir(source_root.join("nested")).unwrap();
    std::fs::create_dir(source_root.join("empty")).unwrap();
    std::fs::write(source_root.join("root.txt"), b"root payload").unwrap();
    std::fs::write(source_root.join("nested").join("leaf.bin"), b"leaf payload").unwrap();
    let mut pinned =
        windows::preflight_pinned_source_tree(&source_root, &AtomicBool::new(false)).unwrap();
    let staging_lease = windows::create_attempt_staging_root(&staging_root).unwrap();
    let staged =
        windows::stage_pinned_source_tree(&mut pinned, staging_lease, &AtomicBool::new(false))
            .unwrap();
    let before = (
        staged.root_identity.clone(),
        staged
            .nodes
            .iter()
            .map(|node| (node.relative_components.clone(), node.identity.clone()))
            .collect::<Vec<_>>(),
    );
    let verified =
        windows::publish_and_verify_staged_tree(staged, &published_root, &AtomicBool::new(false))
            .unwrap();

    assert!(!staging_root.exists());
    assert_eq!(
        std::fs::read(published_root.join("root.txt")).unwrap(),
        b"root payload"
    );
    assert_eq!(
        std::fs::read(published_root.join("nested").join("leaf.bin")).unwrap(),
        b"leaf payload"
    );
    assert_eq!(
        windows::verified_published_identities_for_test(&verified).unwrap(),
        before
    );
    assert_eq!(
        std::fs::read(source_root.join("root.txt")).unwrap(),
        b"root payload"
    );
    assert_eq!(
        std::fs::read(source_root.join("nested").join("leaf.bin")).unwrap(),
        b"leaf payload"
    );
    let nested = published_root.join("nested");
    assert!(std::fs::rename(&nested, published_root.join("nested-moved")).is_err());
    assert!(std::fs::remove_dir(&nested).is_err());
    assert!(std::os::windows::fs::symlink_dir(&source_root, &nested).is_err());
    let empty = published_root.join("empty");
    assert!(std::fs::rename(&empty, published_root.join("empty-moved")).is_err());
    assert!(std::fs::remove_dir(&empty).is_err());
    assert!(std::os::windows::fs::symlink_dir(&source_root, &empty).is_err());
    assert!(
        std::fs::rename(
            published_root.join("root.txt"),
            published_root.join("root-moved.txt")
        )
        .is_err()
    );
}

