#[cfg(windows)]
#[test]
fn pinned_source_tree_fails_closed_for_writer_cancellation_and_limits() {
    use ::windows::{
        Win32::{
            Foundation::{CloseHandle, HANDLE},
            System::Memory::{
                CreateFileMappingW, FILE_MAP_WRITE, MapViewOfFile, PAGE_READWRITE, UnmapViewOfFile,
            },
        },
        core::PCWSTR,
    };
    use std::os::windows::io::AsRawHandle;

    let fixture = local_ntfs_fixture();
    let root = fixture.path().join("source");
    std::fs::create_dir(&root).unwrap();
    std::fs::write(root.join("file.txt"), b"data").unwrap();

    let writer = std::fs::OpenOptions::new()
        .write(true)
        .open(root.join("file.txt"))
        .unwrap();
    assert!(windows::preflight_pinned_source_tree(&root, &AtomicBool::new(false)).is_err());
    drop(writer);

    let mapped_file = std::fs::OpenOptions::new()
        .read(true)
        .write(true)
        .open(root.join("file.txt"))
        .unwrap();
    let mapping = unsafe {
        CreateFileMappingW(
            HANDLE(mapped_file.as_raw_handle() as *mut _),
            None,
            PAGE_READWRITE,
            0,
            0,
            PCWSTR::null(),
        )
        .unwrap()
    };
    let view = unsafe { MapViewOfFile(mapping, FILE_MAP_WRITE, 0, 0, 1) };
    assert!(!view.Value.is_null());
    drop(mapped_file);
    assert!(windows::preflight_pinned_source_tree(&root, &AtomicBool::new(false)).is_err());
    unsafe {
        let _ = UnmapViewOfFile(view);
        let _ = CloseHandle(mapping);
    }
    let cancelled = AtomicBool::new(true);
    assert!(matches!(
        windows::preflight_pinned_source_tree(&root, &cancelled),
        Err(CopyError::Cancelled)
    ));
    for limits in [
        windows::SourceTreeLimits {
            entries: 0,
            ..Default::default()
        },
        windows::SourceTreeLimits {
            depth: 0,
            ..Default::default()
        },
        windows::SourceTreeLimits {
            relative_name_bytes: 0,
            ..Default::default()
        },
        windows::SourceTreeLimits {
            record_bytes: 0,
            ..Default::default()
        },
    ] {
        assert!(
            windows::preflight_pinned_source_tree_with_limits(
                &root,
                &AtomicBool::new(false),
                limits
            )
            .is_err()
        );
    }
    assert_eq!(std::fs::read(root.join("file.txt")).unwrap(), b"data");
}

#[cfg(target_os = "windows")]
fn filesystem_identity(
    path: &Path,
    kind: crate::directory::EntryKind,
) -> crate::filesystem_identity::FilesystemIdentity {
    crate::directory::EntrySourceIdentity::from_path(path, kind)
        .unwrap()
        .filesystem_identity()
}

#[cfg(windows)]
#[test]
#[ignore = "native Windows directory-handle rename behavior probe; run explicitly with --ignored --nocapture"]
fn windows_nested_directory_handle_rename_probe() {
    use ::windows::Win32::{
        Foundation::{HANDLE, INVALID_HANDLE_VALUE},
        Storage::FileSystem::{
            CreateFileW, DELETE, FILE_FLAG_BACKUP_SEMANTICS, FILE_FLAG_OPEN_REPARSE_POINT,
            FILE_INFO_BY_HANDLE_CLASS, FILE_READ_ATTRIBUTES, FILE_RENAME_INFO, FILE_SHARE_READ,
            FILE_SHARE_WRITE, FileRenameInfo, FileRenameInfoEx, GetDriveTypeW,
            GetFileInformationByHandle, GetVolumeInformationW, OPEN_EXISTING,
            SetFileInformationByHandle,
        },
    };
    use ::windows::core::PCWSTR;
    use std::{
        mem::{offset_of, size_of},
        os::windows::{
            ffi::OsStrExt,
            fs::OpenOptionsExt,
            io::{AsRawHandle, FromRawHandle},
        },
    };

    fn rename_info(
        handle: HANDLE,
        destination: &Path,
        class: FILE_INFO_BY_HANDLE_CLASS,
        ex: bool,
    ) -> Result<(), i32> {
        use std::os::windows::ffi::OsStrExt;
        let name: Vec<u16> = destination
            .as_os_str()
            .encode_wide()
            .chain(std::iter::once(0))
            .collect();
        let bytes = name.len().saturating_sub(1) * size_of::<u16>();
        let size = offset_of!(FILE_RENAME_INFO, FileName) + name.len() * size_of::<u16>();
        let mut storage = vec![0_u64; size.div_ceil(size_of::<u64>())];
        let info = storage.as_mut_ptr().cast::<FILE_RENAME_INFO>();
        unsafe {
            if ex {
                (*info).Anonymous.Flags = 0;
            } else {
                (*info).Anonymous.ReplaceIfExists = ::windows::Win32::Foundation::BOOLEAN(0);
            }
            (*info).RootDirectory = HANDLE::default();
            (*info).FileNameLength = bytes as u32;
            std::ptr::copy_nonoverlapping(name.as_ptr(), (*info).FileName.as_mut_ptr(), name.len());
            SetFileInformationByHandle(handle, class, info.cast(), size as u32)
                .map_err(|error| error.code().0)
        }
    }

    fn native_result(result: Result<(), i32>) -> String {
        match result {
            Ok(()) => "ok".into(),
            Err(status) => format!("error HRESULT={:#010x}", status as u32),
        }
    }

    fn open_directory_for_rename(path: &Path) -> std::fs::File {
        let mut options = std::fs::OpenOptions::new();
        options
            .read(true)
            .share_mode(FILE_SHARE_READ.0 | FILE_SHARE_WRITE.0)
            .custom_flags(FILE_FLAG_BACKUP_SEMANTICS.0)
            .access_mode(DELETE.0 | FILE_READ_ATTRIBUTES.0);
        options
            .open(path)
            .expect("open exact fixture directory for rename")
    }

    fn open_child_without_delete_sharing(path: &Path) -> std::fs::File {
        let wide: Vec<u16> = path
            .as_os_str()
            .encode_wide()
            .chain(std::iter::once(0))
            .collect();
        let handle = unsafe {
            CreateFileW(
                ::windows::core::PCWSTR(wide.as_ptr()),
                0,
                FILE_SHARE_READ | FILE_SHARE_WRITE,
                None,
                OPEN_EXISTING,
                FILE_FLAG_BACKUP_SEMANTICS | FILE_FLAG_OPEN_REPARSE_POINT,
                None,
            )
        }
        .expect("open exact no-follow child with no delete sharing");
        assert_ne!(handle, INVALID_HANDLE_VALUE);
        unsafe { std::fs::File::from_raw_handle(handle.0) }
    }

    struct Fixture {
        temp: tempfile::TempDir,
        stage: std::path::PathBuf,
        nested: std::path::PathBuf,
        child_file: std::path::PathBuf,
        bytes: &'static [u8],
        stage_id: crate::filesystem_identity::FilesystemIdentity,
        child_id: crate::filesystem_identity::FilesystemIdentity,
        file_id: crate::filesystem_identity::FilesystemIdentity,
    }

    type FixtureInventory = std::collections::BTreeSet<(String, &'static str)>;

    fn fixture_inventory(root: &Path) -> FixtureInventory {
        use std::os::windows::fs::MetadataExt;

        fn visit(root: &Path, path: &Path, inventory: &mut FixtureInventory) {
            let metadata =
                std::fs::symlink_metadata(path).expect("inspect fixture inventory entry");
            assert_eq!(
                metadata.file_attributes() & 0x400,
                0,
                "probe fixture must not traverse reparse points"
            );
            let kind = if metadata.is_dir() {
                "directory"
            } else if metadata.is_file() {
                "file"
            } else {
                panic!("unsupported fixture inventory kind at {}", path.display());
            };
            let relative = path
                .strip_prefix(root)
                .expect("fixture inventory path stays below its root")
                .to_str()
                .expect("fixture path components are Unicode")
                .replace('\\', "/");
            assert!(
                inventory.insert((relative, kind)),
                "duplicate fixture inventory entry"
            );
            if metadata.is_dir() {
                for child in std::fs::read_dir(path).expect("enumerate fixture inventory directory")
                {
                    visit(
                        root,
                        &child.expect("read fixture inventory child").path(),
                        inventory,
                    );
                }
            }
        }

        let mut inventory = FixtureInventory::new();
        visit(root, root, &mut inventory);
        inventory
    }

    fn relocated_inventory(
        before: &FixtureInventory,
        old_relative: &str,
        new_relative: &str,
    ) -> FixtureInventory {
        before
            .iter()
            .map(|(path, kind)| {
                let relocated = if path == old_relative {
                    new_relative.to_owned()
                } else if let Some(suffix) = path
                    .strip_prefix(old_relative)
                    .and_then(|tail| tail.strip_prefix('/'))
                {
                    format!("{new_relative}/{suffix}")
                } else {
                    path.clone()
                };
                (relocated, *kind)
            })
            .collect()
    }

    fn assert_inventory_unchanged(root: &Path, before: &FixtureInventory, label: &str) {
        assert_eq!(
            fixture_inventory(root),
            *before,
            "{label}: fixture inventory must remain unchanged"
        );
    }

    fn assert_inventory_relocated(
        root: &Path,
        before: &FixtureInventory,
        old_relative: &str,
        new_relative: &str,
        label: &str,
    ) {
        assert_eq!(
            fixture_inventory(root),
            relocated_inventory(before, old_relative, new_relative),
            "{label}: fixture inventory must match the exact path relocation",
        );
    }

    fn fixture(label: &str) -> Fixture {
        let temp = local_ntfs_fixture();
        assert!(
            !temp.path().to_string_lossy().starts_with(r"\\") && is_fixed_ntfs(temp.path()),
            "directory-handle rename probe requires a local fixed NTFS fixture: {}",
            temp.path().display()
        );
        let stage = temp.path().join("stage");
        let nested = stage.join("nested");
        std::fs::create_dir(&stage).unwrap();
        std::fs::create_dir(&nested).unwrap();
        let child_file = nested.join("payload.bin");
        let bytes = match label {
            "legacy" => b"legacy probe payload" as &'static [u8],
            _ => b"extended probe payload" as &'static [u8],
        };
        std::fs::write(&child_file, bytes).unwrap();
        let stage_id = filesystem_identity(&stage, crate::directory::EntryKind::Folder);
        let child_id = filesystem_identity(&nested, crate::directory::EntryKind::Folder);
        let file_id = filesystem_identity(&child_file, crate::directory::EntryKind::File);
        Fixture {
            temp,
            stage,
            nested,
            child_file,
            bytes,
            stage_id,
            child_id,
            file_id,
        }
    }

    fn is_fixed_ntfs(path: &Path) -> bool {
        let root = path.ancestors().last().unwrap();
        let wide: Vec<u16> = root
            .as_os_str()
            .encode_wide()
            .chain(std::iter::once(0))
            .collect();
        let mut filesystem = [0u16; 32];
        let fixed = unsafe { GetDriveTypeW(PCWSTR(wide.as_ptr())) } == 3;
        let ntfs = unsafe {
            GetVolumeInformationW(
                PCWSTR(wide.as_ptr()),
                None,
                None,
                None,
                None,
                Some(&mut filesystem),
            )
        }
        .is_ok()
            && String::from_utf16_lossy(&filesystem)
                .trim_end_matches('\0')
                .eq_ignore_ascii_case("NTFS");
        fixed && ntfs
    }

    fn held_directory_identity(
        file: &std::fs::File,
    ) -> crate::filesystem_identity::FilesystemIdentity {
        let mut info = ::windows::Win32::Storage::FileSystem::BY_HANDLE_FILE_INFORMATION::default();
        unsafe { GetFileInformationByHandle(HANDLE(file.as_raw_handle().cast()), &mut info) }
            .expect("read identity from exact held child handle");
        crate::filesystem_identity::FilesystemIdentity::from_windows_parts(
            info.dwVolumeSerialNumber,
            (u64::from(info.nFileIndexHigh) << 32) | u64::from(info.nFileIndexLow),
        )
    }

    fn create_foreign_at_empty_child_path(
        fixture: &Fixture,
        original_id: &crate::filesystem_identity::FilesystemIdentity,
    ) {
        let before = fixture_inventory(fixture.temp.path());
        let foreign_file = fixture.nested.join("foreign.bin");
        let foreign_bytes = b"fixture-owned replacement sentinel";
        std::fs::create_dir(&fixture.nested)
            .expect("create distinct fixture-owned directory at empty child path");
        std::fs::write(&foreign_file, foreign_bytes).unwrap();
        let foreign_id = filesystem_identity(&fixture.nested, crate::directory::EntryKind::Folder);
        eprintln!(
            "namespace: foreign child path identity = {foreign_id:?}; moved original identity = {original_id:?}"
        );
        assert_ne!(
            foreign_id, *original_id,
            "replacement must be a distinct directory object"
        );
        assert_eq!(std::fs::read(foreign_file).unwrap(), foreign_bytes);
        let mut expected = before;
        expected.insert(("stage/nested".into(), "directory"));
        expected.insert(("stage/nested/foreign.bin".into(), "file"));
        assert_eq!(
            fixture_inventory(fixture.temp.path()),
            expected,
            "foreign replacement inventory must be exact"
        );
    }

    fn verify_child_move(
        label: &str,
        fixture: &Fixture,
        moved_child: &Path,
        child_handle: &std::fs::File,
        captured_child_id: &crate::filesystem_identity::FilesystemIdentity,
    ) -> Option<crate::filesystem_identity::FilesystemIdentity> {
        let held_id = held_directory_identity(child_handle);
        let moved_id = moved_child
            .exists()
            .then(|| filesystem_identity(moved_child, crate::directory::EntryKind::Folder));
        let original_path_absent = !fixture.nested.exists();
        let moved_payload = moved_child.join("payload.bin");
        let moved_file_id = moved_payload
            .exists()
            .then(|| filesystem_identity(&moved_payload, crate::directory::EntryKind::File));
        let moved_bytes = std::fs::read(&moved_payload).ok();
        let conclusive = held_id == *captured_child_id
            && moved_id.as_ref() == Some(captured_child_id)
            && original_path_absent
            && moved_file_id.as_ref() == Some(&fixture.file_id)
            && moved_bytes.as_deref() == Some(fixture.bytes);
        eprintln!(
            "{label}: move postconditions conclusive={conclusive}; held_id={held_id:?}; moved_id={moved_id:?}; original_path_absent={original_path_absent}; moved_file_id={moved_file_id:?}; moved_bytes_match={}",
            moved_bytes.as_deref() == Some(fixture.bytes),
        );
        if conclusive {
            assert_eq!(held_id, *captured_child_id);
            assert_eq!(moved_id.as_ref(), Some(captured_child_id));
            assert!(original_path_absent);
            assert_eq!(moved_file_id.as_ref(), Some(&fixture.file_id));
            assert_eq!(moved_bytes.as_deref(), Some(fixture.bytes));
            Some(captured_child_id.clone())
        } else {
            eprintln!(
                "{label}: inconclusive native success; do not classify as a no-delete-sharing guard bypass"
            );
            None
        }
    }

    fn run_child_namespace_probe() {
        let path_fixture = fixture("namespace-path");
        let moved_child = path_fixture.temp.path().join("nested-moved");
        let child_handle = open_child_without_delete_sharing(&path_fixture.nested);
        let held_child_id = held_directory_identity(&child_handle);
        assert_eq!(
            held_child_id, path_fixture.child_id,
            "held no-follow handle must refer to the captured child"
        );

        let before_path_rename = fixture_inventory(path_fixture.temp.path());
        let replacement = std::fs::rename(&path_fixture.nested, &moved_child);
        eprintln!(
            "namespace: std::fs::rename child = {:?}, win32={:?}",
            replacement,
            replacement
                .as_ref()
                .err()
                .and_then(std::io::Error::raw_os_error)
        );
        if replacement.is_ok() {
            assert_inventory_relocated(
                path_fixture.temp.path(),
                &before_path_rename,
                "stage/nested",
                "nested-moved",
                "std::fs::rename child",
            );
            if let Some(moved_id) = verify_child_move(
                "namespace: std::fs::rename",
                &path_fixture,
                &moved_child,
                &child_handle,
                &held_child_id,
            ) {
                create_foreign_at_empty_child_path(&path_fixture, &moved_id);
            }
        } else {
            assert_inventory_unchanged(
                path_fixture.temp.path(),
                &before_path_rename,
                "failed std::fs::rename child",
            );
            assert_eq!(
                filesystem_identity(&path_fixture.nested, crate::directory::EntryKind::Folder),
                path_fixture.child_id
            );
            assert_eq!(
                std::fs::read(&path_fixture.child_file).unwrap(),
                path_fixture.bytes
            );
        }
        drop(child_handle);
        drop(path_fixture);

        let handle_fixture = fixture("namespace-handle");
        let child_handle = open_child_without_delete_sharing(&handle_fixture.nested);
        let held_child_id = held_directory_identity(&child_handle);
        assert_eq!(held_child_id, handle_fixture.child_id);
        let moved_child = handle_fixture.temp.path().join("nested-handle-moved");
        let wide: Vec<u16> = handle_fixture
            .nested
            .as_os_str()
            .encode_wide()
            .chain(std::iter::once(0))
            .collect();
        let delete_open = unsafe {
            CreateFileW(
                ::windows::core::PCWSTR(wide.as_ptr()),
                DELETE.0 | FILE_READ_ATTRIBUTES.0,
                FILE_SHARE_READ | FILE_SHARE_WRITE,
                None,
                OPEN_EXISTING,
                FILE_FLAG_BACKUP_SEMANTICS | FILE_FLAG_OPEN_REPARSE_POINT,
                None,
            )
        };
        let before_handle_rename = fixture_inventory(handle_fixture.temp.path());
        match delete_open {
            Ok(delete_handle) => {
                let delete_result = rename_info(delete_handle, &moved_child, FileRenameInfo, false);
                eprintln!(
                    "namespace: independent DELETE handle open=ok; FileRenameInfo={}",
                    native_result(delete_result)
                );
                unsafe { ::windows::Win32::Foundation::CloseHandle(delete_handle).unwrap() };
                if delete_result.is_ok() {
                    assert_inventory_relocated(
                        handle_fixture.temp.path(),
                        &before_handle_rename,
                        "stage/nested",
                        "nested-handle-moved",
                        "independent DELETE handle rename",
                    );
                    if let Some(moved_id) = verify_child_move(
                        "namespace: DELETE-handle FileRenameInfo",
                        &handle_fixture,
                        &moved_child,
                        &child_handle,
                        &held_child_id,
                    ) {
                        create_foreign_at_empty_child_path(&handle_fixture, &moved_id);
                    }
                } else {
                    assert_inventory_unchanged(
                        handle_fixture.temp.path(),
                        &before_handle_rename,
                        "failed independent DELETE handle rename",
                    );
                }
            }
            Err(error) => {
                eprintln!(
                    "namespace: independent DELETE handle open denied, HRESULT={:#010x}",
                    error.code().0 as u32
                );
                assert_inventory_unchanged(
                    handle_fixture.temp.path(),
                    &before_handle_rename,
                    "denied independent DELETE handle open",
                );
            }
        }
        drop(child_handle);
        drop(handle_fixture);
    }

    fn run_variant(label: &str, class: FILE_INFO_BY_HANDLE_CLASS, ex: bool) {
        let fixture = fixture(label);
        let child_handle = open_child_without_delete_sharing(&fixture.nested);
        assert_eq!(held_directory_identity(&child_handle), fixture.child_id);
        let stage_handle = open_directory_for_rename(&fixture.stage);
        let destination = fixture.temp.path().join("published-stage");
        let before_rename = fixture_inventory(fixture.temp.path());
        let result = rename_info(
            HANDLE(stage_handle.as_raw_handle().cast()),
            &destination,
            class,
            ex,
        );
        eprintln!(
            "{label}: stage-root rename result = {}",
            native_result(result)
        );
        match result {
            Ok(()) => {
                assert_inventory_relocated(
                    fixture.temp.path(),
                    &before_rename,
                    "stage",
                    "published-stage",
                    label,
                );
                assert_eq!(
                    filesystem_identity(&destination, crate::directory::EntryKind::Folder),
                    fixture.stage_id
                );
                assert_eq!(
                    filesystem_identity(
                        &destination.join("nested"),
                        crate::directory::EntryKind::Folder
                    ),
                    fixture.child_id
                );
                assert_eq!(
                    filesystem_identity(
                        &destination.join("nested/payload.bin"),
                        crate::directory::EntryKind::File
                    ),
                    fixture.file_id
                );
                assert_eq!(
                    std::fs::read(destination.join("nested/payload.bin")).unwrap(),
                    fixture.bytes
                );
            }
            Err(_) => {
                assert_inventory_unchanged(fixture.temp.path(), &before_rename, label);
                assert_eq!(
                    filesystem_identity(&fixture.stage, crate::directory::EntryKind::Folder),
                    fixture.stage_id
                );
                assert_eq!(
                    filesystem_identity(&fixture.nested, crate::directory::EntryKind::Folder),
                    fixture.child_id
                );
                assert_eq!(
                    filesystem_identity(&fixture.child_file, crate::directory::EntryKind::File),
                    fixture.file_id
                );
                assert_eq!(std::fs::read(&fixture.child_file).unwrap(), fixture.bytes);
            }
        }
        drop(child_handle);
        drop(stage_handle);
        drop(fixture);
    }

    fn run_no_child_handle_baseline(label: &str, class: FILE_INFO_BY_HANDLE_CLASS, ex: bool) {
        let fixture = fixture(label);
        let stage_handle = open_directory_for_rename(&fixture.stage);
        let held_root_id = held_directory_identity(&stage_handle);
        assert_eq!(
            held_root_id, fixture.stage_id,
            "baseline root handle must match captured stage identity"
        );
        let destination = fixture.temp.path().join("baseline-published-stage");
        let before_rename = fixture_inventory(fixture.temp.path());
        let result = rename_info(
            HANDLE(stage_handle.as_raw_handle().cast()),
            &destination,
            class,
            ex,
        );
        eprintln!(
            "{label}: no-child-handle baseline result = {}",
            native_result(result)
        );
        match result {
            Ok(()) => {
                assert_inventory_relocated(
                    fixture.temp.path(),
                    &before_rename,
                    "stage",
                    "baseline-published-stage",
                    label,
                );
                let root_id = crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &destination,
                    crate::directory::EntryKind::Folder,
                )
                .expect("observe baseline destination root without following reparse points")
                .filesystem_identity();
                let child_path = destination.join("nested");
                let child_id = crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &child_path,
                    crate::directory::EntryKind::Folder,
                )
                .expect("observe baseline child without following reparse points")
                .filesystem_identity();
                let file_path = child_path.join("payload.bin");
                let file_id = crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &file_path,
                    crate::directory::EntryKind::File,
                )
                .expect("observe baseline payload without following reparse points")
                .filesystem_identity();
                let bytes_match =
                    std::fs::read(destination.join("nested/payload.bin")).unwrap() == fixture.bytes;
                let identities_match = root_id == held_root_id
                    && root_id == fixture.stage_id
                    && child_id == fixture.child_id
                    && file_id == fixture.file_id;
                eprintln!(
                    "{label}: baseline is {} identity-wise; root={root_id:?}/{held_root_id:?}/{:?}, child={child_id:?}/{:?}, file={file_id:?}/{:?}, old_path_absent={}, bytes_match={bytes_match}",
                    if identities_match {
                        "confirmed"
                    } else {
                        "inconclusive"
                    },
                    fixture.stage_id,
                    fixture.child_id,
                    fixture.file_id,
                    !fixture.stage.exists(),
                );
                assert!(
                    identities_match,
                    "successful baseline must preserve exact root, child, and file identities"
                );
                assert!(
                    !fixture.stage.exists(),
                    "successful baseline must leave the old stage path absent"
                );
                assert!(
                    bytes_match,
                    "successful baseline must preserve fixture bytes"
                );
            }
            Err(_) => {
                assert_inventory_unchanged(fixture.temp.path(), &before_rename, label);
                assert_eq!(
                    filesystem_identity(&fixture.stage, crate::directory::EntryKind::Folder),
                    fixture.stage_id
                );
                assert_eq!(
                    filesystem_identity(&fixture.nested, crate::directory::EntryKind::Folder),
                    fixture.child_id
                );
                assert_eq!(
                    filesystem_identity(&fixture.child_file, crate::directory::EntryKind::File),
                    fixture.file_id
                );
                assert_eq!(std::fs::read(&fixture.child_file).unwrap(), fixture.bytes);
                assert!(
                    !destination.exists(),
                    "failed baseline must not publish a destination"
                );
            }
        }
        drop(stage_handle);
        drop(fixture);
    }

    run_child_namespace_probe();
    run_no_child_handle_baseline("FileRenameInfoEx flags=0", FileRenameInfoEx, true);
    run_variant("FileRenameInfo", FileRenameInfo, false);
    run_variant("FileRenameInfoEx flags=0", FileRenameInfoEx, true);

    let control = fixture("collision control");
    let sentinel = control.temp.path().join("collision");
    std::fs::create_dir(&sentinel).unwrap();
    let sentinel_file = sentinel.join("sentinel.bin");
    let sentinel_bytes = b"do not replace this collision sentinel";
    std::fs::write(&sentinel_file, sentinel_bytes).unwrap();
    let sentinel_id = filesystem_identity(&sentinel, crate::directory::EntryKind::Folder);
    let before_collision = fixture_inventory(control.temp.path());
    let stage_handle = open_directory_for_rename(&control.stage);
    let collision = rename_info(
        HANDLE(stage_handle.as_raw_handle().cast()),
        &sentinel,
        FileRenameInfo,
        false,
    );
    eprintln!(
        "collision control: FileRenameInfo result = {}",
        native_result(collision)
    );
    assert!(
        collision.is_err(),
        "no-replace rename must reject existing destination"
    );
    assert_eq!(
        filesystem_identity(&sentinel, crate::directory::EntryKind::Folder),
        sentinel_id
    );
    assert_eq!(std::fs::read(&sentinel_file).unwrap(), sentinel_bytes);
    assert_eq!(
        filesystem_identity(&control.stage, crate::directory::EntryKind::Folder),
        control.stage_id
    );
    assert_inventory_unchanged(
        control.temp.path(),
        &before_collision,
        "no-replace collision control",
    );
    run_no_child_handle_baseline("FileRenameInfo", FileRenameInfo, false);
}

#[cfg(target_os = "windows")]
fn external_cleanup_request(
    sources: Vec<PathBuf>,
    source_identities: Vec<crate::filesystem_identity::FilesystemIdentity>,
) -> OperationRequest {
    let parent_routes = sources
        .iter()
        .map(|source| {
            let mut parents = source
                .parent()
                .unwrap()
                .ancestors()
                .map(Path::to_path_buf)
                .collect::<Vec<_>>();
            parents.reverse();
            parents
                .into_iter()
                .map(|path| super::super::model::SourceCleanupParentIdentity {
                    identity: filesystem_identity(&path, crate::directory::EntryKind::Folder),
                    path,
                })
                .collect()
        })
        .collect();
    let leaf_signatures = sources
        .iter()
        .map(|source| {
            let file = std::fs::File::open(source).expect("open cleanup test source");
            #[cfg(windows)]
            {
                windows::leaf_signature(&file).expect("capture test source signature")
            }
            #[cfg(not(windows))]
            {
                let _ = file;
                super::super::model::SourceCleanupLeafSignature {
                    number_of_links: 1,
                    change_time: 7,
                }
            }
        })
        .collect();
    OperationRequest {
        kind: OperationKind::ExternalMoveCleanup,
        virtual_source: None,
        sources,
        destination: None,
        move_identity_guard: None,
        clipboard_move_source_evidence: None,
        rename_reparse_guard: None,
        move_destination_identity_guard: None,
        move_replace_source_evidence: None,
        trash_source_guards: None,
        source_cleanup_identity_guard: Some(super::super::model::SourceCleanupIdentityGuard {
            source_identities,
            parent_routes,
            leaf_signatures,
        }),
        initial_conflict_policy: None,
        copy_destination_identity_guard: None,
        create_parent_directory_identity_guard: None,
        zip_create_guard: None,
        shortcut_create_guard: None,
        seven_zip_create_guard: None,
        seven_zip_extract_guard: None,
        origin: None,
        batch_rename_plan: None,
    }
}

#[cfg(target_os = "windows")]
fn run_external_cleanup(
    request: OperationRequest,
    retry_items: Vec<ItemId>,
    cancelled: &AtomicBool,
    on_fact: impl FnMut(&ExecutorFact),
) -> Vec<ExecutorFact> {
    let paths = request.sources.clone();
    let routes = request
        .source_cleanup_identity_guard
        .as_ref()
        .unwrap()
        .parent_routes
        .clone();
    let signatures = request
        .source_cleanup_identity_guard
        .as_ref()
        .unwrap()
        .leaf_signatures
        .clone();
    let handles = paths
        .iter()
        .map(std::fs::File::open)
        .collect::<Result<Vec<_>, _>>()
        .expect("cleanup test source handles");
    run_external_cleanup_with_lease(
        request,
        retry_items,
        super::super::runtime::SourceCleanupLease::from_parts(paths, handles, routes, signatures),
        cancelled,
        on_fact,
    )
}

#[cfg(target_os = "windows")]
fn run_external_cleanup_with_lease(
    request: OperationRequest,
    retry_items: Vec<ItemId>,
    lease: super::super::runtime::SourceCleanupLease,
    cancelled: &AtomicBool,
    mut on_fact: impl FnMut(&ExecutorFact),
) -> Vec<ExecutorFact> {
    let mut service = OperationService::default();
    service.submit(request.clone()).unwrap();
    let ExecutorCommand::Prepare { token, .. } = service.start_next().unwrap() else {
        panic!("a submitted operation must prepare")
    };
    let command = ExecutorCommand::Prepare {
        token,
        request,
        retry_items,
        copy_retry_guards: Vec::new(),
        copy_directory_retry_guards: Vec::new(),
        cross_volume_move_retry_guards: Vec::new(),
    };
    let (_controls_sender, controls) = std::sync::mpsc::channel();
    let mut facts = Vec::new();
    execute_prepare_with_source_cleanup_lease(command, cancelled, &controls, Some(lease), |fact| {
        on_fact(&fact);
        facts.push(fact);
    });
    facts
}

#[test]
fn local_move_preflight_binds_the_submit_path_replacement_before_mutation() {
    let root = tempfile::tempdir().unwrap();
    let source = root.path().join("source.txt");
    let replacement = root.path().join("replacement.txt");
    let destination = root.path().join("destination");
    std::fs::write(&source, b"original entry").unwrap();
    std::fs::write(&replacement, b"replacement entry with a distinct size").unwrap();
    std::fs::create_dir(&destination).unwrap();

    let original_identity = crate::directory::EntrySourceIdentity::from_path(
        &source,
        crate::directory::EntryKind::File,
    )
    .unwrap()
    .filesystem_identity();
    std::fs::remove_file(&source).unwrap();
    std::fs::rename(&replacement, &source).unwrap();
    let worker_observed_identity = crate::directory::EntrySourceIdentity::from_path(
        &source,
        crate::directory::EntryKind::File,
    )
    .unwrap()
    .filesystem_identity();
    assert_ne!(original_identity, worker_observed_identity);
    let destination_identity = crate::directory::EntrySourceIdentity::from_path(
        &destination,
        crate::directory::EntryKind::Folder,
    )
    .unwrap()
    .filesystem_identity();

    let mut service = OperationService::default();
    let token = service
        .submit(OperationRequest {
            kind: OperationKind::Move,
            virtual_source: None,
            sources: vec![source.clone()],
            destination: Some(destination.clone()),
            move_identity_guard: Some(super::super::model::MoveIdentityGuard {
                source_identities: Vec::new(),
                destination_identity: destination_identity.clone(),
            }),
            clipboard_move_source_evidence: None,
            rename_reparse_guard: None,
            move_destination_identity_guard: None,
            move_replace_source_evidence: None,
            trash_source_guards: None,
            source_cleanup_identity_guard: None,
            initial_conflict_policy: None,
            copy_destination_identity_guard: None,
            create_parent_directory_identity_guard: None,
            zip_create_guard: None,
            shortcut_create_guard: None,
            seven_zip_create_guard: None,
            seven_zip_extract_guard: None,
            origin: None,
            batch_rename_plan: None,
        })
        .unwrap();
    let command = service.start_next().unwrap();
    let (_control_sender, controls) = std::sync::mpsc::channel();
    let mut facts = Vec::new();
    execute_prepare(command, &AtomicBool::new(false), &controls, |fact| {
        facts.push(fact)
    });

    let resolved_index = facts
        .iter()
        .position(|fact| matches!(fact, ExecutorFact::MoveGuardResolved { .. }))
        .expect("worker must report its preflight identity before mutation");
    let terminal_index = facts
        .iter()
        .position(|fact| matches!(fact, ExecutorFact::Terminal { .. }))
        .expect("worker must report a terminal result");
    assert!(resolved_index < terminal_index);
    assert!(matches!(
        &facts[resolved_index],
        ExecutorFact::MoveGuardResolved { token: resolved_token, guard }
            if *resolved_token == token
                && guard.source_identities == vec![worker_observed_identity]
                && guard.destination_identity == destination_identity
    ));
    assert!(matches!(
        &facts[terminal_index],
        ExecutorFact::Terminal { report, .. }
            if report.outcome == TerminalOutcome::Succeeded
    ));
    assert_eq!(
        std::fs::read(destination.join("source.txt")).unwrap(),
        b"replacement entry with a distinct size"
    );
    assert!(!source.exists());
}

