#[cfg(target_os = "windows")]
fn cleanup_terminal(facts: &[ExecutorFact]) -> &TerminalReport {
    let mut terminals = facts.iter().filter_map(|fact| match fact {
        ExecutorFact::Terminal { report, .. } => Some(report),
        _ => None,
    });
    let terminal = terminals.next().expect("cleanup emits a terminal report");
    assert!(
        terminals.next().is_none(),
        "cleanup emits one terminal report"
    );
    terminal
}

#[cfg(target_os = "windows")]
#[test]
fn external_move_cleanup_deletes_the_captured_file_and_hints_its_parent() {
    let root = tempfile::tempdir().unwrap();
    let source = root.path().join("source.txt");
    std::fs::write(&source, b"captured source").unwrap();
    let identity = filesystem_identity(&source, crate::directory::EntryKind::File);
    let facts = run_external_cleanup(
        external_cleanup_request(vec![source.clone()], vec![identity]),
        Vec::new(),
        &AtomicBool::new(false),
        |_| {},
    );

    assert!(!source.exists());
    let progress = facts
        .iter()
        .filter_map(|fact| match fact {
            ExecutorFact::Progress { update, .. } => Some(update),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(progress.len(), 1);
    assert_eq!(progress[0].sequence, 1);
    assert_eq!(progress[0].current_item, Some(ItemId(0)));
    assert_eq!(progress[0].counters.processed_items, 1);
    assert_eq!(progress[0].counters.total_items, Some(1));

    let report = cleanup_terminal(&facts);
    assert_eq!(report.outcome, TerminalOutcome::Succeeded);
    assert_eq!(report.receipts.len(), 1);
    assert_eq!(report.receipts[0].outcome, ItemOutcome::Completed);
    assert_eq!(report.receipts[0].move_receipt, None);
    assert_eq!(report.receipts[0].replace_receipt, None);
    assert_eq!(report.retry, RetryPlan::NotAllowed);
    assert_eq!(
        report.change_hints,
        vec![FsChangeHint {
            directory: root.path().to_path_buf(),
        }]
    );
}

