fn external_move_cleanup_retains_a_replacement_at_the_captured_path() {
    let root = tempfile::tempdir().unwrap();
    let source = root.path().join("source.txt");
    std::fs::write(&source, b"captured object").unwrap();
    let identity = filesystem_identity(&source, crate::directory::EntryKind::File);
    let request = external_cleanup_request(vec![source.clone()], vec![identity.clone()]);
    let guard = request.source_cleanup_identity_guard.as_ref().unwrap();
    let lease = super::super::runtime::SourceCleanupLease::from_parts(
        vec![source.clone()],
        vec![std::fs::File::open(&source).unwrap()],
        guard.parent_routes.clone(),
        guard.leaf_signatures.clone(),
    );
    std::fs::remove_file(&source).unwrap();
    std::fs::write(&source, b"replacement object").unwrap();
    assert_ne!(
        identity,
        filesystem_identity(&source, crate::directory::EntryKind::File)
    );

    let facts = run_external_cleanup_with_lease(
        request,
        Vec::new(),
        lease,
        &AtomicBool::new(false),
        |_| {},
    );

    assert_eq!(std::fs::read(&source).unwrap(), b"replacement object");
    let report = cleanup_terminal(&facts);
    assert_eq!(report.outcome, TerminalOutcome::Partial);
    assert_eq!(report.receipts.len(), 1);
    assert_eq!(report.receipts[0].outcome, ItemOutcome::Partial);
    assert!(
        report.receipts[0]
            .detail
            .as_deref()
            .is_some_and(|detail| detail.contains("identity changed"))
    );
    assert_eq!(report.receipts[0].move_receipt, None);
    assert_eq!(report.receipts[0].replace_receipt, None);
    assert_eq!(report.retry, RetryPlan::RequiresReinspection);
    assert!(report.change_hints.is_empty());
}

