#[test]
fn external_move_cleanup_rejects_replaced_parent_with_hardlink_to_original_leaf() {
    use ::windows::Win32::Storage::FileSystem::{
        FILE_READ_ATTRIBUTES, FILE_SHARE_DELETE, FILE_SHARE_READ,
    };
    use std::os::windows::fs::OpenOptionsExt;

    let root = tempfile::tempdir().unwrap();
    let parent = root.path().join("parent");
    std::fs::create_dir(&parent).unwrap();
    let source = parent.join("source.txt");
    std::fs::write(&source, b"original").unwrap();
    let identity = filesystem_identity(&source, crate::directory::EntryKind::File);
    let request = external_cleanup_request(vec![source.clone()], vec![identity.clone()]);
    let route = request
        .source_cleanup_identity_guard
        .as_ref()
        .unwrap()
        .parent_routes
        .clone();
    let signatures = request
        .source_cleanup_identity_guard
        .as_ref()
        .unwrap()
        .leaf_signatures
        .clone();
    let moved_parent = root.path().join("moved-parent");
    std::fs::rename(&parent, &moved_parent).unwrap();
    std::fs::create_dir(&parent).unwrap();
    std::fs::hard_link(moved_parent.join("source.txt"), &source).unwrap();
    let lease = super::super::runtime::SourceCleanupLease::from_parts(
        vec![source.clone()],
        vec![
            std::fs::OpenOptions::new()
                .access_mode(FILE_READ_ATTRIBUTES.0)
                .share_mode(FILE_SHARE_READ.0 | FILE_SHARE_DELETE.0)
                .open(moved_parent.join("source.txt"))
                .unwrap(),
        ],
        route,
        signatures,
    );

    let facts = run_external_cleanup_with_lease(
        request,
        Vec::new(),
        lease,
        &AtomicBool::new(false),
        |_| {},
    );

    assert!(
        source.exists(),
        "the planted old-path hard link must remain"
    );
    assert!(
        moved_parent.join("source.txt").exists(),
        "original source entry must remain"
    );
    assert_eq!(std::fs::read(&source).unwrap(), b"original");
    assert_eq!(
        cleanup_terminal(&facts).receipts[0].outcome,
        ItemOutcome::Partial
    );
}

