#[cfg(target_os = "windows")]
#[test]
fn external_move_cleanup_current_handle_blocks_mutation_after_lease_release() {
    use ::windows::Win32::Storage::FileSystem::{
        FILE_SHARE_DELETE, FILE_SHARE_READ, FILE_SHARE_WRITE, FILE_WRITE_DATA,
    };
    use std::os::windows::fs::OpenOptionsExt;

    let root = tempfile::tempdir().unwrap();
    let source = root.path().join("source.txt");
    std::fs::write(&source, b"captured source").unwrap();
    let identity = filesystem_identity(&source, crate::directory::EntryKind::File);
    let original = std::fs::File::open(&source).unwrap();
    let mut guard = external_cleanup_request(vec![source.clone()], vec![identity.clone()])
        .source_cleanup_identity_guard
        .unwrap();
    let route = guard.parent_routes.remove(0);
    let signature = guard.leaf_signatures.remove(0);
    let result = windows::cleanup_external_move_source_with_before_disposition(
        &source,
        &identity,
        &route,
        &signature,
        original,
        &AtomicBool::new(false),
        || {
            let write_open = std::fs::OpenOptions::new()
                .access_mode(FILE_WRITE_DATA.0)
                .share_mode(FILE_SHARE_READ.0 | FILE_SHARE_WRITE.0 | FILE_SHARE_DELETE.0)
                .open(&source);
            assert!(
                write_open.is_err(),
                "current source must reject write opens"
            );

            let delete_open = std::fs::OpenOptions::new()
                .access_mode(::windows::Win32::Storage::FileSystem::DELETE.0)
                .share_mode(FILE_SHARE_READ.0 | FILE_SHARE_WRITE.0 | FILE_SHARE_DELETE.0)
                .open(&source);
            assert!(
                delete_open.is_err(),
                "current source must reject delete/rename opens"
            );
        },
    );

    assert_eq!(result, Ok(()));
    assert!(!source.exists());
}

#[cfg(target_os = "windows")]
#[test]
fn external_move_cleanup_preserves_completed_receipt_when_cancel_races_after_disposition() {
    let root = tempfile::tempdir().unwrap();
    let source_parent = root.path().join("first");
    let remaining_parent = root.path().join("second");
    std::fs::create_dir(&source_parent).unwrap();
    std::fs::create_dir(&remaining_parent).unwrap();
    let source = source_parent.join("source.txt");
    let remaining = remaining_parent.join("remaining.txt");
    std::fs::write(&source, b"captured source").unwrap();
    std::fs::write(&remaining, b"not started").unwrap();
    let identities = vec![
        filesystem_identity(&source, crate::directory::EntryKind::File),
        filesystem_identity(&remaining, crate::directory::EntryKind::File),
    ];
    let cancelled = AtomicBool::new(false);
    let facts = run_external_cleanup(
        external_cleanup_request(vec![source.clone(), remaining.clone()], identities),
        Vec::new(),
        &cancelled,
        |fact| {
            if matches!(fact, ExecutorFact::Progress { update, .. } if update.current_item == Some(ItemId(0)))
            {
                cancelled.store(true, Ordering::Release);
            }
        },
    );

    assert!(!source.exists());
    assert!(remaining.exists());
    let report = cleanup_terminal(&facts);
    assert_eq!(report.outcome, TerminalOutcome::Partial);
    assert_eq!(report.receipts[0].outcome, ItemOutcome::Completed);
    assert_eq!(
        report.receipts[1].outcome,
        ItemOutcome::CancelledBeforeStart
    );
    assert_eq!(report.final_counters.processed_items, 1);
    assert_eq!(
        report.change_hints,
        vec![FsChangeHint {
            directory: source_parent
        }]
    );
    assert_eq!(report.retry, RetryPlan::RequiresReinspection);
}

#[cfg(target_os = "windows")]
#[test]
fn external_move_cleanup_rejects_invalid_identity_shape_destination_and_retry() {
    let root = tempfile::tempdir().unwrap();
    let source = root.path().join("source.txt");
    std::fs::write(&source, b"captured source").unwrap();
    let identity = filesystem_identity(&source, crate::directory::EntryKind::File);

    let mut bad_length = external_cleanup_request(vec![source.clone()], vec![identity.clone()]);
    bad_length
        .source_cleanup_identity_guard
        .as_mut()
        .unwrap()
        .source_identities
        .clear();
    let bad_type = external_cleanup_request(
        vec![source.clone()],
        vec![
            crate::filesystem_identity::FilesystemIdentity::from_fallback_token(
                "not-a-windows-file-id".into(),
            ),
        ],
    );
    let mut fake_destination =
        external_cleanup_request(vec![source.clone()], vec![identity.clone()]);
    fake_destination.destination = Some(root.path().to_path_buf());
    let mut reused_guard = external_cleanup_request(vec![source.clone()], vec![identity.clone()]);
    reused_guard.move_identity_guard = Some(super::super::model::MoveIdentityGuard {
        source_identities: vec![identity.clone()],
        destination_identity: filesystem_identity(root.path(), crate::directory::EntryKind::Folder),
    });

    for request in [bad_length, bad_type, fake_destination, reused_guard] {
        let facts = run_external_cleanup(request, Vec::new(), &AtomicBool::new(false), |_| {});
        let report = cleanup_terminal(&facts);
        assert_eq!(report.outcome, TerminalOutcome::Failed);
        assert!(report.receipts.is_empty());
        assert!(report.change_hints.is_empty());
        assert!(source.exists());
    }

    let facts = run_external_cleanup(
        external_cleanup_request(vec![source.clone()], vec![identity.clone()]),
        vec![ItemId(0)],
        &AtomicBool::new(false),
        |_| {},
    );
    assert_eq!(cleanup_terminal(&facts).outcome, TerminalOutcome::Failed);
    assert!(source.exists());

    let cleanup_guard = external_cleanup_request(
        vec![source.clone()],
        vec![filesystem_identity(
            &source,
            crate::directory::EntryKind::File,
        )],
    )
    .source_cleanup_identity_guard
    .unwrap();
    let leaked_guard = OperationRequest {
        kind: OperationKind::Copy,
        virtual_source: None,
        sources: vec![source.clone()],
        destination: Some(root.path().to_path_buf()),
        move_identity_guard: None,
        clipboard_move_source_evidence: None,
        rename_reparse_guard: None,
        move_destination_identity_guard: None,
        move_replace_source_evidence: None,
        trash_source_guards: None,
        source_cleanup_identity_guard: Some(super::super::model::SourceCleanupIdentityGuard {
            source_identities: vec![identity],
            parent_routes: cleanup_guard.parent_routes,
            leaf_signatures: cleanup_guard.leaf_signatures,
        }),
        initial_conflict_policy: None,
        copy_destination_identity_guard: None,
        create_parent_directory_identity_guard: None,
        zip_create_guard: None,
        shortcut_create_guard: None,
        seven_zip_create_guard: None,
        seven_zip_extract_guard: None,
        origin: None,
        batch_rename_plan: None,
    };
    let facts = run_external_cleanup(
        leaked_guard.clone(),
        Vec::new(),
        &AtomicBool::new(false),
        |_| {},
    );
    assert_eq!(cleanup_terminal(&facts).outcome, TerminalOutcome::Failed);
    assert!(source.exists());
}

