#[cfg(target_os = "windows")]
fn cross_volume_test_root() -> Option<PathBuf> {
    use ::windows::{Win32::Storage::FileSystem::GetDriveTypeW, core::PCWSTR};
    use std::path::{Component, Prefix};

    // Win32 DRIVE_FIXED is the stable value returned by GetDriveTypeW.
    const DRIVE_FIXED: u32 = 3;

    let root = match std::env::var_os("GPUI_FILER_CROSS_VOLUME_TEST_ROOT") {
        Some(root) => PathBuf::from(root),
        None => {
            eprintln!("skipping cross-volume test: GPUI_FILER_CROSS_VOLUME_TEST_ROOT is not set");
            return None;
        }
    };
    if !root.is_absolute() {
        eprintln!("skipping cross-volume test: test root must be an absolute local path");
        return None;
    }
    let Some(Component::Prefix(prefix)) = root.components().next() else {
        eprintln!("skipping cross-volume test: test root must be a drive path");
        return None;
    };
    let Prefix::Disk(letter) = prefix.kind() else {
        eprintln!("skipping cross-volume test: test root must not be UNC or mapped");
        return None;
    };

    let drive_root = format!("{}:\\", char::from(letter));
    let mut wide = drive_root.encode_utf16().collect::<Vec<_>>();
    wide.push(0);
    let drive_type = unsafe { GetDriveTypeW(PCWSTR(wide.as_ptr())) };
    if drive_type != DRIVE_FIXED {
        eprintln!("skipping cross-volume test: test root is not on a fixed drive");
        return None;
    }

    Some(root)
}

#[cfg(target_os = "windows")]
fn cross_volume_test_has_different_drive(source: &Path, destination: &Path) -> bool {
    fn drive_letter(path: &Path) -> Option<u8> {
        match path.components().next() {
            Some(std::path::Component::Prefix(prefix)) => match prefix.kind() {
                std::path::Prefix::Disk(letter) | std::path::Prefix::VerbatimDisk(letter) => {
                    Some(letter.to_ascii_uppercase())
                }
                _ => None,
            },
            _ => None,
        }
    }

    drive_letter(source) != drive_letter(destination)
}

#[test]
fn copy_throttle_is_opt_in_and_bounded() {
    assert_eq!(copy_throttle_from(None), None);
    assert_eq!(copy_throttle_from(Some(OsStr::new("0"))), None);
    assert_eq!(copy_throttle_from(Some(OsStr::new("nope"))), None);
    assert_eq!(
        copy_throttle_from(Some(OsStr::new("25"))),
        Some(Duration::from_millis(25))
    );
    assert_eq!(
        copy_throttle_from(Some(OsStr::new("999"))),
        Some(Duration::from_millis(COPY_THROTTLE_MAX_MS))
    );
}

#[cfg(target_os = "windows")]
#[test]
fn copy_and_move_a_junction_as_its_own_reparse_object() {
    let root = tempfile::tempdir().unwrap();
    let target = root.path().join("target");
    let junction = root.path().join("junction");
    let destination = root.path().join("destination");
    std::fs::create_dir(&target).unwrap();
    std::fs::create_dir(&destination).unwrap();
    std::fs::write(target.join("inside.txt"), b"must not copy").unwrap();
    let status = std::process::Command::new("cmd")
        .args(["/C", "mklink", "/J"])
        .arg(&junction)
        .arg(&target)
        .status()
        .unwrap();
    assert!(status.success(), "mklink /J must create the test junction");

    let mut service = OperationService::default();
    service
        .submit(OperationRequest {
            kind: OperationKind::Copy,
            virtual_source: None,
            sources: vec![junction.clone()],
            destination: Some(destination.clone()),
            move_identity_guard: None,
            clipboard_move_source_evidence: None,
            rename_reparse_guard: None,
            move_destination_identity_guard: None,
            move_replace_source_evidence: None,
            trash_source_guards: None,
            source_cleanup_identity_guard: None,
            initial_conflict_policy: None,
            copy_destination_identity_guard: None,
            create_parent_directory_identity_guard: None,
            zip_create_guard: None,
            shortcut_create_guard: None,
            seven_zip_create_guard: None,
            seven_zip_extract_guard: None,
            origin: None,
            batch_rename_plan: None,
        })
        .unwrap();
    let command = service.start_next().unwrap();
    let (_controls_sender, controls) = std::sync::mpsc::channel();
    let mut terminal = None;
    execute_prepare(command, &AtomicBool::new(false), &controls, |fact| {
        if let ExecutorFact::Terminal { report, .. } = fact {
            terminal = Some(report);
        }
    });

    let report = terminal.expect("junction copy must terminate");
    assert_eq!(report.outcome, TerminalOutcome::Succeeded);
    assert_eq!(report.receipts.len(), 1);
    assert_eq!(report.receipts[0].outcome, ItemOutcome::Completed);
    assert!(junction.exists());
    let copied = destination.join("junction");
    assert!(copied.symlink_metadata().unwrap().file_type().is_symlink());
    assert_eq!(
        std::fs::read(copied.join("inside.txt")).unwrap(),
        b"must not copy"
    );

    let moved_destination = root.path().join("moved");
    std::fs::create_dir(&moved_destination).unwrap();
    let mut service = OperationService::default();
    service
        .submit(OperationRequest {
            kind: OperationKind::Move,
            virtual_source: None,
            sources: vec![copied.clone()],
            destination: Some(moved_destination.clone()),
            move_identity_guard: None,
            clipboard_move_source_evidence: None,
            rename_reparse_guard: None,
            move_destination_identity_guard: None,
            move_replace_source_evidence: None,
            trash_source_guards: None,
            source_cleanup_identity_guard: None,
            initial_conflict_policy: None,
            copy_destination_identity_guard: None,
            create_parent_directory_identity_guard: None,
            zip_create_guard: None,
            shortcut_create_guard: None,
            seven_zip_create_guard: None,
            seven_zip_extract_guard: None,
            origin: None,
            batch_rename_plan: None,
        })
        .unwrap();
    let command = service.start_next().unwrap();
    let (_controls_sender, controls) = std::sync::mpsc::channel();
    let mut terminal = None;
    execute_prepare(command, &AtomicBool::new(false), &controls, |fact| {
        if let ExecutorFact::Terminal { report, .. } = fact {
            terminal = Some(report);
        }
    });
    let report = terminal.expect("junction move must terminate");
    assert_eq!(report.outcome, TerminalOutcome::Succeeded);
    assert_eq!(report.receipts[0].outcome, ItemOutcome::Completed);
    assert!(copied.symlink_metadata().is_err());
    let moved = moved_destination.join("junction");
    assert!(moved.symlink_metadata().unwrap().file_type().is_symlink());
    assert_eq!(
        std::fs::read(moved.join("inside.txt")).unwrap(),
        b"must not copy"
    );
    assert_eq!(
        std::fs::read(target.join("inside.txt")).unwrap(),
        b"must not copy"
    );
}

