#[cfg(windows)]
#[test]
fn ordinary_copy_stage_cleanup_failure_is_partial_with_exact_stage_custody() {
    let root = tempfile::tempdir().unwrap();
    let source = root.path().join("source.bin");
    let destination = root.path().join("destination.bin");
    std::fs::write(&source, b"staged bytes").unwrap();
    let cancelled = AtomicBool::new(false);
    let clean_result =
        windows::copy_regular_file_with_undo(&source, &destination, &cancelled, &mut |_| {
            cancelled.store(true, Ordering::Release);
        });
    assert_eq!(clean_result, Err(CopyError::Cancelled));
    assert!(!destination.exists());
    assert_eq!(std::fs::read_dir(root.path()).unwrap().count(), 1);

    cancelled.store(false, Ordering::Release);
    windows::set_copy_test_faults(true, false);
    let result =
        windows::copy_regular_file_with_undo(&source, &destination, &cancelled, &mut |_| {
            cancelled.store(true, Ordering::Release);
        });
    assert!(matches!(&result, Err(CopyError::PrePublishPartial(_))));
    let detail = match result {
        Err(CopyError::PrePublishPartial(detail)) => detail,
        other => panic!("expected unresolved staged copy, got {other:?}"),
    };
    let stage_text = detail
        .split("pre-publication stage cleanup failed at ")
        .nth(1)
        .and_then(|tail| tail.split(" (original operation error:").next())
        .expect("detail contains exact stage path");
    let stage = PathBuf::from(stage_text);
    assert!(
        stage.exists(),
        "failed cleanup must retain exact owned stage"
    );
    assert_eq!(std::fs::read(stage).unwrap(), b"staged bytes");
    assert!(!destination.exists());
    assert!(detail.contains("original operation error: Cancelled"));
    assert!(detail.contains("cleanup error: Io(\"injected cleanup failure\")"));
}

#[cfg(windows)]
#[test]
fn ordinary_copy_adapter_emits_typed_prepublication_and_postpublication_failure_facts() {
    use crate::operations::model::{CopyPublicationState, ItemId};
    let root = tempfile::tempdir().unwrap();
    let source = root.path().join("source-provenance.bin");
    let destination = root.path().join("destination-provenance.bin");
    std::fs::write(&source, b"preserve source bytes").unwrap();
    let cancelled = AtomicBool::new(false);
    windows::set_copy_test_faults(true, false);
    let mut observations = Vec::new();
    let result = windows::copy_regular_file_with_undo_observed(
        &source,
        &destination,
        &cancelled,
        ItemId(3),
        &mut |_| cancelled.store(true, Ordering::Release),
        &mut |fact| observations.push(fact),
        None,
    );
    assert!(matches!(result, Err(CopyError::PrePublishPartial(_))));
    let evidence = observations
        .pop()
        .expect("cleanup failure has typed evidence");
    assert_eq!(evidence.item, ItemId(3));
    assert_eq!(evidence.source, source);
    assert_eq!(evidence.destination, destination);
    assert_eq!(evidence.publication, CopyPublicationState::NotPublished);
    assert!(evidence.source_identity.is_some() && evidence.source_signature.is_some());
    let stage = evidence
        .stage
        .expect("retained stage came from the owned handle");
    assert!(stage.identity.is_some());
    assert!(stage.path.exists());
    assert!(!root.path().join("destination-provenance.bin").exists());
    assert_eq!(std::fs::read(&source).unwrap(), b"preserve source bytes");
    assert_eq!(std::fs::read(stage.path).unwrap(), b"preserve source bytes");

    windows::set_copy_test_faults(false, true);
    cancelled.store(false, Ordering::Release);
    observations.clear();
    let result = windows::copy_regular_file_with_undo_observed(
        &source,
        &destination,
        &cancelled,
        ItemId(3),
        &mut |_| {},
        &mut |fact| observations.push(fact),
        None,
    );
    assert!(matches!(result, Err(CopyError::Unknown(_))));
    let evidence = observations
        .pop()
        .expect("postpublish receipt failure has typed evidence");
    assert_eq!(evidence.publication, CopyPublicationState::Published);
    assert!(destination.exists());
    assert_eq!(std::fs::read(&source).unwrap(), b"preserve source bytes");
}

#[cfg(windows)]
#[test]
fn ordinary_copy_failure_inspection_matches_stage_while_original_custody_is_held() {
    use crate::operations::model::{
        AttemptToken, CopyFailureInspectionCandidate, CopyFailureInspectionResult,
        CopyInspectionState as State, InspectionTicket, ItemId,
    };
    use std::sync::atomic::{AtomicBool, Ordering};

    let root = tempfile::tempdir_in(env!("CARGO_MANIFEST_DIR")).unwrap();
    let parent = root.path().join("destination-parent");
    std::fs::create_dir(&parent).unwrap();
    let source = root.path().join("source.bin");
    let destination = parent.join("source.bin");
    std::fs::write(
        &source,
        b"source data long enough to enter the retained stage",
    )
    .unwrap();
    let cancelled = AtomicBool::new(false);
    windows::set_copy_test_faults(true, false);
    let mut provenance = None;
    let mut custody = None;
    let result = windows::copy_regular_file_with_undo_observed_and_custody(
        Some(AttemptToken::fixture()),
        &source,
        &destination,
        &cancelled,
        ItemId(0),
        &mut |_| cancelled.store(true, Ordering::Release),
        &mut |fact| provenance = Some(fact),
        &mut |capability| custody = Some(capability),
        None,
    );
    assert!(matches!(result, Err(CopyError::PrePublishPartial(_))));
    let provenance = provenance.expect("failed production Copy emits provenance");
    let custody = custody.expect("failed production Copy returns original strict handle");
    assert_eq!(custody.path, provenance.stage.as_ref().unwrap().path);
    let inspected = super::inspect_copy_failure_candidates(CopyFailureInspectionResult {
        ticket: InspectionTicket::new(1),
        attempt: custody.token,
        candidates: vec![CopyFailureInspectionCandidate {
            provenance,
            source: State::Indeterminate,
            destination_parent: State::Indeterminate,
            destination: State::Indeterminate,
            stage: State::Indeterminate,
            stage_content: State::Indeterminate,
        }],
        directory_candidates: vec![],
    });
    assert_eq!(inspected.candidates[0].source, State::Matches);
    assert_eq!(inspected.candidates[0].destination_parent, State::Matches);
    assert_eq!(inspected.candidates[0].destination, State::Absent);
    assert_eq!(inspected.candidates[0].stage, State::Matches);
    assert_eq!(inspected.candidates[0].stage_content, State::Indeterminate);
    assert!(
        custody.path.exists(),
        "the observed retained stage remains present"
    );
}

#[cfg(windows)]
#[test]
fn ordinary_copy_failure_probe_reports_changes_without_mutating_objects() {
    use crate::operations::model::{
        AttemptToken, CopyFailureInspectionCandidate, CopyFailureInspectionResult,
        CopyInspectionState as State, CopyPublicationState, InspectionTicket, ItemId,
    };

    fn capture_prepublication(
        source: &std::path::Path,
        destination: &std::path::Path,
    ) -> crate::operations::model::CopyFailureProvenance {
        std::fs::write(source, b"probe source bytes").unwrap();
        let cancelled = AtomicBool::new(false);
        windows::set_copy_test_faults(true, false);
        let mut facts = Vec::new();
        let result = windows::copy_regular_file_with_undo_observed(
            source,
            destination,
            &cancelled,
            ItemId(7),
            &mut |_| cancelled.store(true, Ordering::Release),
            &mut |fact| facts.push(fact),
            None,
        );
        assert!(matches!(result, Err(CopyError::PrePublishPartial(_))));
        let fact = facts.pop().expect("typed prepublication evidence");
        assert_eq!(fact.publication, CopyPublicationState::NotPublished);
        fact
    }

    fn inspect(
        provenance: &crate::operations::model::CopyFailureProvenance,
    ) -> (State, State, State, State) {
        windows::inspect_copy_failure(provenance)
    }

    fn file_identity(path: &std::path::Path) -> crate::filesystem_identity::FilesystemIdentity {
        windows::prepare_regular_file_source(path)
            .unwrap()
            .shared_identity()
            .unwrap()
    }

    let root = tempfile::tempdir_in(env!("CARGO_MANIFEST_DIR")).unwrap();
    let parent = root.path().join("parent");
    std::fs::create_dir(&parent).unwrap();
    let source = root.path().join("source.bin");
    let destination = parent.join("destination.bin");
    let evidence = capture_prepublication(&source, &destination);
    let stage = evidence.stage.as_ref().unwrap().path.clone();
    let stage_id = evidence.stage.as_ref().unwrap().identity.clone().unwrap();
    let original_source = std::fs::read(&source).unwrap();
    let original_stage = std::fs::read(&stage).unwrap();
    assert_eq!(inspect(&evidence).0, State::Matches);
    assert_eq!(inspect(&evidence).1, State::Matches);
    assert_eq!(inspect(&evidence).3, State::Matches);
    let inspected = super::inspect_copy_failure_candidates(CopyFailureInspectionResult {
        ticket: InspectionTicket::new(1),
        attempt: AttemptToken::fixture(),
        candidates: vec![CopyFailureInspectionCandidate {
            provenance: evidence.clone(),
            source: State::Indeterminate,
            destination_parent: State::Indeterminate,
            destination: State::Indeterminate,
            stage: State::Indeterminate,
            stage_content: State::Matches,
        }],
        directory_candidates: vec![],
    });
    assert_eq!(inspected.candidates[0].stage, State::Matches);
    assert_eq!(inspected.candidates[0].stage_content, State::Indeterminate);

    // Same pathname with a different file identity is changed.
    let displaced = root.path().join("source-displaced.bin");
    std::fs::rename(&source, &displaced).unwrap();
    std::fs::write(&source, b"replacement source bytes").unwrap();
    assert_eq!(inspect(&evidence).0, State::Changed);
    assert_eq!(std::fs::read(&displaced).unwrap(), original_source);
    assert_eq!(file_identity(&stage), stage_id);

    // Restore the same source identity, then change its observed signature.
    std::fs::remove_file(&source).unwrap();
    std::fs::rename(&displaced, &source).unwrap();
    let restored_source_id = file_identity(&source);
    std::fs::write(&source, b"modified source bytes with another length").unwrap();
    assert_eq!(inspect(&evidence).0, State::Changed);
    assert_eq!(file_identity(&source), restored_source_id);

    // A reused stage path is not the object observed through the owned handle.
    let replacement_stage = stage.with_extension("saved");
    std::fs::rename(&stage, &replacement_stage).unwrap();
    std::fs::write(&stage, b"replacement stage bytes").unwrap();
    assert_eq!(inspect(&evidence).3, State::Changed);
    assert_eq!(std::fs::read(&replacement_stage).unwrap(), original_stage);
    assert_eq!(file_identity(&replacement_stage), stage_id);

    // Replacing the destination parent changes its identity at the same path.
    let parent_marker = parent.join("marker.bin");
    std::fs::write(&parent_marker, b"parent remains untouched").unwrap();
    let old_parent = root.path().join("old-parent");
    std::fs::rename(&parent, &old_parent).unwrap();
    std::fs::create_dir(&parent).unwrap();
    assert_eq!(inspect(&evidence).1, State::Changed);
    assert_eq!(
        std::fs::read(old_parent.join("marker.bin")).unwrap(),
        b"parent remains untouched"
    );

    // Published remains historical when its destination is later absent or replaced.
    let mut published = evidence.clone();
    published.publication = CopyPublicationState::Published;
    published.destination_parent_identity = evidence.destination_parent_identity.clone();
    published.destination = parent.join("published.bin");
    std::fs::write(&published.destination, b"published output bytes").unwrap();
    let output_id = file_identity(&published.destination);
    published.stage = Some(crate::operations::model::CopyStageObservation {
        path: published.destination.clone(),
        identity: Some(output_id.clone()),
    });
    assert_eq!(inspect(&published).2, State::Matches);
    let parked_output = parent.join("parked-published-output.bin");
    std::fs::rename(&published.destination, &parked_output).unwrap();
    assert_eq!(inspect(&published).2, State::Absent);
    assert_eq!(published.publication, CopyPublicationState::Published);
    assert_eq!(file_identity(&parked_output), output_id);
    std::fs::write(&published.destination, b"replacement output bytes").unwrap();
    let replacement_output_id = file_identity(&published.destination);
    assert_ne!(replacement_output_id, output_id);
    assert_eq!(inspect(&published).2, State::Changed);
    assert_eq!(published.publication, CopyPublicationState::Published);
    assert_eq!(
        std::fs::read(&published.destination).unwrap(),
        b"replacement output bytes"
    );
    assert_eq!(file_identity(&published.destination), replacement_output_id);
    assert_eq!(file_identity(&parked_output), output_id);

    let mut unknown = published.clone();
    unknown.publication = CopyPublicationState::Unknown;
    std::fs::remove_file(&unknown.destination).unwrap();
    assert_eq!(inspect(&unknown).2, State::Absent);
    assert_eq!(unknown.publication, CopyPublicationState::Unknown);

    // A sharing violation is a real lookup/open error, reported as indeterminate.
    let blocked_source = root.path().join("blocked-source.bin");
    let blocked_destination = parent.join("blocked-destination.bin");
    let mut blocked = capture_prepublication(&blocked_source, &blocked_destination);
    let blocker =
        std::os::windows::fs::OpenOptionsExt::share_mode(std::fs::OpenOptions::new().read(true), 0)
            .open(&blocked_source)
            .unwrap();
    assert_eq!(inspect(&blocked).0, State::Indeterminate);
    drop(blocker);

    // Inspection itself leaves observed source and stage bytes and identities intact.
    assert_eq!(
        std::fs::read(&blocked_source).unwrap(),
        b"probe source bytes"
    );
    let blocked_stage = blocked.stage.take().unwrap();
    assert_eq!(
        std::fs::read(&blocked_stage.path).unwrap(),
        b"probe source bytes"
    );
    assert_eq!(
        file_identity(&blocked_stage.path),
        blocked_stage.identity.unwrap(),
    );
    assert_eq!(
        file_identity(&blocked_source),
        blocked.source_identity.clone().unwrap(),
    );
}

#[cfg(windows)]
#[test]
fn retained_copy_stage_cleanup_uses_original_strict_handle_and_cancel_is_no_effect() {
    use ::windows::Win32::{
        Foundation::{GENERIC_READ, GENERIC_WRITE},
        Storage::FileSystem::{DELETE, FILE_SHARE_READ},
    };
    use std::os::windows::fs::OpenOptionsExt;

    let root = local_ntfs_fixture();
    let stage = root.path().join(".gpui-filer-copy-retained-stage");
    let moved = root.path().join("moved-stage");
    std::fs::write(&stage, b"retained stage sentinel").unwrap();
    let token = AttemptToken::fixture();
    let open_strict = || {
        std::fs::OpenOptions::new()
            .read(true)
            .write(true)
            .access_mode(GENERIC_READ.0 | GENERIC_WRITE.0 | DELETE.0)
            .share_mode(FILE_SHARE_READ.0)
            .open(&stage)
            .unwrap()
    };
    let lease = || {
        let handle = open_strict();
        super::super::runtime::CopyStageCleanupLease {
            token,
            item: ItemId(0),
            path: stage.clone(),
            identity: filesystem_identity(&stage, crate::directory::EntryKind::File),
            parent_identity: filesystem_identity(root.path(), crate::directory::EntryKind::Folder),
            handle,
            native_disposition_observer: None,
        }
    };

    assert!(matches!(
        windows::cleanup_copy_stage_handle(lease(), &AtomicBool::new(true)),
        Err(CopyError::Cancelled)
    ));
    assert_eq!(std::fs::read(&stage).unwrap(), b"retained stage sentinel");

    let held = lease();
    assert!(
        std::fs::OpenOptions::new()
            .write(true)
            .open(&stage)
            .is_err()
    );
    assert!(std::fs::remove_file(&stage).is_err());
    assert!(std::fs::rename(&stage, &moved).is_err());
    assert_eq!(std::fs::read(&stage).unwrap(), b"retained stage sentinel");
    assert!(windows::cleanup_copy_stage_handle(held, &AtomicBool::new(false)).unwrap());
    assert!(!stage.exists());
    assert!(!moved.exists());
}

#[cfg(windows)]
#[test]
fn ordinary_copy_retry_revalidates_open_handles_before_new_stage_and_keeps_old_stage() {
    use crate::operations::model::{CopyRetryGuard, ItemId};

    let root = tempfile::tempdir_in(env!("CARGO_MANIFEST_DIR")).unwrap();
    let parent = root.path().join("parent");
    std::fs::create_dir(&parent).unwrap();
    let source = root.path().join("source.bin");
    let destination = parent.join("source.bin");
    std::fs::write(&source, b"source bytes for guarded retry").unwrap();

    // Simulate the exact NotPublished failure class while leaving its owned old stage behind.
    windows::set_copy_test_faults(true, false);
    let cancelled = AtomicBool::new(false);
    let mut provenance = Vec::new();
    let failed = windows::copy_regular_file_with_undo_observed(
        &source,
        &destination,
        &cancelled,
        ItemId(0),
        &mut |bytes| {
            if bytes > 0 {
                cancelled.store(true, Ordering::Release);
            }
        },
        &mut |fact| provenance.push(fact),
        None,
    );
    assert!(matches!(failed, Err(CopyError::PrePublishPartial(_))));
    let provenance = provenance.pop().unwrap();
    let old_stage = provenance.stage.unwrap().path;
    let old_stage_bytes = std::fs::read(&old_stage).unwrap();
    assert!(!destination.exists());
    let guard = CopyRetryGuard {
        item: ItemId(0),
        source: source.clone(),
        destination: destination.clone(),
        source_identity: provenance.source_identity.unwrap(),
        source_signature: provenance.source_signature.unwrap(),
        destination_parent_identity: provenance.destination_parent_identity.unwrap(),
    };

    // A changed confirmation signature fails before allocating or mutating another stage.
    std::fs::write(&source, b"source changed after inspection").unwrap();
    let mut rejected_facts = Vec::new();
    let rejected = windows::copy_regular_file_with_undo_observed(
        &source,
        &destination,
        &AtomicBool::new(false),
        ItemId(0),
        &mut |_| {},
        &mut |fact| rejected_facts.push(fact),
        Some(&guard),
    );
    assert!(matches!(rejected, Err(CopyError::Io(_))));
    assert_eq!(rejected_facts.len(), 1);
    assert_eq!(
        rejected_facts[0].publication,
        crate::operations::model::CopyPublicationState::NotPublished
    );
    assert_ne!(
        rejected_facts[0].source_signature,
        Some(guard.source_signature),
        "fresh failure provenance records the current source for a new inspection"
    );
    assert!(!destination.exists());
    assert_eq!(std::fs::read(&old_stage).unwrap(), old_stage_bytes);

    // A fresh inspection of the changed source may authorize a new attempt; the old stage
    // remains untouched while the new copy publishes.
    let opened_source = windows::prepare_regular_file_source(&source).unwrap();
    let signature_file = std::fs::File::open(&source).unwrap();
    let fresh_guard = CopyRetryGuard {
        source_identity: opened_source.shared_identity().unwrap(),
        source_signature: windows::leaf_signature(&signature_file).unwrap(),
        ..guard
    };
    let retried = windows::copy_regular_file_with_undo_observed(
        &source,
        &destination,
        &AtomicBool::new(false),
        ItemId(0),
        &mut |_| {},
        &mut |_| {},
        Some(&fresh_guard),
    )
    .unwrap();
    assert_eq!(
        std::fs::read(&destination).unwrap(),
        b"source changed after inspection"
    );
    assert_eq!(std::fs::read(&old_stage).unwrap(), old_stage_bytes);
    assert_eq!(retried.destination, destination);

    let entries_before_collision = std::fs::read_dir(&parent).unwrap().count();
    let mut collision_facts = Vec::new();
    let collision = windows::copy_regular_file_with_undo_observed(
        &source,
        &destination,
        &AtomicBool::new(false),
        ItemId(0),
        &mut |_| {},
        &mut |fact| collision_facts.push(fact),
        Some(&fresh_guard),
    );
    assert!(matches!(collision, Err(CopyError::DestinationExists)));
    assert_eq!(collision_facts.len(), 1);
    assert_eq!(
        collision_facts[0].publication,
        crate::operations::model::CopyPublicationState::NotPublished
    );
    assert_eq!(
        std::fs::read_dir(&parent).unwrap().count(),
        entries_before_collision
    );
    assert_eq!(
        std::fs::read(&destination).unwrap(),
        b"source changed after inspection"
    );
}

