#[cfg(windows)]
#[test]
fn copy_undo_refuses_replaced_or_modified_outputs() {
    // hardlink substitution requires a filesystem that supports hard links.
    let root = tempfile::tempdir_in(env!("CARGO_MANIFEST_DIR")).unwrap();
    let source = root.path().join("source.bin");
    let destination = root.path().join("destination.bin");
    std::fs::write(&source, b"copy-time bytes").unwrap();

    let replacement_receipt = windows::copy_regular_file_with_undo(
        &source,
        &destination,
        &AtomicBool::new(false),
        &mut |_| {},
    )
    .unwrap();
    std::fs::remove_file(&destination).unwrap();
    std::fs::write(&destination, b"replacement object").unwrap();
    assert!(windows::undo_copy(&replacement_receipt).is_err());
    assert_eq!(std::fs::read(&destination).unwrap(), b"replacement object");

    std::fs::remove_file(&destination).unwrap();
    let modified_receipt = windows::copy_regular_file_with_undo(
        &source,
        &destination,
        &AtomicBool::new(false),
        &mut |_| {},
    )
    .unwrap();
    std::fs::write(&destination, b"same object changed").unwrap();
    assert!(windows::undo_copy(&modified_receipt).is_err());
    assert_eq!(std::fs::read(&destination).unwrap(), b"same object changed");

    std::fs::remove_file(&destination).unwrap();
    let alias_receipt = windows::copy_regular_file_with_undo(
        &source,
        &destination,
        &AtomicBool::new(false),
        &mut |_| {},
    )
    .unwrap();
    let saved_alias = root.path().join("saved-output.bin");
    std::fs::rename(&destination, &saved_alias).unwrap();
    std::fs::hard_link(&saved_alias, &destination).unwrap();
    assert!(windows::undo_copy(&alias_receipt).is_err());
    assert_eq!(std::fs::read(&destination).unwrap(), b"copy-time bytes");
    assert_eq!(std::fs::read(&saved_alias).unwrap(), b"copy-time bytes");
}
