#[test]
fn exact_byte_total_is_only_advertised_for_regular_file_batches() {
    let root = tempfile::tempdir().unwrap();
    let first = root.path().join("first.bin");
    let second = root.path().join("second.bin");
    let empty = root.path().join("empty.bin");
    let directory = root.path().join("directory");
    std::fs::write(&first, b"123").unwrap();
    std::fs::write(&second, b"12345").unwrap();
    std::fs::write(&empty, []).unwrap();
    std::fs::create_dir(&directory).unwrap();

    assert_eq!(known_regular_file_bytes(&[first, second]), Some(8));
    assert_eq!(known_regular_file_bytes(&[directory]), None);

    let first = root.path().join("first.bin");
    let second = root.path().join("second.bin");
    let directory = root.path().join("directory");
    assert_eq!(known_regular_file_count(&[first, second]), Some(2));
    assert_eq!(known_regular_file_count(&[directory]), None);

    let first = root.path().join("first.bin");
    let second = root.path().join("second.bin");
    let empty = root.path().join("empty.bin");
    let directory = root.path().join("directory");
    assert_eq!(
        known_regular_file_facts(&[first, directory, second, empty]),
        (3, 8)
    );
}
