#[test]
fn tagged_executor_facts_commit_to_the_current_attempt_only() {
    let root = tempfile::tempdir().unwrap();
    let source = root.path().join("source");
    let destination = root.path().join("destination");
    std::fs::write(&source, b"contents").unwrap();
    std::fs::create_dir(&destination).unwrap();
    let request = OperationRequest {
        kind: OperationKind::Copy,
        virtual_source: None,
        sources: vec![source],
        destination: Some(destination.clone()),
        move_identity_guard: None,
        clipboard_move_source_evidence: None,
        rename_reparse_guard: None,
        move_destination_identity_guard: None,
        move_replace_source_evidence: None,
        trash_source_guards: None,
        source_cleanup_identity_guard: None,
        initial_conflict_policy: None,
        copy_destination_identity_guard: None,
        create_parent_directory_identity_guard: None,
        zip_create_guard: None,
        shortcut_create_guard: None,
        seven_zip_create_guard: None,
        seven_zip_extract_guard: None,
        origin: None,
        batch_rename_plan: None,
    };
    let mut service = OperationService::default();
    let token = service.submit(request).unwrap();
    let command = service.start_next().unwrap();
    assert!(service.prepared(token));
    let (_control, controls) = std::sync::mpsc::channel();
    execute_prepare(
        command,
        &AtomicBool::new(false),
        &controls,
        |fact| match fact {
            ExecutorFact::OrdinaryCopySourceKind {
                token: actual,
                item,
                kind,
            } => {
                assert_eq!(actual, token);
                assert_eq!(item, ItemId(0));
                assert_eq!(kind, super::OrdinaryCopySourceKind::File);
            }
            ExecutorFact::Conflict { .. } => panic!("destination was fresh"),
            ExecutorFact::Progress { token, update } => {
                assert!(service.progress(token, update))
            }
            ExecutorFact::TrashReceipt { .. } => panic!("copy cannot produce a trash receipt"),
            ExecutorFact::ReplaceBackupIntent { .. } => {
                panic!("ordinary copy cannot enter a replace backup barrier")
            }
            ExecutorFact::MoveGuardResolved { .. } => {
                panic!("ordinary copy cannot preflight a guarded move")
            }
            ExecutorFact::GuardedMoveNoEffectProof { .. } => {
                panic!("ordinary copy cannot prove a guarded move had no effect")
            }
            ExecutorFact::CrossVolumeMoveNoEffectProof { .. }
            | ExecutorFact::PublishedMoveSourceRetained { .. }
            | ExecutorFact::PublishedMoveDisposition { .. } => {
                panic!("ordinary copy cannot emit Move retry or disposition proofs")
            }
            ExecutorFact::CrossVolumeMoveReplacePhaseIntent { .. } => {
                panic!("ordinary copy cannot enter cross-volume Move Replace phases")
            }
            ExecutorFact::BatchRenamePlanIntent { .. }
            | ExecutorFact::RenameStageIntent { .. }
            | ExecutorFact::BatchRenameItemCompleted { .. }
            | ExecutorFact::DirectoryMoveManifestIntent { .. }
            | ExecutorFact::DirectoryMoveChildIntent { .. }
            | ExecutorFact::DirectoryMoveChildDisposition { .. }
            | ExecutorFact::DirectoryMoveRootIntent { .. }
            | ExecutorFact::DirectoryMoveRootDisposition { .. }
            | ExecutorFact::DirectoryMoveComplete { .. }
            | ExecutorFact::DirectoryMoveReplacePhaseIntent { .. }
            | ExecutorFact::DirectoryMoveReplaceBackupIntent { .. }
            | ExecutorFact::DirectoryMoveReplaceBackupDisposition { .. }
            | ExecutorFact::DirectoryMoveReplaceBackupComplete { .. }
            | ExecutorFact::DirectoryMoveReplaceRenamePhaseIntent { .. }
            | ExecutorFact::DirectoryMoveReplaceRenameCleanupIntent { .. }
            | ExecutorFact::DirectoryMoveReplaceRenameCleanupDisposition { .. }
            | ExecutorFact::DirectoryMoveReplaceRenameBackupComplete { .. }
            | ExecutorFact::CopyReplaceCleanupManifestIntent { .. }
            | ExecutorFact::CopyReplaceCleanupChildIntent { .. }
            | ExecutorFact::CopyReplaceCleanupChildDisposition { .. }
            | ExecutorFact::CopyReplaceCleanupComplete { .. }
            | ExecutorFact::ZipCreateLedgerIntent { .. }
            | ExecutorFact::SevenZipCreateLedgerIntent { .. }
            | ExecutorFact::ZipExtractLedgerIntent { .. }
            | ExecutorFact::CopyFailureProvenance { .. }
            | ExecutorFact::CopyDirectoryRetryProvenance { .. }
            | ExecutorFact::CopyStageCustody { .. }
            | ExecutorFact::CreatedObjectUndoCandidate { .. }
            | ExecutorFact::DirectoryCopyUndoCandidate { .. }
            | ExecutorFact::MoveUndoCandidate { .. }
            | ExecutorFact::SevenZipExtractBatchIntent { .. } => {
                panic!("ordinary copy cannot enter a rename barrier")
            }
            ExecutorFact::Terminal { token, report } => {
                assert!(service.terminal(token, report).is_some())
            }
        },
    );
    let snapshot = service.job(token.job_id()).unwrap();
    assert_eq!(
        snapshot.attempts[0].state,
        crate::operations::model::AttemptState::Terminal
    );
    assert_eq!(
        std::fs::read(destination.join("source")).unwrap(),
        b"contents"
    );
}

#[cfg(target_os = "windows")]
#[test]
fn ordinary_directory_copy_undo_removes_only_the_exact_unchanged_tree() {
    use super::DirectoryCopyUndoResult;
    let fixture_root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("target/tmp");
    std::fs::create_dir_all(&fixture_root).unwrap();
    let fixture = tempfile::tempdir_in(&fixture_root).unwrap();
    let source = fixture.path().join("source");
    let parent = fixture.path().join("destination-parent");
    let destination = parent.join("source");
    std::fs::create_dir_all(source.join("nested/empty")).unwrap();
    std::fs::create_dir_all(&parent).unwrap();
    std::fs::write(source.join("root.bin"), b"root payload").unwrap();
    std::fs::write(source.join("nested/leaf.bin"), b"nested payload").unwrap();

    let receipt = super::windows::copy_directory_for_test_with_undo(&source, &destination)
        .unwrap()
        .expect("bounded successful tree captures Undo");
    assert_eq!(
        std::fs::read(destination.join("nested/leaf.bin")).unwrap(),
        b"nested payload"
    );
    assert_eq!(
        super::undo_directory_copy(receipt, super::DirectoryCopyUndoCustodySlot::default()),
        DirectoryCopyUndoResult::Removed
    );
    assert!(!destination.exists(), "exact tree was removed");
    assert_eq!(
        std::fs::read(source.join("root.bin")).unwrap(),
        b"root payload"
    );

    let destination = parent.join("source-edited");
    let receipt = super::windows::copy_directory_for_test_with_undo(&source, &destination)
        .unwrap()
        .expect("second successful tree captures Undo");
    let foreign = destination.join("nested/foreign.bin");
    std::fs::write(&foreign, b"foreign data").unwrap();
    let custody = super::DirectoryCopyUndoCustodySlot::default();
    assert!(matches!(
        super::undo_directory_copy(receipt, custody.clone()),
        DirectoryCopyUndoResult::Refused(_)
    ));
    assert!(
        !custody.is_occupied(),
        "no-effect refusal retains the receipt without unresolved native custody"
    );
    assert_eq!(std::fs::read(&foreign).unwrap(), b"foreign data");
    assert_eq!(
        std::fs::read(destination.join("root.bin")).unwrap(),
        b"root payload"
    );

    for root_close in [false, true] {
        let destination = parent.join(if root_close {
            "source-root-close"
        } else {
            "source-child-close"
        });
        let receipt = super::windows::copy_directory_for_test_with_undo(&source, &destination)
            .unwrap()
            .expect("fault fixture has a bounded successful Copy proof");
        let custody = super::DirectoryCopyUndoCustodySlot::default();
        custody.inject_cleanup_close_fault_for_test(root_close);
        let worker_custody = custody.clone();
        let result =
            std::thread::spawn(move || super::undo_directory_copy(receipt, worker_custody))
                .join()
                .expect("cleanup worker returns normally");
        assert!(matches!(result, DirectoryCopyUndoResult::Partial(_)));
        assert!(
            custody.is_occupied(),
            "accepted disposition leaves passive custody in the application slot"
        );
        assert!(
            super::close_directory_copy_undo_injected_handle_after_terminal_for_test(&custody),
            "test driver releases this invocation's injected uncertain native handle only after native return"
        );
        drop(custody);
    }
}

#[cfg(target_os = "windows")]
#[test]
fn empty_directory_copy_root_close_uncertainty_is_partial_and_nonreplayable() {
    use super::DirectoryCopyUndoResult;
    let fixture_root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("target/tmp");
    std::fs::create_dir_all(&fixture_root).unwrap();
    let fixture = tempfile::tempdir_in(&fixture_root).unwrap();
    let source = fixture.path().join("empty-source");
    let parent = fixture.path().join("destination-parent");
    let destination = parent.join("empty-source");
    std::fs::create_dir(&source).unwrap();
    std::fs::create_dir(&parent).unwrap();

    let receipt = super::windows::copy_directory_for_test_with_undo(&source, &destination)
        .unwrap()
        .expect("empty successful Copy captures bounded root proof");
    assert!(receipt.entries.is_empty());
    let custody = super::DirectoryCopyUndoCustodySlot::default();
    custody.inject_cleanup_close_fault_for_test(true);
    let worker_custody = custody.clone();
    let result = std::thread::spawn(move || super::undo_directory_copy(receipt, worker_custody))
        .join()
        .expect("cleanup worker returns normally");
    assert!(
        matches!(result, DirectoryCopyUndoResult::Partial(_)),
        "root close uncertainty follows an accepted root disposition"
    );
    assert!(
        custody.is_occupied(),
        "the application slot retains root custody after worker return"
    );
    assert!(
        super::close_directory_copy_undo_injected_handle_after_terminal_for_test(&custody),
        "test driver closes this invocation's injected raw handle only after the worker returned"
    );
    assert!(
        !destination.exists(),
        "the accepted empty-root disposition completes after the uncertain handle closes"
    );
    drop(custody);
}

#[cfg(target_os = "windows")]
#[test]
fn folder_copy_publishes_a_complete_tree_only_after_the_staging_copy_finishes() {
    let root = local_ntfs_fixture();
    let source = root.path().join("source");
    let destination = root.path().join("destination");
    std::fs::create_dir(&source).unwrap();
    std::fs::create_dir(&destination).unwrap();
    std::fs::create_dir(source.join("nested")).unwrap();
    std::fs::create_dir(source.join("nested-empty")).unwrap();
    std::fs::write(source.join("top.txt"), b"top").unwrap();
    std::fs::write(source.join("second-top.txt"), b"ok").unwrap();
    std::fs::write(source.join("nested").join("child.txt"), b"child").unwrap();
    let mut service = OperationService::default();
    let token = service
        .submit(OperationRequest {
            kind: OperationKind::Copy,
            virtual_source: None,
            sources: vec![source.clone()],
            destination: Some(destination.clone()),
            move_identity_guard: None,
            clipboard_move_source_evidence: None,
            rename_reparse_guard: None,
            move_destination_identity_guard: None,
            move_replace_source_evidence: None,
            trash_source_guards: None,
            source_cleanup_identity_guard: None,
            initial_conflict_policy: None,
            copy_destination_identity_guard: None,
            create_parent_directory_identity_guard: None,
            zip_create_guard: None,
            shortcut_create_guard: None,
            seven_zip_create_guard: None,
            seven_zip_extract_guard: None,
            origin: None,
            batch_rename_plan: None,
        })
        .unwrap();

    let completed_files = RefCell::new(0);
    let discoveries = RefCell::new(Vec::new());
    copy_entry_no_clobber(
        &source,
        &destination.join("source"),
        token,
        ItemId(0),
        &AtomicBool::new(false),
        |_| {},
        || *completed_files.borrow_mut() += 1,
        |items, bytes| discoveries.borrow_mut().push((items, bytes)),
    )
    .unwrap();

    // Direct children are enumerated before the first copy starts, so the
    // initially known denominator does not oscillate per copied file. The
    // two direct files are one notification, the nested file another.
    assert_eq!(*completed_files.borrow(), 3);
    assert_eq!(discoveries.into_inner(), vec![(2, 5), (1, 5)]);

    assert_eq!(
        std::fs::read(destination.join("source/top.txt")).unwrap(),
        b"top"
    );
    assert_eq!(
        std::fs::read(destination.join("source/second-top.txt")).unwrap(),
        b"ok"
    );
    assert_eq!(
        std::fs::read(destination.join("source/nested/child.txt")).unwrap(),
        b"child"
    );
    assert!(destination.join("source/nested-empty").is_dir());
    assert!(std::fs::read_dir(&destination).unwrap().all(|entry| {
        !entry
            .unwrap()
            .file_name()
            .to_string_lossy()
            .starts_with(".gpui-filer-copy-")
    }));
}

#[cfg(target_os = "windows")]
#[test]
fn ordinary_directory_copy_rejects_late_source_junction_substitution() {
    use std::os::windows::fs::MetadataExt;

    let root = local_ntfs_fixture();
    assert_fixed_ntfs_fixture(root.path());
    let source = root.path().join("late-source-substitution");
    let destination_parent = root.path().join("late-destination");
    let destination = destination_parent.join("published");
    std::fs::create_dir(&source).unwrap();
    std::fs::create_dir(&destination_parent).unwrap();
    std::fs::write(source.join("a-control.bin"), b"ordinary control").unwrap();
    let later = source.join("z-later.bin");
    std::fs::write(&later, b"original enumerated file").unwrap();
    let outside = root.path().join("outside-payload");
    std::fs::create_dir(&outside).unwrap();
    let outside_sentinel = outside.join("sentinel.bin");
    let sentinel_bytes = b"outside target bytes must never be staged";
    std::fs::write(&outside_sentinel, sentinel_bytes).unwrap();
    let later_for_hook = later.clone();
    let outside_for_hook = outside.clone();
    let fired = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let hook_fired = fired.clone();
    windows::set_copy_directory_source_open_hook_for_test(move |candidate| {
        if candidate == later_for_hook && !hook_fired.swap(true, Ordering::AcqRel) {
            std::fs::remove_file(&later_for_hook)
                .expect("the enumerated source leaf is not opened before its admission hook");
            let status = std::process::Command::new("cmd.exe")
                .args(["/C", "mklink", "/J"])
                .arg(&later_for_hook)
                .arg(&outside_for_hook)
                .status()
                .expect("launch directory-junction fixture command");
            assert!(status.success(), "mklink /J must create the late junction");
        }
    });

    let result = super::copy_entry_no_clobber(
        &source,
        &destination,
        AttemptToken::fixture(),
        ItemId(0),
        &AtomicBool::new(false),
        |_| {},
        || {},
        |_, _| {},
    );

    assert!(
        fired.load(Ordering::Acquire),
        "the later enumerated leaf reached admission"
    );
    assert!(
        result.is_err(),
        "a no-follow opened reparse leaf must be rejected"
    );
    assert!(
        !destination.exists(),
        "a rejected source tree cannot be published"
    );
    assert_eq!(
        std::fs::read(source.join("a-control.bin")).unwrap(),
        b"ordinary control"
    );
    let later_metadata = std::fs::symlink_metadata(&later).unwrap();
    assert_ne!(
        later_metadata.file_attributes()
            & ::windows::Win32::Storage::FileSystem::FILE_ATTRIBUTE_REPARSE_POINT.0,
        0,
        "the fixture substitution must remain a reparse object"
    );
    assert_eq!(std::fs::read(&outside_sentinel).unwrap(), sentinel_bytes);
    assert!(!destination.join("z-later.bin").exists());
    assert!(
        !tree_contains_bytes(&destination_parent, sentinel_bytes),
        "outside target bytes must never enter staging"
    );
}

#[cfg(target_os = "windows")]
#[test]
#[ignore = "file symlink creation requires local privilege or Developer Mode; 1314 was observed on this host"]
fn ordinary_directory_copy_rejects_late_source_file_symlink_substitution() {
    use std::os::windows::fs::symlink_file;

    let root = local_ntfs_fixture();
    assert_fixed_ntfs_fixture(root.path());
    let source = root.path().join("late-file-symlink-source");
    let destination_parent = root.path().join("late-file-symlink-destination");
    let destination = destination_parent.join("published");
    let outside = root.path().join("late-file-symlink-outside.bin");
    let sentinel = b"outside file-symlink sentinel";
    std::fs::create_dir(&source).unwrap();
    std::fs::create_dir(&destination_parent).unwrap();
    std::fs::write(source.join("a-control.bin"), b"ordinary source control").unwrap();
    let later = source.join("z-later.bin");
    std::fs::write(&later, b"enumerated ordinary file").unwrap();
    std::fs::write(&outside, sentinel).unwrap();
    let hook_later = later.clone();
    let hook_outside = outside.clone();
    let fired = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let hook_fired = fired.clone();
    windows::set_copy_directory_source_open_hook_for_test(move |candidate| {
        if candidate == hook_later && !hook_fired.swap(true, Ordering::AcqRel) {
            std::fs::remove_file(&hook_later).expect("late leaf has not been opened yet");
            symlink_file(&hook_outside, &hook_later)
                .expect("file symlink fixture must be supported when this ignored test runs");
        }
    });

    let result = super::copy_entry_no_clobber(
        &source,
        &destination,
        AttemptToken::fixture(),
        ItemId(0),
        &AtomicBool::new(false),
        |_| {},
        || {},
        |_, _| {},
    );

    assert!(
        fired.load(Ordering::Acquire),
        "late file symlink substitution hook ran"
    );
    assert!(
        result.is_err(),
        "no-follow admission rejects the file symlink"
    );
    assert!(!destination.exists());
    assert_eq!(std::fs::read(outside).unwrap(), sentinel);
}

#[cfg(target_os = "windows")]
#[test]
fn ordinary_directory_copy_holds_strict_source_directory_leases() {
    use ::windows::Win32::Storage::FileSystem::{
        FILE_FLAG_BACKUP_SEMANTICS, FILE_FLAG_OPEN_REPARSE_POINT, FILE_SHARE_DELETE,
        FILE_SHARE_READ, FILE_SHARE_WRITE, FILE_WRITE_ATTRIBUTES, FILE_WRITE_DATA,
    };
    use std::os::windows::fs::OpenOptionsExt;

    let root = local_ntfs_fixture();
    assert_fixed_ntfs_fixture(root.path());
    let route = root.path().join("source-route");
    let source = route.join("source");
    let nested = source.join("nested");
    let nested_leaf = nested.join("leaf.bin");
    let destination_parent = root.path().join("lease-destination");
    let destination = destination_parent.join("published");
    std::fs::create_dir_all(&nested).unwrap();
    std::fs::create_dir(&destination_parent).unwrap();
    std::fs::write(source.join("root.bin"), b"root control bytes").unwrap();
    std::fs::write(&nested_leaf, b"nested control bytes").unwrap();
    std::fs::create_dir(source.join("nested-empty")).unwrap();
    let outside_tree = root.path().join("source-route-outside");
    std::fs::create_dir_all(outside_tree.join("source")).unwrap();
    let outside_sentinel = outside_tree.join("source/z-later.bin");
    let outside_bytes = b"unique outside route-rebind sentinel payload";
    std::fs::write(&outside_sentinel, outside_bytes).unwrap();
    assert_eq!(std::fs::read(&outside_sentinel).unwrap(), outside_bytes);

    let route_for_hook = route.clone();
    let source_for_hook = source.clone();
    let nested_for_hook = nested.clone();
    let route_held = route.with_file_name("source-route-held");
    let source_held = source.with_file_name("source-held");
    let nested_held = nested.with_file_name("nested-held");
    let route_held_for_hook = route_held.clone();
    let source_held_for_hook = source_held.clone();
    let nested_held_for_hook = nested_held.clone();

    // Copy lease 前に rename と reparse-write access が許可される fixture だと確認する。
    // Reparse conversion には FILE_WRITE_ATTRIBUTES と directory write access の両方を要求する。
    let write_attributes_reparse_conversion_open = |path: &Path| {
        std::fs::OpenOptions::new()
            .access_mode(FILE_WRITE_ATTRIBUTES.0 | FILE_WRITE_DATA.0)
            .share_mode(FILE_SHARE_READ.0 | FILE_SHARE_WRITE.0 | FILE_SHARE_DELETE.0)
            .custom_flags(FILE_FLAG_BACKUP_SEMANTICS.0 | FILE_FLAG_OPEN_REPARSE_POINT.0)
            .open(path)
    };
    for (path, held) in [
        (&route, &route_held),
        (&source, &source_held),
        (&nested, &nested_held),
    ] {
        std::fs::rename(path, held).unwrap_or_else(|error| {
            panic!("directory rename probe must work before Copy: {path:?}: {error:?}")
        });
        std::fs::rename(held, path).unwrap_or_else(|error| {
            panic!("directory rename probe must restore before Copy: {path:?}: {error:?}")
        });
    }
    for path in [&route, &source, &nested] {
        write_attributes_reparse_conversion_open(path).unwrap_or_else(|error| {
            panic!("write-attributes reparse probe must open before Copy: {path:?}: {error:?}")
        });
    }

    #[derive(Default)]
    struct LeaseProbe {
        hook_ran: bool,
        route_rename: Option<Result<(), Option<i32>>>,
        source_rename: Option<Result<(), Option<i32>>>,
        nested_rename: Option<Result<(), Option<i32>>>,
        route_reparse_write: Option<Result<(), Option<i32>>>,
        source_reparse_write: Option<Result<(), Option<i32>>>,
        nested_reparse_write: Option<Result<(), Option<i32>>>,
    }
    let probe_state = std::sync::Arc::new(std::sync::Mutex::new(LeaseProbe::default()));
    let fired = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let hook_fired = fired.clone();
    let hook_probe = probe_state.clone();
    let route_for_hook2 = route_for_hook.clone();
    let source_for_hook2 = source_for_hook.clone();
    let nested_for_hook2 = nested_for_hook.clone();
    let route_held_for_hook2 = route_held_for_hook.clone();
    let source_held_for_hook2 = source_held_for_hook.clone();
    let nested_held_for_hook2 = nested_held_for_hook.clone();
    let nested_leaf_for_hook = nested_leaf.clone();
    windows::set_copy_directory_source_open_hook_for_test(move |candidate| {
        if candidate != nested_leaf_for_hook || hook_fired.swap(true, Ordering::AcqRel) {
            return;
        }
        let route_rename = std::fs::rename(&route_for_hook2, &route_held_for_hook2)
            .map_err(|error| error.raw_os_error());
        let source_rename = std::fs::rename(&source_for_hook2, &source_held_for_hook2)
            .map_err(|error| error.raw_os_error());
        let nested_rename = std::fs::rename(&nested_for_hook2, &nested_held_for_hook2)
            .map_err(|error| error.raw_os_error());
        let route_reparse_write = write_attributes_reparse_conversion_open(&route_for_hook2)
            .map(|_| ())
            .map_err(|error| error.raw_os_error());
        let source_reparse_write = write_attributes_reparse_conversion_open(&source_for_hook2)
            .map(|_| ())
            .map_err(|error| error.raw_os_error());
        let nested_reparse_write = write_attributes_reparse_conversion_open(&nested_for_hook2)
            .map(|_| ())
            .map_err(|error| error.raw_os_error());
        let mut probe = hook_probe.lock().unwrap();
        probe.hook_ran = true;
        probe.route_rename = Some(route_rename);
        probe.source_rename = Some(source_rename);
        probe.nested_rename = Some(nested_rename);
        probe.route_reparse_write = Some(route_reparse_write);
        probe.source_reparse_write = Some(source_reparse_write);
        probe.nested_reparse_write = Some(nested_reparse_write);
    });

    let copy_result = super::copy_entry_no_clobber(
        &source,
        &destination,
        AttemptToken::fixture(),
        ItemId(0),
        &AtomicBool::new(false),
        |_| {},
        || {},
        |_, _| {},
    );

    let (route_was_moved, source_was_moved, nested_was_moved) = {
        let recorded = probe_state.lock().unwrap();
        (
            recorded.route_rename.as_ref().is_some_and(Result::is_ok),
            recorded.source_rename.as_ref().is_some_and(Result::is_ok),
            recorded.nested_rename.as_ref().is_some_and(Result::is_ok),
        )
    };
    if route_was_moved {
        std::fs::rename(&route_held, &route).expect("restore source route after probe");
    }
    if source_was_moved {
        std::fs::rename(&source_held, &source).expect("restore source root after probe");
    }
    if nested_was_moved {
        std::fs::rename(&nested_held, &nested).expect("restore nested source after probe");
    }

    let recorded = probe_state.lock().unwrap();
    assert!(recorded.hook_ran, "nested source admission hook ran");
    assert_eq!(
        recorded.route_rename,
        Some(Err(Some(32))),
        "ancestor route rename must fail with ERROR_SHARING_VIOLATION"
    );
    assert_eq!(
        recorded.source_rename,
        Some(Err(Some(32))),
        "source-root rename must fail with ERROR_SHARING_VIOLATION"
    );
    assert_eq!(
        recorded.nested_rename,
        Some(Err(Some(32))),
        "nested-directory rename must fail with ERROR_SHARING_VIOLATION"
    );
    assert_eq!(
        recorded.route_reparse_write,
        Some(Err(Some(32))),
        "route reparse-write open must fail with ERROR_SHARING_VIOLATION"
    );
    assert_eq!(
        recorded.source_reparse_write,
        Some(Err(Some(32))),
        "source-root reparse-write open must fail with ERROR_SHARING_VIOLATION"
    );
    assert_eq!(
        recorded.nested_reparse_write,
        Some(Err(Some(32))),
        "nested reparse-write open must fail with ERROR_SHARING_VIOLATION"
    );
    drop(recorded);

    copy_result.expect("strict read-only directory leases must permit ordinary Copy");

    assert!(
        fired.load(Ordering::Acquire),
        "nested source admission hook ran"
    );
    assert!(route.exists() && source.exists() && nested.exists());
    assert!(!route_held.exists() && !source_held.exists() && !nested_held.exists());
    assert_eq!(
        std::fs::read(destination.join("root.bin")).unwrap(),
        b"root control bytes"
    );
    assert_eq!(
        std::fs::read(destination.join("nested/leaf.bin")).unwrap(),
        b"nested control bytes"
    );
    assert!(destination.join("nested-empty").is_dir());
    assert_eq!(std::fs::read(&outside_sentinel).unwrap(), outside_bytes);
    assert!(
        !tree_contains_bytes(&destination_parent, outside_bytes),
        "outside sentinel must not be staged or published"
    );
}

#[cfg(target_os = "windows")]
#[test]
fn ordinary_directory_copy_rejects_intermediate_ancestor_route_rebind() {
    let root = local_ntfs_fixture();
    assert_fixed_ntfs_fixture(root.path());
    let route = root.path().join("route-rebind");
    let source = route.join("source");
    let later = source.join("z-later.bin");
    let destination_parent = root.path().join("route-rebind-destination");
    let destination = destination_parent.join("published");
    let outside_tree = root.path().join("route-rebind-outside");
    let outside_later = outside_tree.join("source/z-later.bin");
    let outside_bytes = b"unique intermediate-route redirection sentinel";
    let source_bytes = b"original source leaf stays selected";
    std::fs::create_dir_all(&source).unwrap();
    std::fs::create_dir(&destination_parent).unwrap();
    std::fs::write(source.join("a-control.bin"), b"source route control").unwrap();
    std::fs::write(&later, source_bytes).unwrap();
    std::fs::create_dir_all(outside_later.parent().unwrap()).unwrap();
    std::fs::write(&outside_later, outside_bytes).unwrap();

    // Prove that the falsifier can rebind this exact intermediate route absent a Copy lease.
    let route_probe = route.with_file_name("route-rebind-probe");
    std::fs::rename(&route, &route_probe).expect("route rename probe succeeds before Copy");
    std::fs::rename(&route_probe, &route).expect("route rename probe can be reversed");
    assert_eq!(std::fs::read(&outside_later).unwrap(), outside_bytes);

    #[derive(Default)]
    struct RouteProbe {
        hook_ran: bool,
        route_rename: Option<Result<(), Option<i32>>>,
        junction_create: Option<Result<bool, Option<i32>>>,
    }
    let probe = std::sync::Arc::new(std::sync::Mutex::new(RouteProbe::default()));
    let hook_probe = probe.clone();
    let hook_route = route.clone();
    let hook_later = later.clone();
    let hook_outside_tree = outside_tree.clone();
    let held_route = route.with_file_name("route-rebind-held");
    let hook_held_route = held_route.clone();
    let fired = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let hook_fired = fired.clone();
    windows::set_copy_directory_source_open_hook_for_test(move |candidate| {
        if candidate != hook_later || hook_fired.swap(true, Ordering::AcqRel) {
            return;
        }
        let route_rename =
            std::fs::rename(&hook_route, &hook_held_route).map_err(|error| error.raw_os_error());
        let junction_create = if route_rename.is_ok() {
            Some(
                std::process::Command::new("cmd.exe")
                    .args(["/C", "mklink", "/J"])
                    .arg(&hook_route)
                    .arg(&hook_outside_tree)
                    .output()
                    .map(|output| output.status.success())
                    .map_err(|error| error.raw_os_error()),
            )
        } else {
            None
        };
        let mut probe = hook_probe.lock().unwrap();
        probe.hook_ran = true;
        probe.route_rename = Some(route_rename);
        probe.junction_create = junction_create;
    });

    let copy_result = super::copy_entry_no_clobber(
        &source,
        &destination,
        AttemptToken::fixture(),
        ItemId(0),
        &AtomicBool::new(false),
        |_| {},
        || {},
        |_, _| {},
    );

    let recorded = probe.lock().unwrap();
    let route_was_moved = recorded
        .route_rename
        .as_ref()
        .is_some_and(|result| result.is_ok());
    let junction_create = recorded.junction_create.clone();
    drop(recorded);
    if route_was_moved {
        if route.exists() {
            let metadata = std::fs::symlink_metadata(&route).unwrap();
            assert!(
                metadata.file_type().is_symlink(),
                "route path should hold only the test junction"
            );
            std::fs::remove_dir(&route).expect("remove junction without following it");
        }
        std::fs::rename(&held_route, &route).expect("restore original route before assertions");
    }
    if route_was_moved {
        assert_eq!(
            junction_create,
            Some(Ok(true)),
            "fixture must install a directory junction if route rename unexpectedly succeeds"
        );
    } else {
        assert_eq!(junction_create, None);
    }

    let recorded = probe.lock().unwrap();
    assert!(
        recorded.hook_ran,
        "later source leaf reached the deterministic admission hook"
    );
    assert_eq!(
        recorded.route_rename,
        Some(Err(Some(32))),
        "ancestor route rename must fail with ERROR_SHARING_VIOLATION"
    );
    assert_eq!(
        junction_create, None,
        "a junction is installed only if route rename unexpectedly succeeds"
    );
    drop(recorded);

    copy_result.expect("an unchanged ordinary source route must copy successfully");
    assert!(route.join("source").exists());
    assert_eq!(
        std::fs::read(destination.join("a-control.bin")).unwrap(),
        b"source route control"
    );
    assert_eq!(std::fs::read(&later).unwrap(), source_bytes);
    assert_eq!(
        std::fs::read(destination.join("z-later.bin")).unwrap(),
        source_bytes
    );
    assert_eq!(std::fs::read(&outside_later).unwrap(), outside_bytes);
    assert!(
        !tree_contains_bytes(&destination_parent, outside_bytes),
        "outside leaf bytes must not appear in staging or the published tree"
    );
}

#[cfg(windows)]
fn assert_fixed_ntfs_fixture(path: &Path) {
    use ::windows::{
        Win32::Storage::FileSystem::{GetDriveTypeW, GetVolumeInformationW},
        core::PCWSTR,
    };
    use std::os::windows::ffi::OsStrExt;

    let root = path.ancestors().last().expect("absolute fixture path");
    let wide = root
        .as_os_str()
        .encode_wide()
        .chain(std::iter::once(0))
        .collect::<Vec<_>>();
    let mut filesystem = [0u16; 32];
    assert_eq!(
        unsafe { GetDriveTypeW(PCWSTR(wide.as_ptr())) },
        3,
        "fixture must be on a fixed drive"
    );
    unsafe {
        GetVolumeInformationW(
            PCWSTR(wide.as_ptr()),
            None,
            None,
            None,
            None,
            Some(&mut filesystem),
        )
    }
    .expect("read fixed-drive filesystem type");
    assert_eq!(
        String::from_utf16_lossy(&filesystem)
            .trim_end_matches('\0')
            .to_ascii_uppercase(),
        "NTFS",
        "fixture must use local NTFS"
    );
}

#[cfg(windows)]
fn tree_contains_bytes(directory: &Path, wanted: &[u8]) -> bool {
    for entry in std::fs::read_dir(directory).unwrap() {
        let path = entry.unwrap().path();
        let metadata = std::fs::symlink_metadata(&path).unwrap();
        if metadata.file_type().is_symlink() {
            continue;
        }
        if metadata.is_dir() {
            if tree_contains_bytes(&path, wanted) {
                return true;
            }
        } else if metadata.is_file() && std::fs::read(path).unwrap() == wanted {
            return true;
        }
    }
    false
}

#[cfg(target_os = "windows")]
#[test]
fn ordinary_directory_copy_denies_nested_stage_replacement_before_later_child_write() {
    let root = local_ntfs_fixture();
    let source = root.path().join("nested-junction-source");
    let destination_parent = root.path().join("nested-junction-destination");
    let destination = destination_parent.join("published");
    let external = root.path().join("junction-target");
    std::fs::create_dir_all(source.join("nested")).unwrap();
    std::fs::create_dir(&destination_parent).unwrap();
    std::fs::create_dir(&external).unwrap();
    std::fs::write(source.join("nested/first.bin"), b"first nested bytes").unwrap();
    std::fs::write(source.join("nested/second.bin"), b"second nested bytes").unwrap();
    let external_sentinel = external.join("sentinel.bin");
    std::fs::write(&external_sentinel, b"external data must remain unchanged").unwrap();
    let external_id = filesystem_identity(&external, crate::directory::EntryKind::Folder);
    let sentinel_id = filesystem_identity(&external_sentinel, crate::directory::EntryKind::File);
    let token = AttemptToken::fixture();
    let mut attempted = false;
    let mut replacement_denied = false;
    let mut junction_denied = false;

    let result = super::copy_entry_no_clobber(
        &source,
        &destination,
        token,
        ItemId(0),
        &AtomicBool::new(false),
        |_| {},
        || {
            if attempted {
                return;
            }
            attempted = true;
            let stage = std::fs::read_dir(&destination_parent)
                .unwrap()
                .map(Result::unwrap)
                .map(|entry| entry.path())
                .find(|path| {
                    path.file_name()
                        .unwrap()
                        .to_string_lossy()
                        .starts_with(".gpui-filer-copy-")
                })
                .expect("staging root exists before publication");
            let nested = stage.join("nested");
            replacement_denied = std::fs::rename(&nested, stage.join("detached-nested")).is_err();
            if replacement_denied {
                junction_denied = !std::process::Command::new("cmd.exe")
                    .args(["/C", "mklink", "/J"])
                    .arg(&nested)
                    .arg(&external)
                    .stdout(std::process::Stdio::null())
                    .stderr(std::process::Stdio::null())
                    .status()
                    .unwrap()
                    .success();
            }
        },
        |_, _| {},
    );

    assert!(attempted, "the nested file callback must run");
    assert!(
        replacement_denied,
        "the exact held nested directory must deny path replacement"
    );
    assert!(
        junction_denied,
        "the occupied nested name must deny junction insertion"
    );
    result.unwrap();
    assert!(destination.join("nested").is_dir());
    assert_eq!(
        filesystem_identity(&external, crate::directory::EntryKind::Folder),
        external_id
    );
    assert_eq!(
        filesystem_identity(&external_sentinel, crate::directory::EntryKind::File),
        sentinel_id
    );
    assert_eq!(
        std::fs::read(&external_sentinel).unwrap(),
        b"external data must remain unchanged"
    );
    assert_eq!(
        std::fs::read(destination.join("nested/first.bin")).unwrap(),
        b"first nested bytes"
    );
    assert_eq!(
        std::fs::read(destination.join("nested/second.bin")).unwrap(),
        b"second nested bytes"
    );
}

#[cfg(target_os = "windows")]
#[test]
fn ordinary_directory_copy_rejects_child_substitution_in_final_prepublication_window() {
    let root = local_ntfs_fixture();
    let source = root.path().join("prepublish-substitution-source");
    let destination_parent = root.path().join("prepublish-substitution-destination");
    let destination = destination_parent.join("published");
    let external = root.path().join("prepublish-substitution-target");
    std::fs::create_dir_all(source.join("nested")).unwrap();
    std::fs::create_dir(&destination_parent).unwrap();
    std::fs::create_dir(&external).unwrap();
    std::fs::write(source.join("nested/first.bin"), b"first child").unwrap();
    std::fs::write(source.join("nested/second.bin"), b"second child").unwrap();
    let sentinel = external.join("sentinel.bin");
    std::fs::write(&sentinel, b"external target is foreign").unwrap();
    let external_id = filesystem_identity(&external, crate::directory::EntryKind::Folder);
    let sentinel_id = filesystem_identity(&sentinel, crate::directory::EntryKind::File);
    let hook_ran = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let hook_ran_clone = hook_ran.clone();
    let external_for_hook = external.clone();
    windows::set_copy_directory_preverify_hook_for_test(move |stage| {
        use std::os::windows::fs::MetadataExt;

        // The descendant creation handle is gone, but the exact stage-root handle remains held.
        let root_before = filesystem_identity(stage, crate::directory::EntryKind::Folder);
        let nested = stage.join("nested");
        let original_child = crate::directory::EntrySourceIdentity::from_path_no_follow(
            &nested,
            crate::directory::EntryKind::Folder,
        )
        .unwrap();
        let detached = stage.join("detached-nested");
        std::fs::rename(&nested, &detached).unwrap();
        let status = std::process::Command::new("cmd.exe")
            .args(["/C", "mklink", "/J"])
            .arg(&nested)
            .arg(&external_for_hook)
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .status()
            .unwrap();
        assert!(status.success(), "could not create final-window junction");
        assert_eq!(
            filesystem_identity(stage, crate::directory::EntryKind::Folder),
            root_before,
            "stage root handle identity remains stable across child substitution"
        );
        assert_eq!(
            crate::directory::EntrySourceIdentity::from_path_no_follow(
                &detached,
                crate::directory::EntryKind::Folder,
            )
            .unwrap(),
            original_child,
            "the moved object retains the captured child identity"
        );
        let link = std::fs::symlink_metadata(&nested).unwrap();
        assert_ne!(link.file_attributes() & 0x0000_0400, 0);
        let junction_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
            &nested,
            crate::directory::EntryKind::Folder,
        )
        .unwrap();
        assert_ne!(junction_identity, original_child);
        hook_ran_clone.store(true, Ordering::Release);
    });
    let result = super::copy_entry_no_clobber(
        &source,
        &destination,
        AttemptToken::fixture(),
        ItemId(0),
        &AtomicBool::new(false),
        |_| {},
        || {},
        |_, _| {},
    );

    assert!(hook_ran.load(Ordering::Acquire));
    assert!(
        result.is_err(),
        "a substituted stage namespace cannot publish"
    );
    assert!(!destination.exists());
    assert_eq!(
        filesystem_identity(&external, crate::directory::EntryKind::Folder),
        external_id
    );
    assert_eq!(
        filesystem_identity(&sentinel, crate::directory::EntryKind::File),
        sentinel_id
    );
    assert_eq!(
        std::fs::read(&sentinel).unwrap(),
        b"external target is foreign"
    );
    let stage = std::fs::read_dir(&destination_parent)
        .unwrap()
        .map(Result::unwrap)
        .map(|entry| entry.path())
        .find(|path| {
            path.file_name()
                .unwrap()
                .to_string_lossy()
                .starts_with(".gpui-filer-copy-")
        })
        .expect("uncertain prepublication stage remains fixture-owned");
    let mut root_names = std::fs::read_dir(&stage)
        .unwrap()
        .map(Result::unwrap)
        .map(|entry| entry.file_name().to_string_lossy().into_owned())
        .collect::<Vec<_>>();
    root_names.sort();
    assert_eq!(root_names, ["detached-nested", "nested"]);
    assert_eq!(
        std::fs::read(stage.join("detached-nested/first.bin")).unwrap(),
        b"first child"
    );
    assert_eq!(
        std::fs::read(stage.join("detached-nested/second.bin")).unwrap(),
        b"second child"
    );
}

#[cfg(target_os = "windows")]
#[test]
fn ordinary_directory_copy_rejects_foreign_child_directory_replacement_before_publication() {
    let root = local_ntfs_fixture();
    let source = root.path().join("foreign-child-replacement-source");
    let destination_parent = root.path().join("foreign-child-replacement-destination");
    let destination = destination_parent.join("published");
    std::fs::create_dir_all(source.join("nested")).unwrap();
    std::fs::create_dir(&destination_parent).unwrap();
    std::fs::write(source.join("nested/first.bin"), b"first child").unwrap();
    std::fs::write(source.join("nested/second.bin"), b"second child").unwrap();
    let source_identity = filesystem_identity(&source, crate::directory::EntryKind::Folder);
    let nested_identity = filesystem_identity(
        &source.join("nested"),
        crate::directory::EntryKind::Folder,
    );
    let first_identity = filesystem_identity(
        &source.join("nested/first.bin"),
        crate::directory::EntryKind::File,
    );
    let second_identity = filesystem_identity(
        &source.join("nested/second.bin"),
        crate::directory::EntryKind::File,
    );
    let hook_ran = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let hook_ran_clone = hook_ran.clone();
    let observed = std::sync::Arc::new(std::sync::Mutex::new(None));
    let observed_clone = observed.clone();
    windows::set_copy_directory_preverify_hook_for_test(move |stage| {
        // final file callback後、child handle解放直後のpreverify窓を再現する。
        let original_nested = stage.join("nested");
        let original_identity = filesystem_identity(
            &original_nested,
            crate::directory::EntryKind::Folder,
        );
        let detached = stage.join("detached-nested");
        std::fs::rename(&original_nested, &detached).unwrap();
        std::fs::create_dir(&original_nested).unwrap();
        let sentinel = original_nested.join("foreign-sentinel.bin");
        std::fs::write(&sentinel, b"foreign replacement child").unwrap();
        *observed_clone.lock().unwrap() = Some((
            original_identity,
            filesystem_identity(&detached, crate::directory::EntryKind::Folder),
            filesystem_identity(&original_nested, crate::directory::EntryKind::Folder),
            filesystem_identity(&sentinel, crate::directory::EntryKind::File),
        ));
        hook_ran_clone.store(true, Ordering::Release);
    });

    let result = super::copy_entry_no_clobber(
        &source,
        &destination,
        AttemptToken::fixture(),
        ItemId(0),
        &AtomicBool::new(false),
        |_| {},
        || {},
        |_, _| {},
    );

    assert!(hook_ran.load(Ordering::Acquire));
    assert!(result.is_err(), "a replaced child namespace cannot publish");
    assert!(!destination.exists());
    assert_eq!(
        filesystem_identity(&source, crate::directory::EntryKind::Folder),
        source_identity
    );
    assert_eq!(
        filesystem_identity(&source.join("nested"), crate::directory::EntryKind::Folder),
        nested_identity
    );
    assert_eq!(
        filesystem_identity(
            &source.join("nested/first.bin"),
            crate::directory::EntryKind::File,
        ),
        first_identity
    );
    assert_eq!(
        filesystem_identity(
            &source.join("nested/second.bin"),
            crate::directory::EntryKind::File,
        ),
        second_identity
    );
    assert_eq!(
        std::fs::read(source.join("nested/first.bin")).unwrap(),
        b"first child"
    );
    assert_eq!(
        std::fs::read(source.join("nested/second.bin")).unwrap(),
        b"second child"
    );

    let stage = std::fs::read_dir(&destination_parent)
        .unwrap()
        .map(Result::unwrap)
        .map(|entry| entry.path())
        .find(|path| {
            path.file_name()
                .unwrap()
                .to_string_lossy()
                .starts_with(".gpui-filer-copy-")
        })
        .expect("the uncertain prepublication stage remains available for inspection");
    let (original_identity, detached_identity, replacement_identity, sentinel_identity) =
        observed.lock().unwrap().take().expect("preverify mutation ran");
    assert_eq!(detached_identity, original_identity);
    assert_ne!(replacement_identity, original_identity);
    assert_eq!(
        filesystem_identity(
            &stage.join("detached-nested"),
            crate::directory::EntryKind::Folder,
        ),
        original_identity
    );
    assert_eq!(
        filesystem_identity(
            &stage.join("nested"),
            crate::directory::EntryKind::Folder,
        ),
        replacement_identity
    );
    let sentinel = stage.join("nested/foreign-sentinel.bin");
    assert_eq!(
        filesystem_identity(&sentinel, crate::directory::EntryKind::File),
        sentinel_identity
    );
    assert_eq!(
        std::fs::read(&sentinel).unwrap(),
        b"foreign replacement child"
    );
    assert_eq!(
        std::fs::read(stage.join("detached-nested/first.bin")).unwrap(),
        b"first child"
    );
    assert_eq!(
        std::fs::read(stage.join("detached-nested/second.bin")).unwrap(),
        b"second child"
    );
}

#[cfg(target_os = "windows")]
#[test]
fn ordinary_directory_copy_rejects_missing_extra_and_same_length_stage_mutations() {
    let root = local_ntfs_fixture();
    for mutation in ["missing", "extra", "same-length"] {
        let source = root.path().join(format!("mutation-source-{mutation}"));
        let destination_parent = root.path().join(format!("mutation-destination-{mutation}"));
        let destination = destination_parent.join("published");
        std::fs::create_dir(&source).unwrap();
        std::fs::create_dir(&destination_parent).unwrap();
        std::fs::write(source.join("a.bin"), b"alpha bytes").unwrap();
        std::fs::write(source.join("b.bin"), b"bravo bytes").unwrap();
        let token = AttemptToken::fixture();
        let mut completed = 0;
        let mut mutated = false;
        let mut stage_identity = None;
        let mut file_identities = None;
        let result = super::copy_entry_no_clobber(
            &source,
            &destination,
            token,
            ItemId(0),
            &AtomicBool::new(false),
            |_| {},
            || {
                completed += 1;
                if completed != 2 {
                    return;
                }
                let stage = std::fs::read_dir(&destination_parent)
                    .unwrap()
                    .map(Result::unwrap)
                    .map(|entry| entry.path())
                    .find(|path| {
                        path.file_name()
                            .unwrap()
                            .to_string_lossy()
                            .starts_with(".gpui-filer-copy-")
                    })
                    .expect("stage exists before publication");
                stage_identity = Some(filesystem_identity(
                    &stage,
                    crate::directory::EntryKind::Folder,
                ));
                file_identities = Some((
                    filesystem_identity(&stage.join("a.bin"), crate::directory::EntryKind::File),
                    filesystem_identity(&stage.join("b.bin"), crate::directory::EntryKind::File),
                ));
                match mutation {
                    "missing" => std::fs::remove_file(stage.join("a.bin")).unwrap(),
                    "extra" => std::fs::write(stage.join("extra.bin"), b"foreign extra").unwrap(),
                    "same-length" => std::fs::write(stage.join("a.bin"), b"omega bytes").unwrap(),
                    _ => unreachable!(),
                }
                mutated = true;
            },
            |_, _| {},
        );
        assert!(mutated, "the deterministic {mutation} mutation must run");
        assert!(
            result.is_err(),
            "the {mutation} stage must fail verification"
        );
        assert!(
            !destination.exists(),
            "the {mutation} stage must not publish"
        );
        let stage = std::fs::read_dir(&destination_parent)
            .unwrap()
            .map(Result::unwrap)
            .map(|entry| entry.path())
            .find(|path| {
                path.file_name()
                    .unwrap()
                    .to_string_lossy()
                    .starts_with(".gpui-filer-copy-")
            })
            .expect("prepublication mismatch retains its stage");
        assert_eq!(
            filesystem_identity(&stage, crate::directory::EntryKind::Folder),
            stage_identity.unwrap()
        );
        let mut names = std::fs::read_dir(&stage)
            .unwrap()
            .map(Result::unwrap)
            .map(|entry| entry.file_name().to_string_lossy().into_owned())
            .collect::<Vec<_>>();
        names.sort();
        assert_eq!(
            names,
            match mutation {
                "missing" => vec!["b.bin"],
                "extra" => vec!["a.bin", "b.bin", "extra.bin"],
                "same-length" => vec!["a.bin", "b.bin"],
                _ => unreachable!(),
            }
        );
        let (a_id, b_id) = file_identities.unwrap();
        if mutation != "missing" {
            assert_eq!(
                filesystem_identity(&stage.join("a.bin"), crate::directory::EntryKind::File),
                a_id
            );
        }
        assert_eq!(
            filesystem_identity(&stage.join("b.bin"), crate::directory::EntryKind::File),
            b_id
        );
        if mutation == "same-length" {
            assert_eq!(std::fs::read(stage.join("a.bin")).unwrap(), b"omega bytes");
            assert_eq!(
                std::fs::metadata(stage.join("a.bin")).unwrap().len(),
                b"alpha bytes".len() as u64
            );
        }
    }
}

#[cfg(target_os = "windows")]
#[test]
fn ordinary_directory_copy_stage_root_identity_failure_is_unknown_but_create_collision_is_not_evidence()
 {
    use std::os::windows::ffi::OsStrExt;
    let root = local_ntfs_fixture();
    let source = root.path().join("source");
    let destination_parent = root.path().join("destination-parent");
    let destination = destination_parent.join("source");
    std::fs::create_dir(&source).unwrap();
    std::fs::create_dir(&destination_parent).unwrap();
    std::fs::write(source.join("payload.bin"), b"source bytes").unwrap();

    super::windows::fail_next_copy_directory_stage_root_identity_for_test();
    let result = super::copy_entry_no_clobber(
        &source,
        &destination,
        AttemptToken::fixture(),
        ItemId(0),
        &AtomicBool::new(false),
        |_| {},
        || {},
        |_, _| {},
    );
    let Err(CopyError::DirectoryCopyStageRetained { evidence, cause }) = result else {
        panic!(
            "successful CREATE_NEW followed by failed root identity must retain typed evidence: {result:?}"
        );
    };
    assert!(matches!(*cause, CopyError::Unknown(_)));
    assert_eq!(
        evidence.phase,
        super::super::model::CopyDirectoryStagePhase::CreatedRootIdentityUnverified
    );
    assert!(evidence.expected_root_identity.is_empty());
    assert_eq!(
        evidence.destination_path_units,
        destination.as_os_str().encode_wide().collect::<Vec<_>>()
    );
    let stage = PathBuf::from(String::from_utf16(&evidence.stage_path_units).unwrap());
    assert!(
        stage.is_dir(),
        "the exact path came from a successful CREATE_NEW"
    );
    assert_eq!(stage.parent(), Some(destination_parent.as_path()));
    assert!(!destination.exists());
    for expected_root_identity in [String::new(), "forged-but-nonempty".to_owned()] {
        let inspected = super::inspect_copy_failure_candidates(
            crate::operations::model::CopyFailureInspectionResult {
                ticket: crate::operations::model::InspectionTicket::new(1),
                attempt: AttemptToken::fixture(),
                candidates: vec![],
                directory_candidates: vec![crate::operations::model::CopyDirectoryInspectionCandidate {
                    evidence: crate::operations::model::CopyDirectoryInspectionEvidence::RetainedStage(
                        super::super::model::CopyDirectoryStageEvidence {
                            stage_path_units: evidence.stage_path_units.clone(),
                            destination_path_units: evidence.destination_path_units.clone(),
                            expected_root_identity,
                            phase: super::super::model::CopyDirectoryStagePhase::CreatedRootIdentityUnverified,
                            detail: evidence.detail.clone(),
                        },
                    ),
                    stage_root: crate::operations::model::CopyInspectionState::Matches,
                    destination_root: crate::operations::model::CopyInspectionState::Indeterminate,
                }],
            },
        );
        assert_eq!(
            inspected.directory_candidates[0].stage_root,
            crate::operations::model::CopyInspectionState::Indeterminate,
            "an unverified stage root stays indeterminate even when the path currently resolves"
        );
    }
    let (outcome, detail) = super::copy_outcome(Err(CopyError::DirectoryCopyStageRetained {
        evidence: evidence.clone(),
        cause: Box::new(CopyError::Unknown("injected".into())),
    }));
    assert_eq!(outcome, ItemOutcome::Unknown);
    let detail = detail.unwrap();
    assert!(detail.contains(super::super::model::DIRECTORY_COPY_STAGE_EVIDENCE_PREFIX));
    assert!(detail.contains("created-root-identity-unverified"));

    let collision_source = root.path().join("collision-source");
    let collision_parent = root.path().join("collision-parent");
    let collision_destination = collision_parent.join("collision-source");
    std::fs::create_dir(&collision_source).unwrap();
    std::fs::create_dir(&collision_parent).unwrap();
    std::fs::write(collision_source.join("payload.bin"), b"safe").unwrap();
    let token = AttemptToken::fixture();
    let collision = collision_parent.join(format!(
        ".gpui-filer-copy-{}-{}-{}-{}-0",
        std::process::id(),
        token.job_id().value(),
        token.attempt_id().value(),
        ItemId(0).0
    ));
    std::fs::create_dir(&collision).unwrap();
    std::fs::write(collision.join("foreign.txt"), b"preserve").unwrap();
    let result = super::copy_entry_no_clobber(
        &collision_source,
        &collision_destination,
        token,
        ItemId(0),
        &AtomicBool::new(false),
        |_| {},
        || {},
        |_, _| {},
    );
    assert!(
        result.is_ok(),
        "CREATE_NEW collision must advance to another name without evidence: {result:?}"
    );
    assert_eq!(
        std::fs::read(collision.join("foreign.txt")).unwrap(),
        b"preserve"
    );
    assert_eq!(
        std::fs::read(collision_destination.join("payload.bin")).unwrap(),
        b"safe"
    );
}

#[cfg(target_os = "windows")]
#[test]
fn ordinary_directory_copy_returns_unknown_for_postpublish_cancellation_or_foreign_addition() {
    use std::os::windows::ffi::OsStrExt;
    for (case, fault) in [
        (
            "cancel-after-publish",
            windows::CopyDirectoryPostPublishTestFault::Cancel,
        ),
        (
            "foreign-addition-after-publish",
            windows::CopyDirectoryPostPublishTestFault::AddForeignChild,
        ),
    ] {
        let root = local_ntfs_fixture();
        let source = root.path().join(format!("source-{case}"));
        let destination_parent = root.path().join(format!("destination-parent-{case}"));
        let destination = destination_parent.join("published");
        std::fs::create_dir(&source).unwrap();
        std::fs::create_dir(&destination_parent).unwrap();
        std::fs::write(source.join("payload.bin"), b"published payload").unwrap();
        let cancelled = AtomicBool::new(false);
        let published_facts = std::sync::Arc::new(std::sync::Mutex::new(None));
        if case == "foreign-addition-after-publish" {
            let captured = published_facts.clone();
            windows::set_copy_directory_postpublish_hook_for_test(move |published| {
                let mut names = std::fs::read_dir(published)
                    .unwrap()
                    .map(Result::unwrap)
                    .map(|entry| entry.file_name().to_string_lossy().into_owned())
                    .collect::<Vec<_>>();
                names.sort();
                assert_eq!(names, ["payload.bin"]);
                *captured.lock().unwrap() = Some((
                    filesystem_identity(published, crate::directory::EntryKind::Folder),
                    filesystem_identity(
                        &published.join("payload.bin"),
                        crate::directory::EntryKind::File,
                    ),
                    names,
                ));
            });
        }
        windows::set_copy_directory_postpublish_fault_for_test(fault);
        let result = super::copy_entry_no_clobber(
            &source,
            &destination,
            AttemptToken::fixture(),
            ItemId(0),
            &cancelled,
            |_| {},
            || {},
            |_, _| {},
        );
        let Err(CopyError::UnknownDirectoryPublication(evidence)) = result else {
            panic!("published uncertainty must be Unknown, got {result:?}");
        };
        assert_eq!(
            evidence.destination_path_units,
            destination.as_os_str().encode_wide().collect::<Vec<_>>()
        );
        assert_eq!(
            std::fs::read(destination.join("payload.bin")).unwrap(),
            b"published payload"
        );
        if case == "cancel-after-publish" {
            assert!(cancelled.load(Ordering::Acquire));
            assert!(!destination.join("foreign-after-publish.bin").exists());
        } else {
            let (root_id, payload_id, before_names) = published_facts
                .lock()
                .unwrap()
                .take()
                .expect("post-rename hook captured exact baseline identities");
            assert_eq!(before_names, ["payload.bin"]);
            assert_eq!(
                filesystem_identity(&destination, crate::directory::EntryKind::Folder),
                root_id
            );
            assert_eq!(
                filesystem_identity(
                    &destination.join("payload.bin"),
                    crate::directory::EntryKind::File,
                ),
                payload_id
            );
            assert_eq!(
                std::fs::read(destination.join("foreign-after-publish.bin")).unwrap(),
                b"foreign"
            );
            let mut names = std::fs::read_dir(&destination)
                .unwrap()
                .map(Result::unwrap)
                .map(|entry| entry.file_name().to_string_lossy().into_owned())
                .collect::<Vec<_>>();
            names.sort();
            assert_eq!(names, ["foreign-after-publish.bin", "payload.bin"]);
        }
    }
}

#[cfg(target_os = "windows")]
#[test]
fn ordinary_directory_copy_retains_verified_sibling_handles_during_later_hash_and_cancels_unknown()
{
    use std::os::windows::ffi::OsStrExt;
    let root = local_ntfs_fixture();
    let source = root.path().join("scan-retention-source");
    let destination_parent = root.path().join("scan-retention-destination");
    let destination = destination_parent.join("published");
    std::fs::create_dir(&source).unwrap();
    std::fs::create_dir(&destination_parent).unwrap();
    let first = source.join("a-first.bin");
    let later = source.join("z-later-large.bin");
    let detached = root.path().join("detached-first.bin");
    std::fs::write(&first, b"first identity stays pinned").unwrap();
    let large_bytes = vec![0x5a; 8 * 1024 * 1024];
    std::fs::write(&later, &large_bytes).unwrap();
    let cancelled = std::sync::Arc::new(AtomicBool::new(false));
    let hook_cancelled = cancelled.clone();
    let fired = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let hook_fired = fired.clone();
    let hook_detached = detached.clone();
    windows::set_copy_directory_postpublish_hook_for_test(move |published| {
        let published_first = published.join("a-first.bin");
        let held_identity =
            filesystem_identity(&published_first, crate::directory::EntryKind::File);
        let name = std::ffi::OsStr::new("z-later-large.bin")
            .encode_wide()
            .collect::<Vec<_>>();
        let hook_fired = hook_fired.clone();
        let hook_detached = hook_detached.clone();
        windows::set_copy_directory_scan_hook_for_test(move |relative| {
            if relative.last().is_some_and(|component| component == &name)
                && !hook_fired.swap(true, Ordering::AcqRel)
            {
                let rename = std::fs::rename(&published_first, &hook_detached);
                assert!(
                    rename.is_err(),
                    "the earlier verified file handle must deny relocation while the later file is hashed"
                );
                assert_eq!(
                    filesystem_identity(&published_first, crate::directory::EntryKind::File),
                    held_identity
                );
                assert_eq!(
                    std::fs::read(&published_first).unwrap(),
                    b"first identity stays pinned"
                );
                hook_cancelled.store(true, Ordering::Release);
                true
            } else {
                false
            }
        });
    });
    let result = super::copy_entry_no_clobber(
        &source,
        &destination,
        AttemptToken::fixture(),
        ItemId(0),
        &cancelled,
        |_| {},
        || {},
        |_, _| {},
    );
    assert!(
        fired.load(Ordering::Acquire),
        "the later large file must be hashed after the first file is retained"
    );
    assert!(
        matches!(result, Err(CopyError::UnknownDirectoryPublication(_))),
        "scan-time cancellation after publication must remain Unknown: {result:?}"
    );
    assert!(!detached.exists());
    assert_eq!(
        std::fs::read(destination.join("a-first.bin")).unwrap(),
        b"first identity stays pinned"
    );
    assert_eq!(
        std::fs::read(destination.join("z-later-large.bin")).unwrap(),
        large_bytes
    );
}

#[cfg(target_os = "windows")]
#[test]
fn ordinary_directory_copy_detects_root_child_added_during_postpublish_hash() {
    use std::os::windows::ffi::OsStrExt;
    let root = local_ntfs_fixture();
    let source = root.path().join("scan-addition-source");
    let destination_parent = root.path().join("scan-addition-destination");
    let destination = destination_parent.join("published");
    std::fs::create_dir(&source).unwrap();
    std::fs::create_dir(&destination_parent).unwrap();
    std::fs::write(source.join("a-first.bin"), b"first stays exact").unwrap();
    let large_bytes = vec![0x39; 8 * 1024 * 1024];
    std::fs::write(source.join("z-later-large.bin"), &large_bytes).unwrap();
    let first_identity = std::sync::Arc::new(std::sync::Mutex::new(None));
    let root_identity = std::sync::Arc::new(std::sync::Mutex::new(None));
    let saw_later = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let hook_first_identity = first_identity.clone();
    let hook_root_identity = root_identity.clone();
    let hook_saw_later = saw_later.clone();
    windows::set_copy_directory_postpublish_hook_for_test(move |published| {
        *hook_first_identity.lock().unwrap() = Some(filesystem_identity(
            &published.join("a-first.bin"),
            crate::directory::EntryKind::File,
        ));
        *hook_root_identity.lock().unwrap() = Some(filesystem_identity(
            published,
            crate::directory::EntryKind::Folder,
        ));
        let published = published.to_path_buf();
        let later = std::ffi::OsStr::new("z-later-large.bin")
            .encode_wide()
            .collect::<Vec<_>>();
        windows::set_copy_directory_scan_hook_for_test(move |relative| {
            if relative.last().is_some_and(|component| component == &later)
                && !hook_saw_later.swap(true, Ordering::AcqRel)
            {
                std::fs::write(
                    published.join("foreign-root.bin"),
                    b"foreign child survives",
                )
                .expect("the test mutation adds a fixture-owned child");
                true
            } else {
                false
            }
        });
    });
    let result = super::copy_entry_no_clobber(
        &source,
        &destination,
        AttemptToken::fixture(),
        ItemId(0),
        &AtomicBool::new(false),
        |_| {},
        || {},
        |_, _| {},
    );
    assert!(saw_later.load(Ordering::Acquire));
    let Err(CopyError::UnknownDirectoryPublication(evidence)) = result else {
        panic!("postpublish foreign child must yield Unknown, got {result:?}");
    };
    assert_eq!(
        evidence.phase,
        crate::operations::model::CopyDirectoryPublicationPhase::PublishedInventoryMismatch
    );
    let expected_root_identity = root_identity.lock().unwrap().clone().unwrap();
    let expected_first_identity = first_identity.lock().unwrap().clone().unwrap();
    assert_eq!(
        filesystem_identity(&destination, crate::directory::EntryKind::Folder),
        expected_root_identity
    );
    assert_eq!(
        filesystem_identity(
            &destination.join("a-first.bin"),
            crate::directory::EntryKind::File
        ),
        expected_first_identity
    );
    assert_eq!(
        std::fs::read(destination.join("a-first.bin")).unwrap(),
        b"first stays exact"
    );
    assert_eq!(
        std::fs::read(destination.join("z-later-large.bin")).unwrap(),
        large_bytes
    );
    assert_eq!(
        std::fs::read(destination.join("foreign-root.bin")).unwrap(),
        b"foreign child survives"
    );
}

#[cfg(target_os = "windows")]
#[test]
fn ordinary_directory_copy_postpublish_external_child_is_not_a_namespace_lock() {
    use std::io::Write;
    use std::os::windows::ffi::OsStrExt;

    let root = local_ntfs_fixture();
    let source = root.path().join("checked-directory-mutation-source");
    let destination_parent = root.path().join("checked-directory-mutation-destination");
    let destination = destination_parent.join("published");
    std::fs::create_dir_all(source.join("a-checked")).unwrap();
    std::fs::create_dir_all(source.join("z-later")).unwrap();
    std::fs::create_dir(&destination_parent).unwrap();
    std::fs::write(source.join("a-checked/original.bin"), b"first exact bytes").unwrap();
    std::fs::write(source.join("z-later/original.bin"), b"later exact bytes").unwrap();

    let checked = std::ffi::OsStr::new("a-checked")
        .encode_wide()
        .collect::<Vec<_>>();
    let later = std::ffi::OsStr::new("z-later")
        .encode_wide()
        .collect::<Vec<_>>();
    let foreign_name = std::ffi::OsStr::new("foreign-after-check.bin")
        .encode_wide()
        .collect::<Vec<_>>();
    let mutation = std::sync::Arc::new(std::sync::Mutex::new(None));
    let hook_mutation = mutation.clone();
    windows::set_copy_directory_namespace_hook_for_test(
        move |checked_relative, later_relative, checked_handle| {
            assert_eq!(checked_relative, &[checked.clone()]);
            assert_eq!(later_relative, &[later.clone()]);
            let attempt = windows::create_staged_file(checked_handle, &foreign_name);
            let observation = match attempt {
                Ok(mut file) => {
                    file.write_all(b"foreign bytes from retained handle")
                        .unwrap();
                    file.flush().unwrap();
                    drop(file);
                    Ok(())
                }
                Err(error) => Err(format!("{error:?}")),
            };
            *hook_mutation.lock().unwrap() = Some(observation);
        },
    );

    let result = super::copy_entry_no_clobber(
        &source,
        &destination,
        AttemptToken::fixture(),
        ItemId(0),
        &AtomicBool::new(false),
        |_| {},
        || {},
        |_, _| {},
    );
    let mutation = mutation
        .lock()
        .unwrap()
        .take()
        .expect("hook attempts mutation during second directory check");
    if mutation.is_ok() {
        match result {
            Ok(()) => {}
            Err(CopyError::UnknownDirectoryPublication(evidence)) => {
                assert_eq!(evidence.phase, crate::operations::model::CopyDirectoryPublicationPhase::PublishedInventoryMismatch);
            }
            Err(error) => panic!(
                "postpublication external mutation must not become a prepublication failure: {error:?}"
            ),
        }
        assert_eq!(
            std::fs::read(destination.join("a-checked/foreign-after-check.bin")).unwrap(),
            b"foreign bytes from retained handle"
        );
    } else {
        result.expect(
            "when the filesystem refuses the concurrent child creation, ordinary copy completes",
        );
        assert!(
            !destination
                .join("a-checked/foreign-after-check.bin")
                .exists()
        );
    }
    assert_eq!(
        std::fs::read(destination.join("a-checked/original.bin")).unwrap(),
        b"first exact bytes"
    );
    assert_eq!(
        std::fs::read(destination.join("z-later/original.bin")).unwrap(),
        b"later exact bytes"
    );
    assert!(!source.join("a-checked/foreign-after-check.bin").exists());
}

#[cfg(target_os = "windows")]
#[test]
fn ordinary_directory_copy_stage_root_substitution_at_final_file_callback_is_not_published() {
    let root = local_ntfs_fixture();
    let source = root.path().join("stage-root-substitution-source");
    let destination_parent = root.path().join("stage-root-substitution-destination");
    let destination = destination_parent.join("published");
    std::fs::create_dir(&source).unwrap();
    std::fs::create_dir(&destination_parent).unwrap();
    std::fs::write(source.join("payload.bin"), b"original staged bytes").unwrap();

    let cancelled = AtomicBool::new(false);
    let mut callback_observation = None;
    super::copy_entry_no_clobber(
        &source,
        &destination,
        AttemptToken::fixture(),
        ItemId(0),
        &cancelled,
        |_| {},
        || {
            let stage = std::fs::read_dir(&destination_parent)
                .unwrap()
                .map(|entry| entry.unwrap().path())
                .find(|path| {
                    path.file_name()
                        .is_some_and(|name| name.to_string_lossy().starts_with(".gpui-filer-copy-"))
                })
                .expect("attempt-owned stage exists during final file callback");
            let stage_id = filesystem_identity(&stage, crate::directory::EntryKind::Folder);
            let staged_file = stage.join("payload.bin");
            let staged_file_id =
                filesystem_identity(&staged_file, crate::directory::EntryKind::File);
            let displaced = destination_parent.join("displaced-original-stage");
            let (rename_error, sentinel_placed) = match std::fs::rename(&stage, &displaced) {
                Ok(()) => {
                    std::fs::create_dir(&stage).unwrap();
                    std::fs::write(stage.join("foreign-sentinel.bin"), b"foreign tree").unwrap();
                    (None, true)
                }
                Err(error) => (Some(error.raw_os_error()), false),
            };
            callback_observation = Some((
                stage,
                stage_id,
                staged_file_id,
                rename_error,
                sentinel_placed,
            ));
        },
        |_, _| {},
    )
    .unwrap();

    let (stage, stage_id, staged_file_id, rename_error, sentinel_placed) =
        callback_observation.expect("file callback ran");
    assert_eq!(rename_error, Some(Some(32)));
    assert!(
        !sentinel_placed,
        "the held stage pathname cannot be substituted"
    );
    assert!(
        !stage.exists(),
        "the original stage was published from its held handle"
    );
    assert_eq!(
        filesystem_identity(&destination, crate::directory::EntryKind::Folder),
        stage_id
    );
    assert_eq!(
        filesystem_identity(
            &destination.join("payload.bin"),
            crate::directory::EntryKind::File
        ),
        staged_file_id
    );
    assert_eq!(
        std::fs::read(destination.join("payload.bin")).unwrap(),
        b"original staged bytes"
    );
    let entries = std::fs::read_dir(&destination)
        .unwrap()
        .collect::<Result<Vec<_>, _>>()
        .unwrap();
    assert_eq!(entries.len(), 1);
    assert_eq!(entries[0].file_name(), "payload.bin");
}

#[cfg(target_os = "windows")]
#[test]
fn cancelled_directory_copy_retains_original_locked_stage_and_releases_it_on_return() {
    let root = local_ntfs_fixture();
    let source = root.path().join("cancelled-stage-source");
    let destination_parent = root.path().join("cancelled-stage-destination");
    let destination = destination_parent.join("published");
    std::fs::create_dir(&source).unwrap();
    std::fs::create_dir(&destination_parent).unwrap();
    std::fs::write(source.join("payload.bin"), b"retained stage bytes").unwrap();
    let cancelled = AtomicBool::new(false);
    let mut stage_facts = None;
    let result = super::copy_entry_no_clobber(
        &source,
        &destination,
        AttemptToken::fixture(),
        ItemId(0),
        &cancelled,
        |_| {},
        || {
            let stage = std::fs::read_dir(&destination_parent)
                .unwrap()
                .map(|entry| entry.unwrap().path())
                .find(|path| {
                    path.file_name()
                        .unwrap()
                        .to_string_lossy()
                        .starts_with(".gpui-filer-copy-")
                })
                .unwrap();
            stage_facts = Some((
                stage.clone(),
                filesystem_identity(&stage, crate::directory::EntryKind::Folder),
                filesystem_identity(
                    &stage.join("payload.bin"),
                    crate::directory::EntryKind::File,
                ),
            ));
            cancelled.store(true, Ordering::Release);
        },
        |_, _| {},
    );
    assert_eq!(result, Err(CopyError::Cancelled));
    assert!(!destination.exists());
    let (stage, root_id, file_id) = stage_facts.expect("final file callback ran");
    assert_eq!(
        filesystem_identity(&stage, crate::directory::EntryKind::Folder),
        root_id
    );
    assert_eq!(
        filesystem_identity(
            &stage.join("payload.bin"),
            crate::directory::EntryKind::File
        ),
        file_id
    );
    assert_eq!(
        std::fs::read(stage.join("payload.bin")).unwrap(),
        b"retained stage bytes"
    );
    let released = stage.with_file_name("cancelled-stage-released");
    std::fs::rename(&stage, &released).expect("stage lease is released after cancellation returns");
    assert_eq!(
        filesystem_identity(&released, crate::directory::EntryKind::Folder),
        root_id
    );
}

