#[cfg(target_os = "windows")]
#[test]
fn clipboard_move_same_volume_second_hardlink_rename_refusal_keeps_first_undo_only() {
    let root = tempfile::tempdir_in(env!("CARGO_MANIFEST_DIR")).unwrap();
    let source = root.path().join("source.bin");
    let alias = root.path().join("alias.bin");
    let destination = root.path().join("destination");
    let bytes = b"shared hardlink object";
    std::fs::write(&source, bytes).unwrap();
    std::fs::hard_link(&source, &alias).unwrap();
    std::fs::create_dir(&destination).unwrap();
    let source_identity = filesystem_identity(&source, crate::directory::EntryKind::File);
    assert_eq!(filesystem_identity(&alias, crate::directory::EntryKind::File), source_identity);

    let destination_identity = filesystem_identity(&destination, crate::directory::EntryKind::Folder);
    let (files, replace_evidence, move_evidence) =
        crate::shell::FilerShell::prepare_clipboard_file_request(
            crate::operations::file_clipboard::ClipboardFiles {
                paths: vec![source.clone(), alias.clone()],
                effect: crate::operations::file_clipboard::ClipboardEffect::Move,
            },
            &destination_identity,
        )
        .unwrap();
    assert_eq!(files.paths, vec![source.clone(), alias.clone()]);
    let move_evidence = move_evidence.unwrap();
    assert_eq!(move_evidence.len(), 2);
    assert_eq!(move_evidence[0].source_identity, source_identity);
    assert_eq!(move_evidence[1].source_identity, source_identity);

    crate::operations::rename::refuse_clipboard_move_rename_once_for_test(&alias);
    let mut runtime = super::super::runtime::OperationRuntime::default();
    let token = runtime
        .submit(OperationRequest {
            kind: OperationKind::Move,
            virtual_source: None,
            sources: files.paths,
            destination: Some(destination.clone()),
            move_identity_guard: None,
            clipboard_move_source_evidence: Some(move_evidence),
            rename_reparse_guard: None,
            move_destination_identity_guard: Some(destination_identity),
            move_replace_source_evidence: replace_evidence,
            trash_source_guards: None,
            source_cleanup_identity_guard: None,
            initial_conflict_policy: None,
            copy_destination_identity_guard: None,
            create_parent_directory_identity_guard: None,
            zip_create_guard: None,
            shortcut_create_guard: None,
            seven_zip_create_guard: None,
            seven_zip_extract_guard: None,
            origin: None,
            batch_rename_plan: None,
        })
        .unwrap();
    let start = runtime.start_next().unwrap();
    let (fact_sender, facts) = std::sync::mpsc::channel();
    let worker = std::thread::spawn(move || {
        execute_prepare(start.command, &start.cancellation, &start.controls, |fact| {
            fact_sender.send(fact).unwrap()
        })
    });
    let report = loop {
        let fact = facts.recv().unwrap();
        let report = match &fact {
            ExecutorFact::Terminal { token: actual, report } => {
                assert_eq!(*actual, token);
                Some(report.clone())
            }
            _ => None,
        };
        runtime.commit_fact(fact);
        if let Some(report) = report {
            break report;
        }
    };
    worker.join().unwrap();

    assert!(!crate::operations::rename::clipboard_move_rename_refusal_is_armed_for_test(&alias));
    assert_eq!(report.outcome, TerminalOutcome::Partial, "{report:#?}");
    assert_eq!(report.receipts.len(), 2);
    assert_eq!(report.receipts[0].item, ItemId(0));
    assert_eq!(report.receipts[1].item, ItemId(1));
    assert_eq!(report.receipts[0].outcome, ItemOutcome::Completed);
    assert_eq!(report.receipts[1].outcome, ItemOutcome::Failed);
    let moved = destination.join("source.bin");
    assert!(!source.exists());
    assert_eq!(std::fs::read(&moved).unwrap(), bytes);
    assert_eq!(filesystem_identity(&moved, crate::directory::EntryKind::File), source_identity);
    assert_eq!(std::fs::read(&alias).unwrap(), bytes);
    assert_eq!(filesystem_identity(&alias, crate::directory::EntryKind::File), source_identity);
    assert!(!destination.join("alias.bin").exists());

    let (_, undo_entries) = runtime.undo_snapshot_for_test();
    assert_eq!(undo_entries.len(), 1, "only the completed item grants Undo");
    let super::super::runtime::UndoEntry::Move(group) = &undo_entries[0] else {
        panic!("expected Move Undo group")
    };
    assert_eq!(group.len(), 1);
    assert_eq!(group[0].source, source);
    assert_eq!(group[0].destination, moved);
    assert_eq!(group[0].cross_volume_file, None);
}

