#[cfg(target_os = "windows")]
#[test]
fn move_worker_moves_same_volume_and_refreshes_both_parents() {
    let root = tempfile::tempdir().unwrap();
    let source_parent = root.path().join("source");
    let destination = root.path().join("destination");
    std::fs::create_dir(&source_parent).unwrap();
    std::fs::create_dir(&destination).unwrap();
    let source = source_parent.join("item.txt");
    std::fs::write(&source, b"contents").unwrap();
    let request = OperationRequest {
        kind: OperationKind::Move,
        virtual_source: None,
        sources: vec![source.clone()],
        destination: Some(destination.clone()),
        move_identity_guard: None,
        clipboard_move_source_evidence: None,
        rename_reparse_guard: None,
        move_destination_identity_guard: None,
        move_replace_source_evidence: None,
        trash_source_guards: None,
        source_cleanup_identity_guard: None,
        initial_conflict_policy: None,
        copy_destination_identity_guard: None,
        create_parent_directory_identity_guard: None,
        zip_create_guard: None,
        shortcut_create_guard: None,
        seven_zip_create_guard: None,
        seven_zip_extract_guard: None,
        origin: None,
        batch_rename_plan: None,
    };
    let mut service = OperationService::default();
    let token = service.submit(request).unwrap();
    let command = service.start_next().unwrap();
    assert!(service.prepared(token));
    let (_control, controls) = std::sync::mpsc::channel();
    let mut terminal = None;
    execute_prepare(
        command,
        &AtomicBool::new(false),
        &controls,
        |fact| match fact {
            ExecutorFact::OrdinaryCopySourceKind { .. } => {
                panic!("Move cannot emit an ordinary Copy source-kind fact")
            }
            ExecutorFact::CopyDirectoryRetryProvenance { .. } => {
                panic!("Move cannot emit directory Copy retry provenance")
            }
            ExecutorFact::DirectoryMoveReplaceRenamePhaseIntent { .. }
            | ExecutorFact::DirectoryMoveReplaceRenameCleanupIntent { .. }
            | ExecutorFact::DirectoryMoveReplaceRenameCleanupDisposition { .. }
            | ExecutorFact::DirectoryMoveReplaceRenameBackupComplete { .. } => {
                panic!("ordinary file Move cannot enter directory Replace rename cleanup")
            }
            ExecutorFact::Terminal {
                token: actual,
                report,
            } => {
                assert_eq!(actual, token);
                terminal = service.terminal(actual, report)
            }
            ExecutorFact::Conflict { .. }
            | ExecutorFact::Progress { .. }
            | ExecutorFact::TrashReceipt { .. }
            | ExecutorFact::MoveGuardResolved { .. }
            | ExecutorFact::GuardedMoveNoEffectProof { .. }
            | ExecutorFact::CrossVolumeMoveNoEffectProof { .. }
            | ExecutorFact::PublishedMoveSourceRetained { .. }
            | ExecutorFact::PublishedMoveDisposition { .. }
            | ExecutorFact::CrossVolumeMoveReplacePhaseIntent { .. }
            | ExecutorFact::ReplaceBackupIntent { .. }
            | ExecutorFact::BatchRenamePlanIntent { .. }
            | ExecutorFact::RenameStageIntent { .. }
            | ExecutorFact::BatchRenameItemCompleted { .. }
            | ExecutorFact::DirectoryMoveManifestIntent { .. }
            | ExecutorFact::DirectoryMoveChildIntent { .. }
            | ExecutorFact::DirectoryMoveChildDisposition { .. }
            | ExecutorFact::DirectoryMoveRootIntent { .. }
            | ExecutorFact::DirectoryMoveRootDisposition { .. }
            | ExecutorFact::DirectoryMoveComplete { .. }
            | ExecutorFact::DirectoryMoveReplacePhaseIntent { .. }
            | ExecutorFact::DirectoryMoveReplaceBackupIntent { .. }
            | ExecutorFact::DirectoryMoveReplaceBackupDisposition { .. }
            | ExecutorFact::DirectoryMoveReplaceBackupComplete { .. }
            | ExecutorFact::CopyReplaceCleanupManifestIntent { .. }
            | ExecutorFact::CopyReplaceCleanupChildIntent { .. }
            | ExecutorFact::CopyReplaceCleanupChildDisposition { .. }
            | ExecutorFact::CopyReplaceCleanupComplete { .. }
            | ExecutorFact::ZipCreateLedgerIntent { .. }
            | ExecutorFact::SevenZipCreateLedgerIntent { .. }
            | ExecutorFact::ZipExtractLedgerIntent { .. }
            | ExecutorFact::CopyFailureProvenance { .. }
            | ExecutorFact::CopyStageCustody { .. }
            | ExecutorFact::CreatedObjectUndoCandidate { .. }
            | ExecutorFact::DirectoryCopyUndoCandidate { .. }
            | ExecutorFact::MoveUndoCandidate { .. }
            | ExecutorFact::SevenZipExtractBatchIntent { .. } => {}
        },
    );
    let report = match terminal.unwrap() {
        crate::operations::model::ServiceEvent::TerminalCommitted { report, .. } => report,
    };
    assert_eq!(report.outcome, TerminalOutcome::Succeeded);
    assert_eq!(report.change_hints.len(), 2);
    assert!(!source.exists());
    assert_eq!(
        std::fs::read(destination.join("item.txt")).unwrap(),
        b"contents"
    );
}

#[cfg(target_os = "windows")]
#[test]
fn move_worker_falls_back_for_junction_source_parent_without_move_undo_candidate() {
    let root = tempfile::tempdir_in(env!("CARGO_MANIFEST_DIR")).unwrap();
    let source_parent = root.path().join("source-parent");
    let source_alias = root.path().join("source-alias");
    let destination_parent = root.path().join("destination-parent");
    std::fs::create_dir_all(&source_parent).unwrap();
    std::fs::create_dir(&destination_parent).unwrap();
    crate::operations::rename::create_test_mount_point_junction(&source_alias, &source_parent)
        .unwrap();
    let source = source_alias.join("one");
    let actual_source = source_parent.join("one");
    let destination = destination_parent.join("one");
    std::fs::write(&actual_source, b"junction source").unwrap();
    let source_identity = filesystem_identity(&source, crate::directory::EntryKind::File);
    let destination_identity =
        filesystem_identity(&destination_parent, crate::directory::EntryKind::Folder);

    let mut service = OperationService::default();
    let token = service
        .submit(OperationRequest {
            kind: OperationKind::Move,
            virtual_source: None,
            sources: vec![source.clone()],
            destination: Some(destination_parent.clone()),
            move_identity_guard: Some(crate::operations::model::MoveIdentityGuard {
                source_identities: vec![source_identity],
                destination_identity,
            }),
            clipboard_move_source_evidence: None,
            rename_reparse_guard: None,
            move_destination_identity_guard: None,
            move_replace_source_evidence: None,
            trash_source_guards: None,
            source_cleanup_identity_guard: None,
            initial_conflict_policy: None,
            copy_destination_identity_guard: None,
            create_parent_directory_identity_guard: None,
            zip_create_guard: None,
            shortcut_create_guard: None,
            seven_zip_create_guard: None,
            seven_zip_extract_guard: None,
            origin: None,
            batch_rename_plan: None,
        })
        .unwrap();
    let command = service.start_next().unwrap();
    let (_control, controls) = std::sync::mpsc::channel();
    let mut terminal = None;
    let mut undo_candidates = 0;
    let mut no_effect_proofs = 0;
    execute_prepare(
        command,
        &AtomicBool::new(false),
        &controls,
        |fact| match fact {
            ExecutorFact::Terminal {
                token: actual,
                report,
            } => {
                assert_eq!(actual, token);
                terminal = service.terminal(actual, report);
            }
            ExecutorFact::MoveUndoCandidate { .. } => undo_candidates += 1,
            ExecutorFact::GuardedMoveNoEffectProof { .. } => no_effect_proofs += 1,
            _ => {}
        },
    );
    let report = match terminal.unwrap() {
        crate::operations::model::ServiceEvent::TerminalCommitted { report, .. } => report,
    };
    assert_eq!(
        report.outcome,
        TerminalOutcome::Succeeded,
        "junction fallback: {:?}",
        report
            .receipts
            .first()
            .and_then(|receipt| receipt.detail.as_deref())
    );
    assert!(
        report
            .change_hints
            .iter()
            .any(|hint| hint.directory == source_alias)
    );
    assert!(
        report
            .change_hints
            .iter()
            .any(|hint| hint.directory == destination_parent)
    );
    assert_eq!(
        undo_candidates, 0,
        "the junction route is not Move Undo proof"
    );
    assert_eq!(no_effect_proofs, 0);
    assert!(!actual_source.exists());
    assert_eq!(std::fs::read(destination).unwrap(), b"junction source");
    crate::operations::rename::remove_test_mount_point_junction(&source_alias).unwrap();
}

#[cfg(target_os = "windows")]
#[test]
fn uncertain_relative_move_is_unknown_without_no_effect_or_undo_proof_and_reconciles_both_parents()
{
    let source = PathBuf::from(r"C:\source-parent\item");
    let destination = PathBuf::from(r"C:\destination-parent\item");
    let identity = crate::filesystem_identity::FilesystemIdentity::from_windows_parts(1, 2);
    let mut undo_proofs = 0;
    let result = super::move_file_guarded_with_undo_using(
        &source,
        &destination,
        &identity,
        &identity,
        &AtomicBool::new(false),
        &mut |_| undo_proofs += 1,
        |_, _, _, _, _, _| {
            Err(crate::operations::rename::RenameError::MutationUncertain(
                "injected native status/IOSB mismatch".into(),
            ))
        },
    );
    assert!(matches!(result, Err(super::CopyError::Unknown(_))));
    assert_eq!(undo_proofs, 0);
    assert!(!super::should_emit_guarded_move_no_effect_proof(&result));
    assert_eq!(super::copy_outcome(result).0, ItemOutcome::Unknown);
    let hints = super::change_hints(
        OperationKind::Move,
        std::slice::from_ref(&source),
        Some(destination.parent().unwrap().to_path_buf()),
    );
    assert!(
        hints
            .iter()
            .any(|hint| hint.directory == source.parent().unwrap())
    );
    assert!(
        hints
            .iter()
            .any(|hint| hint.directory == destination.parent().unwrap())
    );
}

