#[cfg(target_os = "windows")]
#[test]
fn guarded_keep_both_keeps_destination_pinned_during_conflict_wait() {
    let root = tempfile::tempdir().unwrap();
    let source = root.path().join("item.txt");
    let destination = root.path().join("destination");
    std::fs::write(&source, b"captured source").unwrap();
    std::fs::create_dir(&destination).unwrap();
    std::fs::write(destination.join("item.txt"), b"existing target").unwrap();
    let source_identity = filesystem_identity(&source, crate::directory::EntryKind::File);
    let destination_identity =
        filesystem_identity(&destination, crate::directory::EntryKind::Folder);

    let mut service = OperationService::default();
    service
        .submit(OperationRequest {
            kind: OperationKind::Move,
            virtual_source: None,
            sources: vec![source.clone()],
            destination: Some(destination.clone()),
            move_identity_guard: Some(super::super::model::MoveIdentityGuard {
                source_identities: vec![source_identity],
                destination_identity,
            }),
            clipboard_move_source_evidence: None,
            rename_reparse_guard: None,
            move_destination_identity_guard: None,
            move_replace_source_evidence: None,
            trash_source_guards: None,
            source_cleanup_identity_guard: None,
            initial_conflict_policy: None,
            copy_destination_identity_guard: None,
            create_parent_directory_identity_guard: None,
            zip_create_guard: None,
            shortcut_create_guard: None,
            seven_zip_create_guard: None,
            seven_zip_extract_guard: None,
            origin: None,
            batch_rename_plan: None,
        })
        .unwrap();
    let command = service.start_next().unwrap();
    let (control_sender, controls) = std::sync::mpsc::channel();
    let (facts_sender, facts) = std::sync::mpsc::channel();
    let worker = std::thread::spawn(move || {
        execute_prepare(command, &AtomicBool::new(false), &controls, |fact| {
            facts_sender.send(fact).unwrap();
        });
    });
    loop {
        if matches!(facts.recv().unwrap(), ExecutorFact::Conflict { .. }) {
            break;
        }
    }

    let displaced = root.path().join("displaced-destination");
    assert!(std::fs::rename(&destination, &displaced).is_err());
    control_sender
        .send(WorkerControl::Resolve {
            decision: ConflictDecision::KeepBoth,
            apply_to_remaining: false,
        })
        .unwrap();
    let report = loop {
        if let ExecutorFact::Terminal { report, .. } = facts.recv().unwrap() {
            break report;
        }
    };
    worker.join().unwrap();

    assert_eq!(report.outcome, TerminalOutcome::Succeeded);
    assert_eq!(
        std::fs::read(destination.join("item.txt")).unwrap(),
        b"existing target"
    );
    assert_eq!(
        std::fs::read(destination.join("item (2).txt")).unwrap(),
        b"captured source"
    );
    assert!(!source.exists());
    assert_eq!(std::fs::read_dir(&destination).unwrap().count(), 2);
    assert!(!displaced.exists());
}

