#[cfg(target_os = "windows")]
#[test]
fn cross_volume_move_replace_source_parent_rename_after_source_delete_ack_is_denied() {
    use crate::operations::journal::CrossVolumeMoveReplacePhase;
    use ::windows::Win32::Foundation::{ERROR_ACCESS_DENIED, ERROR_SHARING_VIOLATION};
    use std::os::windows::ffi::OsStringExt;

    let _hook = CrossVolumeReplaceAckHookGuard::install(
        CrossVolumeMoveReplacePhase::SourceDeleteIntent,
        |ledger| {
            assert_eq!(
                ledger.phase,
                CrossVolumeMoveReplacePhase::SourceDeleteIntent
            );
            let source = PathBuf::from(std::ffi::OsString::from_wide(&ledger.source.units));
            let parent = source.parent().expect("source has a parent").to_path_buf();
            let renamed_sibling = parent
                .parent()
                .expect("source parent is inside the temp fixture")
                .join("renamed-source-parent");
            assert!(!renamed_sibling.exists(), "rename target starts absent");

            let parent_identity = filesystem_identity(&parent, crate::directory::EntryKind::Folder);
            let source_identity = filesystem_identity(&source, crate::directory::EntryKind::File);
            assert_eq!(ledger.source_identity, {
                let (volume, index) = source_identity.windows_parts().unwrap();
                format!("{volume:08x}:{index:016x}")
            });
            let source_bytes = std::fs::read(&source).unwrap();
            assert_eq!(source_bytes, b"incoming exact source bytes");
            assert!(
                windows::later_write_mapping_is_blocked(&source),
                "the acknowledged source must reject a fresh writable mapping while still present"
            );

            let error = std::fs::rename(&parent, &renamed_sibling)
                .expect_err("live source route pin must deny parent rename");
            eprintln!("source parent rename was denied: {error:?}");
            assert!(
                matches!(error.raw_os_error(), Some(code) if code == ERROR_ACCESS_DENIED.0 as i32 || code == ERROR_SHARING_VIOLATION.0 as i32),
                "expected ERROR_ACCESS_DENIED or ERROR_SHARING_VIOLATION, got {error:?}"
            );
            assert_eq!(
                filesystem_identity(&parent, crate::directory::EntryKind::Folder),
                parent_identity
            );
            assert_eq!(
                filesystem_identity(&source, crate::directory::EntryKind::File),
                source_identity
            );
            assert_eq!(std::fs::read(&source).unwrap(), source_bytes);
            assert!(!renamed_sibling.exists(), "rename target remains absent");

            let source_root = parent
                .parent()
                .expect("source parent is inside the source root")
                .to_path_buf();
            let renamed_source_root = source_root
                .parent()
                .expect("source root is inside the temp fixture")
                .join("renamed-source-root");
            assert!(
                !renamed_source_root.exists(),
                "source-root rename target starts absent"
            );
            let source_root_identity =
                filesystem_identity(&source_root, crate::directory::EntryKind::Folder);

            let error = std::fs::rename(&source_root, &renamed_source_root)
                .expect_err("held source-root route lease must deny ancestor rename");
            eprintln!("source-root ancestor rename was denied: {error:?}");
            assert!(
                matches!(error.raw_os_error(), Some(code) if code == ERROR_ACCESS_DENIED.0 as i32 || code == ERROR_SHARING_VIOLATION.0 as i32),
                "expected ERROR_ACCESS_DENIED or ERROR_SHARING_VIOLATION, got {error:?}"
            );
            assert_eq!(
                filesystem_identity(&source_root, crate::directory::EntryKind::Folder),
                source_root_identity
            );
            assert_eq!(
                filesystem_identity(&parent, crate::directory::EntryKind::Folder),
                parent_identity
            );
            assert_eq!(
                filesystem_identity(&source, crate::directory::EntryKind::File),
                source_identity
            );
            assert_eq!(std::fs::read(&source).unwrap(), source_bytes);
            assert!(
                !renamed_source_root.exists(),
                "source-root rename target remains absent"
            );
        },
    );

    run_cross_volume_move_replace_adapter(
        false, false, false, false, false, false, false, false, false, false, false, false, false,
        false, false, false, false,
    );
    assert!(
        CROSS_VOLUME_REPLACE_ACK_HOOK_FIRED.with(std::cell::Cell::get),
        "one-shot SourceDeleteIntent ACK hook must fire exactly once"
    );
}

#[cfg(target_os = "windows")]
#[test]
fn cross_volume_move_replace_published_destination_rejects_writable_open_at_source_delete_ack() {
    use crate::operations::journal::CrossVolumeMoveReplacePhase;
    use ::windows::Win32::Foundation::{ERROR_ACCESS_DENIED, ERROR_SHARING_VIOLATION};
    use ::windows::Win32::Storage::FileSystem::{
        FILE_SHARE_DELETE, FILE_SHARE_READ, FILE_SHARE_WRITE,
    };
    use std::os::windows::{ffi::OsStringExt, fs::OpenOptionsExt};

    let writable_open_allowed = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let writable_open_allowed_at_ack = writable_open_allowed.clone();
    let _hook = CrossVolumeReplaceAckHookGuard::install(
        CrossVolumeMoveReplacePhase::SourceDeleteIntent,
        move |ledger| {
            assert_eq!(
                ledger.phase,
                CrossVolumeMoveReplacePhase::SourceDeleteIntent
            );
            let path = |path: &crate::operations::journal::JournalPath| {
                PathBuf::from(std::ffi::OsString::from_wide(&path.units))
            };
            let source = path(&ledger.source);
            let destination = path(&ledger.destination);
            let backup = path(&ledger.backup);
            let stage = path(&ledger.stage);
            let source_identity = filesystem_identity(&source, crate::directory::EntryKind::File);
            let destination_identity =
                filesystem_identity(&destination, crate::directory::EntryKind::File);
            let backup_identity = filesystem_identity(&backup, crate::directory::EntryKind::File);
            assert_eq!(ledger.source_identity, {
                let (volume, index) = source_identity.windows_parts().unwrap();
                format!("{volume:08x}:{index:016x}")
            });
            assert_eq!(ledger.approved_target_identity, {
                let (volume, index) = backup_identity.windows_parts().unwrap();
                format!("{volume:08x}:{index:016x}")
            });
            let (destination_volume, destination_index) =
                destination_identity.windows_parts().unwrap();
            assert_eq!(
                ledger.stage_identity,
                format!("{destination_volume:08x}:{destination_index:016x}"),
                "published destination must retain the staged file identity"
            );
            assert_eq!(
                std::fs::read(&source).unwrap(),
                b"incoming exact source bytes"
            );
            assert_eq!(
                std::fs::read(&destination).unwrap(),
                b"incoming exact source bytes"
            );
            use sha2::Digest;
            assert_eq!(
                ledger.content_sha256,
                format!(
                    "{:x}",
                    sha2::Sha256::digest(std::fs::read(&destination).unwrap())
                )
            );
            assert_eq!(std::fs::read(&backup).unwrap(), b"old target bytes");
            assert!(
                !stage.exists(),
                "the original stage path must be absent after publication"
            );

            let open = std::fs::OpenOptions::new()
                .read(true)
                .write(true)
                .share_mode(FILE_SHARE_READ.0 | FILE_SHARE_WRITE.0 | FILE_SHARE_DELETE.0)
                .open(&destination);
            match open {
                Ok(file) => {
                    drop(file);
                    writable_open_allowed_at_ack.store(true, Ordering::Release);
                }
                Err(error) => assert!(
                    matches!(error.raw_os_error(), Some(code) if code == ERROR_ACCESS_DENIED.0 as i32 || code == ERROR_SHARING_VIOLATION.0 as i32),
                    "expected ERROR_ACCESS_DENIED or ERROR_SHARING_VIOLATION, got {error:?}"
                ),
            }

            assert_eq!(
                filesystem_identity(&source, crate::directory::EntryKind::File),
                source_identity
            );
            assert_eq!(
                filesystem_identity(&destination, crate::directory::EntryKind::File),
                destination_identity
            );
            assert_eq!(
                filesystem_identity(&backup, crate::directory::EntryKind::File),
                backup_identity
            );
            assert_eq!(
                std::fs::read(&source).unwrap(),
                b"incoming exact source bytes"
            );
            assert_eq!(
                std::fs::read(&destination).unwrap(),
                b"incoming exact source bytes"
            );
            assert_eq!(std::fs::read(&backup).unwrap(), b"old target bytes");
            assert!(!stage.exists(), "stage path remains absent");
        },
    );

    run_cross_volume_move_replace_adapter(
        false, false, false, false, false, false, false, false, false, false, false, false, false,
        false, false, false, false,
    );
    assert!(
        !writable_open_allowed.load(Ordering::Acquire),
        "published destination unexpectedly allowed a new writable open"
    );
    assert!(
        CROSS_VOLUME_REPLACE_ACK_HOOK_FIRED.with(std::cell::Cell::get),
        "one-shot SourceDeleteIntent ACK hook must fire exactly once"
    );
}

