#[cfg(target_os = "windows")]
#[test]
fn cross_volume_move_replace_external_destination_leaf_reuse_after_publish_ack_fails_closed() {
    let _hook = CrossVolumeReplaceAckHookGuard::install(
        crate::operations::journal::CrossVolumeMoveReplacePhase::PublishIntent,
        |ledger| {
            use std::io::Write;
            use std::os::windows::ffi::OsStringExt;

            assert_eq!(
                ledger.phase,
                crate::operations::journal::CrossVolumeMoveReplacePhase::PublishIntent
            );
            let destination =
                PathBuf::from(std::ffi::OsString::from_wide(&ledger.destination.units));
            assert!(
                !destination.exists(),
                "destination must be vacant after PublishIntent ACK"
            );
            std::fs::OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(&destination)
                .unwrap()
                .write_all(b"external leaf owner bytes")
                .unwrap();
            let identity = filesystem_identity(&destination, crate::directory::EntryKind::File);
            CROSS_VOLUME_REPLACE_ACK_DESTINATION_IDENTITY
                .with(|stored| *stored.borrow_mut() = Some(identity));
        },
    );
    run_cross_volume_move_replace_adapter(
        false, false, false, false, false, false, false, false, false, false, false, false, false,
        false, false, false, false,
    );
    assert!(
        CROSS_VOLUME_REPLACE_ACK_HOOK_FIRED.with(std::cell::Cell::get),
        "one-shot PublishIntent ACK hook must fire exactly once"
    );
}

#[cfg(target_os = "windows")]
#[test]
fn cross_volume_move_replace_backup_path_mutations_after_delete_ack_are_denied() {
    use ::windows::Win32::Foundation::{ERROR_ACCESS_DENIED, ERROR_SHARING_VIOLATION};
    use ::windows::Win32::Storage::FileSystem::{MOVEFILE_REPLACE_EXISTING, MoveFileExW};
    use ::windows::core::PCWSTR;
    use std::io::Write;
    use std::os::windows::ffi::{OsStrExt, OsStringExt};

    let _hook = CrossVolumeReplaceAckHookGuard::install(
        crate::operations::journal::CrossVolumeMoveReplacePhase::BackupDeleteIntent,
        move |ledger| {
            assert_eq!(
                ledger.phase,
                crate::operations::journal::CrossVolumeMoveReplacePhase::BackupDeleteIntent
            );
            let path = |journal_path: &crate::operations::journal::JournalPath| {
                PathBuf::from(std::ffi::OsString::from_wide(&journal_path.units))
            };
            let backup = path(&ledger.backup);
            let approved_identity = filesystem_identity(&backup, crate::directory::EntryKind::File);
            let (volume, index) = approved_identity.windows_parts().unwrap();
            assert_eq!(
                ledger.approved_target_identity,
                format!("{volume:08x}:{index:016x}")
            );
            assert_eq!(std::fs::read(&backup).unwrap(), b"old target bytes");

            let sentinel = backup.with_file_name("external-backup-sentinel.txt");
            std::fs::OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(&sentinel)
                .unwrap()
                .write_all(b"foreign sentinel bytes")
                .unwrap();
            let sentinel_identity =
                filesystem_identity(&sentinel, crate::directory::EntryKind::File);

            let assert_unchanged = || {
                assert_eq!(std::fs::read(&backup).unwrap(), b"old target bytes");
                assert_eq!(
                    filesystem_identity(&backup, crate::directory::EntryKind::File),
                    approved_identity
                );
                assert_eq!(std::fs::read(&sentinel).unwrap(), b"foreign sentinel bytes");
                assert_eq!(
                    filesystem_identity(&sentinel, crate::directory::EntryKind::File),
                    sentinel_identity
                );
            };
            let assert_sharing_denied = |error: std::io::Error| {
                assert!(
                    matches!(error.raw_os_error(), Some(code) if code == ERROR_ACCESS_DENIED.0 as i32 || code == ERROR_SHARING_VIOLATION.0 as i32),
                    "expected a Windows sharing/access denial, got {error:?}"
                );
            };

            let renamed = backup.with_file_name("renamed-held-backup.txt");
            assert_sharing_denied(std::fs::rename(&backup, &renamed).unwrap_err());
            assert_unchanged();
            assert_sharing_denied(std::fs::remove_file(&backup).unwrap_err());
            assert_unchanged();
            assert_sharing_denied(
                std::fs::OpenOptions::new()
                    .write(true)
                    .open(&backup)
                    .unwrap_err(),
            );
            assert_unchanged();

            let sentinel_wide = sentinel
                .as_os_str()
                .encode_wide()
                .chain(std::iter::once(0))
                .collect::<Vec<_>>();
            let backup_wide = backup
                .as_os_str()
                .encode_wide()
                .chain(std::iter::once(0))
                .collect::<Vec<_>>();
            let replace_result = unsafe {
                MoveFileExW(
                    PCWSTR(sentinel_wide.as_ptr()),
                    PCWSTR(backup_wide.as_ptr()),
                    MOVEFILE_REPLACE_EXISTING,
                )
            };
            let Err(error) = replace_result else {
                panic!("foreign sentinel must not replace the held backup path");
            };
            assert!(
                matches!(
                    error.code().0 as u32 & 0xffff,
                    code if code == ERROR_ACCESS_DENIED.0 || code == ERROR_SHARING_VIOLATION.0
                ),
                "expected MoveFileExW sharing/access denial, got {error:?}"
            );
            assert_unchanged();
        },
    );

    run_cross_volume_move_replace_adapter(
        false, false, false, false, false, false, false, false, false, false, false, false, false,
        false, false, false, false,
    );
    assert!(
        CROSS_VOLUME_REPLACE_ACK_HOOK_FIRED.with(std::cell::Cell::get),
        "one-shot BackupDeleteIntent ACK hook must fire exactly once"
    );
}

