#[cfg(target_os = "windows")]
const CROSS_VOLUME_CRASH_CHILD_ENV: &str = "GPUI_FILER_REPLACE_CRASH_CHILD";

#[cfg(target_os = "windows")]
thread_local! {
    static CROSS_VOLUME_CRASH_ATTEMPT_KEY: std::cell::RefCell<Option<String>> = const { std::cell::RefCell::new(None) };
    static CROSS_VOLUME_REPLACE_ACK_HOOK: std::cell::RefCell<Option<(crate::operations::journal::CrossVolumeMoveReplacePhase, Box<dyn FnOnce(&crate::operations::journal::JournalCrossVolumeMoveReplace)>)>> = const { std::cell::RefCell::new(None) };
    static CROSS_VOLUME_REPLACE_ACK_HOOK_FIRED: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    static CROSS_VOLUME_REPLACE_ACK_DESTINATION_IDENTITY: std::cell::RefCell<Option<crate::filesystem_identity::FilesystemIdentity>> = const { std::cell::RefCell::new(None) };
    static CROSS_VOLUME_REPLACE_REJECT_STAGE_OWNED_ACK: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    static CROSS_VOLUME_REPLACE_FAIL_STAGE_OWNED_REAL_IO: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    static CROSS_VOLUME_REPLACE_FAIL_SOURCE_DISPOSITION: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    static CROSS_VOLUME_REPLACE_SOURCE_DISPOSITION_FAILED: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    static CROSS_VOLUME_REPLACE_SOURCE_DISPOSITION_LEDGER: std::cell::RefCell<Option<crate::operations::journal::JournalCrossVolumeMoveReplace>> = const { std::cell::RefCell::new(None) };
}

#[cfg(target_os = "windows")]
struct CrossVolumeReplaceSourceDispositionFailureGuard;

#[cfg(target_os = "windows")]
impl CrossVolumeReplaceSourceDispositionFailureGuard {
    fn install() -> Self {
        CROSS_VOLUME_REPLACE_FAIL_SOURCE_DISPOSITION.with(|armed| armed.set(true));
        CROSS_VOLUME_REPLACE_SOURCE_DISPOSITION_FAILED.with(|fired| fired.set(false));
        CROSS_VOLUME_REPLACE_SOURCE_DISPOSITION_LEDGER.with(|ledger| *ledger.borrow_mut() = None);
        Self
    }
}

#[cfg(target_os = "windows")]
impl Drop for CrossVolumeReplaceSourceDispositionFailureGuard {
    fn drop(&mut self) {
        CROSS_VOLUME_REPLACE_FAIL_SOURCE_DISPOSITION.with(|armed| armed.set(false));
        CROSS_VOLUME_REPLACE_SOURCE_DISPOSITION_FAILED.with(|fired| fired.set(false));
        CROSS_VOLUME_REPLACE_SOURCE_DISPOSITION_LEDGER.with(|ledger| *ledger.borrow_mut() = None);
    }
}

#[cfg(target_os = "windows")]
pub(super) fn fail_cross_volume_source_disposition_after_ack(
    ledger: &crate::operations::journal::JournalCrossVolumeMoveReplace,
) -> bool {
    use crate::operations::journal::CrossVolumeMoveReplacePhase;

    if ledger.phase != CrossVolumeMoveReplacePhase::SourceDeleteIntent {
        return false;
    }
    CROSS_VOLUME_REPLACE_FAIL_SOURCE_DISPOSITION.with(|armed| {
        if !armed.replace(false) {
            return false;
        }
        CROSS_VOLUME_REPLACE_SOURCE_DISPOSITION_FAILED.with(|fired| fired.set(true));
        CROSS_VOLUME_REPLACE_SOURCE_DISPOSITION_LEDGER
            .with(|captured| *captured.borrow_mut() = Some(ledger.clone()));
        true
    })
}

#[cfg(target_os = "windows")]
fn cross_volume_replace_collision_identity_slot()
-> &'static std::sync::Mutex<Option<(PathBuf, crate::filesystem_identity::FilesystemIdentity)>> {
    static SLOT: std::sync::OnceLock<
        std::sync::Mutex<Option<(PathBuf, crate::filesystem_identity::FilesystemIdentity)>>,
    > = std::sync::OnceLock::new();
    SLOT.get_or_init(|| std::sync::Mutex::new(None))
}

#[cfg(target_os = "windows")]
struct CrossVolumeReplaceAckHookGuard;

#[cfg(target_os = "windows")]
impl CrossVolumeReplaceAckHookGuard {
    fn install(
        phase: crate::operations::journal::CrossVolumeMoveReplacePhase,
        hook: impl FnOnce(&crate::operations::journal::JournalCrossVolumeMoveReplace) + 'static,
    ) -> Self {
        CROSS_VOLUME_REPLACE_ACK_HOOK.with(|slot| {
            assert!(slot.borrow_mut().replace((phase, Box::new(hook))).is_none());
        });
        CROSS_VOLUME_REPLACE_ACK_HOOK_FIRED.with(|fired| fired.set(false));
        CROSS_VOLUME_REPLACE_ACK_DESTINATION_IDENTITY
            .with(|identity| *identity.borrow_mut() = None);
        Self
    }
}

#[cfg(target_os = "windows")]
impl Drop for CrossVolumeReplaceAckHookGuard {
    fn drop(&mut self) {
        CROSS_VOLUME_REPLACE_ACK_HOOK.with(|slot| *slot.borrow_mut() = None);
        CROSS_VOLUME_REPLACE_ACK_HOOK_FIRED.with(|fired| fired.set(false));
        CROSS_VOLUME_REPLACE_ACK_DESTINATION_IDENTITY
            .with(|identity| *identity.borrow_mut() = None);
    }
}

#[cfg(target_os = "windows")]
pub(super) fn checkpoint_cross_volume_replace_after_ack(
    ledger: &crate::operations::journal::JournalCrossVolumeMoveReplace,
) {
    let hook = CROSS_VOLUME_REPLACE_ACK_HOOK.with(|slot| {
        if slot
            .borrow()
            .as_ref()
            .is_some_and(|(phase, _)| *phase == ledger.phase)
        {
            slot.borrow_mut().take().map(|(_, hook)| hook)
        } else {
            None
        }
    });
    if let Some(hook) = hook {
        CROSS_VOLUME_REPLACE_ACK_HOOK_FIRED.with(|fired| fired.set(true));
        hook(ledger);
    }
    let checkpoint_phase = match std::env::var("GPUI_FILER_CRASH_PHASE").as_deref() {
        Ok("stage-ready-acked") => {
            crate::operations::journal::CrossVolumeMoveReplacePhase::StageReady
        }
        Ok("displace-intent-acked") => {
            crate::operations::journal::CrossVolumeMoveReplacePhase::DisplaceIntent
        }
        Ok("publish-intent-acked") => {
            crate::operations::journal::CrossVolumeMoveReplacePhase::PublishIntent
        }
        Ok("source-delete-intent-acked") => {
            crate::operations::journal::CrossVolumeMoveReplacePhase::SourceDeleteIntent
        }
        Ok("backup-delete-intent-acked") => {
            crate::operations::journal::CrossVolumeMoveReplacePhase::BackupDeleteIntent
        }
        _ => return,
    };
    if ledger.phase != checkpoint_phase {
        return;
    }

    let key = CROSS_VOLUME_CRASH_ATTEMPT_KEY.with(|key| {
        key.borrow()
            .clone()
            .expect("crash child records the attempt key before waiting for phase ack")
    });
    let checkpoint_path = PathBuf::from(std::env::var_os("GPUI_FILER_CRASH_CHECKPOINT").unwrap());
    let checkpoint = serde_json::to_vec(&(key, ledger)).unwrap();
    use std::io::Write;
    let checkpoint_temp_path = checkpoint_path.with_extension("json.tmp");
    let mut file = std::fs::File::create(&checkpoint_temp_path).unwrap();
    file.write_all(&checkpoint).unwrap();
    file.sync_all().unwrap();
    drop(file);
    std::fs::rename(&checkpoint_temp_path, &checkpoint_path).unwrap();

    // The exact durable acknowledgement has been consumed. Hold this worker
    // before it can return from the barrier and displace the target.
    let (_hold_sender, hold_receiver) = std::sync::mpsc::channel::<()>();
    let _ = hold_receiver.recv();
    unreachable!("child should be terminated after the acknowledged intent");
}

#[cfg(target_os = "windows")]
pub(super) fn checkpoint_cross_volume_replace_after_partial_stage_write(
    ledger: &crate::operations::journal::JournalCrossVolumeMoveReplace,
    written: usize,
) {
    if std::env::var_os(CROSS_VOLUME_CRASH_CHILD_ENV).is_none()
        || std::env::var("GPUI_FILER_CRASH_PHASE").as_deref() != Ok("stage-owned-partial-write")
    {
        return;
    }
    assert_eq!(
        ledger.phase,
        crate::operations::journal::CrossVolumeMoveReplacePhase::StageOwned
    );
    assert!(written > 0);
    use std::os::windows::ffi::OsStringExt;
    let stage = PathBuf::from(std::ffi::OsString::from_wide(&ledger.stage.units));
    let stage_bytes = std::fs::read(&stage).expect("first successful stage write is visible");
    assert_eq!(stage_bytes.len(), written);
    let key = CROSS_VOLUME_CRASH_ATTEMPT_KEY.with(|key| {
        key.borrow()
            .clone()
            .expect("crash attempt key recorded before execution")
    });
    let checkpoint_path = PathBuf::from(
        std::env::var_os("GPUI_FILER_CRASH_CHECKPOINT").expect("parent supplies checkpoint path"),
    );
    let checkpoint = serde_json::json!({
        "selector": "stage-owned-partial-write",
        "stage_owned_ack_consumed": true,
        "attempt": key,
        "ledger": ledger,
        "stage_len": stage_bytes.len(),
        "stage_bytes": stage_bytes,
    });
    use std::io::Write;
    let checkpoint_temp_path = checkpoint_path.with_extension("json.tmp");
    let mut file = std::fs::File::create(&checkpoint_temp_path).unwrap();
    file.write_all(&serde_json::to_vec(&checkpoint).unwrap())
        .unwrap();
    file.sync_all().unwrap();
    drop(file);
    std::fs::rename(&checkpoint_temp_path, &checkpoint_path).unwrap();
    // The test child stays here after the first real write; the parent kills and reaps it.
    let (_hold_sender, hold_receiver) = std::sync::mpsc::channel::<()>();
    let _ = hold_receiver.recv();
    unreachable!("child should be terminated after the partial-stage checkpoint");
}

#[cfg(target_os = "windows")]
pub(super) fn checkpoint_cross_volume_replace_after_full_stage_write(
    ledger: &crate::operations::journal::JournalCrossVolumeMoveReplace,
) {
    if std::env::var_os(CROSS_VOLUME_CRASH_CHILD_ENV).is_none()
        || std::env::var("GPUI_FILER_CRASH_PHASE").as_deref() != Ok("stage-owned-full-write")
    {
        return;
    }
    use crate::operations::journal::CrossVolumeMoveReplacePhase;
    use std::os::windows::ffi::OsStringExt;
    assert_eq!(ledger.phase, CrossVolumeMoveReplacePhase::StageOwned);
    assert!(ledger.content_sha256.is_empty());
    let stage = PathBuf::from(std::ffi::OsString::from_wide(&ledger.stage.units));
    let stage_bytes = std::fs::read(&stage).expect("complete pre-flush stage is visible");
    assert!(!stage_bytes.is_empty());
    let key = CROSS_VOLUME_CRASH_ATTEMPT_KEY.with(|key| {
        key.borrow()
            .clone()
            .expect("crash attempt key recorded before execution")
    });
    let checkpoint_path = PathBuf::from(
        std::env::var_os("GPUI_FILER_CRASH_CHECKPOINT").expect("parent supplies checkpoint path"),
    );
    let checkpoint = serde_json::json!({
        "selector": "stage-owned-full-write",
        "stage_owned_ack_consumed": true,
        "attempt": key,
        "ledger": ledger,
        "stage_len": stage_bytes.len(),
        "stage_bytes": stage_bytes,
    });
    use std::io::Write;
    let checkpoint_temp_path = checkpoint_path.with_extension("json.tmp");
    let mut file = std::fs::File::create(&checkpoint_temp_path).unwrap();
    file.write_all(&serde_json::to_vec(&checkpoint).unwrap())
        .unwrap();
    file.sync_all().unwrap();
    drop(file);
    std::fs::rename(&checkpoint_temp_path, &checkpoint_path).unwrap();
    // 完全なstageを書き終えた後、flush前のworkerを親が終了する。
    let (_hold_sender, hold_receiver) = std::sync::mpsc::channel::<()>();
    let _ = hold_receiver.recv();
    unreachable!("child should be terminated after the full-stage checkpoint");
}

#[cfg(target_os = "windows")]
pub(super) fn checkpoint_cross_volume_replace_after_flushed_stage_write(
    ledger: &crate::operations::journal::JournalCrossVolumeMoveReplace,
    content_sha256: &str,
) {
    if std::env::var_os(CROSS_VOLUME_CRASH_CHILD_ENV).is_none()
        || std::env::var("GPUI_FILER_CRASH_PHASE").as_deref() != Ok("stage-owned-flushed")
    {
        return;
    }
    use crate::operations::journal::CrossVolumeMoveReplacePhase;
    use std::os::windows::ffi::OsStringExt;
    assert_eq!(ledger.phase, CrossVolumeMoveReplacePhase::StageOwned);
    assert!(ledger.content_sha256.is_empty());
    let stage = PathBuf::from(std::ffi::OsString::from_wide(&ledger.stage.units));
    let source = PathBuf::from(std::ffi::OsString::from_wide(&ledger.source.units));
    let stage_bytes = std::fs::read(&stage).expect("flushed complete stage is readable");
    let source_bytes = std::fs::read(&source).expect("pinned source is readable");
    assert_eq!(stage_bytes, source_bytes);
    use sha2::Digest;
    let verified_hash = format!("{:x}", sha2::Sha256::digest(&stage_bytes));
    assert_eq!(verified_hash, content_sha256);
    let key = CROSS_VOLUME_CRASH_ATTEMPT_KEY.with(|key| {
        key.borrow()
            .clone()
            .expect("crash attempt key recorded before execution")
    });
    let checkpoint_path = PathBuf::from(
        std::env::var_os("GPUI_FILER_CRASH_CHECKPOINT").expect("parent supplies checkpoint path"),
    );
    let checkpoint = serde_json::json!({
        "selector": "stage-owned-flushed",
        "stage_owned_ack_consumed": true,
        "attempt": key,
        "ledger": ledger,
        "stage_len": stage_bytes.len(),
        "stage_bytes": stage_bytes,
        "verified_content_sha256": verified_hash,
    });
    use std::io::Write;
    let checkpoint_temp_path = checkpoint_path.with_extension("json.tmp");
    let mut file = std::fs::File::create(&checkpoint_temp_path).unwrap();
    file.write_all(&serde_json::to_vec(&checkpoint).unwrap())
        .unwrap();
    file.sync_all().unwrap();
    drop(file);
    std::fs::rename(&checkpoint_temp_path, &checkpoint_path).unwrap();
    // flushとhash検証の後、StageReadyをjournalへ送る前にworkerを保持する。
    let (_hold_sender, hold_receiver) = std::sync::mpsc::channel::<()>();
    let _ = hold_receiver.recv();
    unreachable!("child should be terminated after the flushed-stage checkpoint");
}

#[cfg(target_os = "windows")]
fn cross_volume_move_replace_crash_child() {
    use crate::operations::journal::{
        CrossVolumeMoveReplacePhase, JournalAttempt, JournalKind, JournalPath,
        JournalReplaceBackup, JournalState, JournalStore, JournalWriter,
    };

    let source = PathBuf::from(std::env::var_os("GPUI_FILER_CRASH_SOURCE").unwrap());
    let destination_root =
        PathBuf::from(std::env::var_os("GPUI_FILER_CRASH_DESTINATION_ROOT").unwrap());
    let journal_path = PathBuf::from(std::env::var_os("GPUI_FILER_CRASH_JOURNAL").unwrap());
    let journal_path_for_diagnostics = journal_path.clone();
    let child_pid = std::process::id();
    let requested_checkpoint = std::env::var("GPUI_FILER_CRASH_PHASE").unwrap_or_default();
    macro_rules! require_journal_write {
        ($write:expr, $phase:expr) => {
            match $write {
                Ok(Ok(())) => {}
                Ok(Err(error)) => panic!(
                    "crash child pid={child_pid} checkpoint={requested_checkpoint:?} ledger_phase={:?} journal={} persistence failure: {error:?}",
                    $phase,
                    journal_path_for_diagnostics.display()
                ),
                Err(error) => panic!(
                    "crash child pid={child_pid} checkpoint={requested_checkpoint:?} ledger_phase={:?} journal={} receipt-channel failure: {error:?}",
                    $phase,
                    journal_path_for_diagnostics.display()
                ),
            }
        };
    }
    let checkpoint_path = PathBuf::from(std::env::var_os("GPUI_FILER_CRASH_CHECKPOINT").unwrap());
    let checkpoint_phase = match std::env::var("GPUI_FILER_CRASH_PHASE").as_deref() {
        Ok("stage-owned-durable-unacked") | Ok("stage-owned-partial-write") => {
            CrossVolumeMoveReplacePhase::StageOwned
        }
        Ok("stage-owned-full-write") => CrossVolumeMoveReplacePhase::StageOwned,
        Ok("stage-owned-flushed") => CrossVolumeMoveReplacePhase::StageOwned,
        Ok("stage-ready-acked") | Ok("stage-ready-durable-unacked") => {
            CrossVolumeMoveReplacePhase::StageReady
        }
        Ok("displace-intent-durable-unacked") | Ok("displace-intent-acked") => {
            CrossVolumeMoveReplacePhase::DisplaceIntent
        }
        Ok("publish-intent-durable-unacked") | Ok("publish-intent-acked") => {
            CrossVolumeMoveReplacePhase::PublishIntent
        }
        Ok("source-delete-intent-durable-unacked") | Ok("source-delete-intent-acked") => {
            CrossVolumeMoveReplacePhase::SourceDeleteIntent
        }
        Ok("backup-delete-intent-durable-unacked") | Ok("backup-delete-intent-acked") => {
            CrossVolumeMoveReplacePhase::BackupDeleteIntent
        }
        Ok("destination-published") => CrossVolumeMoveReplacePhase::DestinationPublished,
        Ok("source-deleted") => CrossVolumeMoveReplacePhase::SourceDeleted,
        Ok("backup-deleted") => CrossVolumeMoveReplacePhase::BackupDeleted,
        Ok("complete") | Ok("complete-durable-unacked") => CrossVolumeMoveReplacePhase::Complete,
        _ => CrossVolumeMoveReplacePhase::TargetDisplaced,
    };
    let durable_unacked_phase = matches!(
        std::env::var("GPUI_FILER_CRASH_PHASE").as_deref(),
        Ok("complete-durable-unacked")
            | Ok("stage-ready-durable-unacked")
            | Ok("displace-intent-durable-unacked")
            | Ok("publish-intent-durable-unacked")
            | Ok("source-delete-intent-durable-unacked")
            | Ok("backup-delete-intent-durable-unacked")
    );
    let acknowledged_before_mutation = matches!(
        std::env::var("GPUI_FILER_CRASH_PHASE").as_deref(),
        Ok("displace-intent-acked")
            | Ok("publish-intent-acked")
            | Ok("source-delete-intent-acked")
            | Ok("backup-delete-intent-acked")
    );
    let destination = destination_root.join("item.txt");

    let mut service = OperationService::default();
    let token = service
        .submit(OperationRequest {
            kind: OperationKind::Move,
            virtual_source: None,
            sources: vec![source.clone()],
            destination: Some(destination_root.clone()),
            move_identity_guard: None,
            clipboard_move_source_evidence: None,
            rename_reparse_guard: None,
            move_destination_identity_guard: None,
            move_replace_source_evidence: None,
            trash_source_guards: None,
            source_cleanup_identity_guard: None,
            initial_conflict_policy: None,
            copy_destination_identity_guard: None,
            create_parent_directory_identity_guard: None,
            zip_create_guard: None,
            shortcut_create_guard: None,
            seven_zip_create_guard: None,
            seven_zip_extract_guard: None,
            origin: None,
            batch_rename_plan: None,
        })
        .unwrap();
    let ExecutorCommand::Prepare {
        token: command_token,
        ..
    } = service.start_next().unwrap()
    else {
        panic!("move request must produce a prepare command");
    };
    assert_eq!(token, command_token);
    let source_handle = windows::prepare_regular_file_move_source(&source).unwrap();
    let target = windows::prepare_regular_file_replace(&destination).unwrap();
    let expected_parent =
        filesystem_identity(&destination_root, crate::directory::EntryKind::Folder);
    let key = format!("cross-volume-crash-{}", token.attempt_id().value());
    let mut attempt = JournalAttempt {
        created_folder_path: None,
        created_archive_path: None,
        zip_create: None,
        seven_zip_create: None,
        seven_zip_create_handles: None,
        seven_zip_extract_batch: None,
        seven_zip_extract_receipts: Vec::new(),
        zip_extract: None,
        zip_extract_items: Vec::new(),
        zip_extract_receipts: Vec::new(),
        key,
        kind: JournalKind::Move,
        state: JournalState::Running,
        sources: vec![JournalPath::from_path(&source)],
        destination: Some(JournalPath::from_path(&destination_root)),
        batch_rename_plan: Vec::new(),
        batch_rename_completed: Vec::new(),
        replace_backup: None,
        cross_volume_move_replace: None,
        directory_move_replace_rename: None,
        rename_stage: None,
        directory_moves: Vec::new(),
        copy_replace_cleanups: Vec::new(),
        copy_directory_publications: Vec::new(),
        copy_directory_stage: None,
        receipts_recorded: false,
        virtual_source_name: None,
        virtual_source_size: None,
        virtual_sources: Vec::new(),
        virtual_item_status: Vec::new(),
        terminal_outcome: None,
    };
    CROSS_VOLUME_CRASH_ATTEMPT_KEY.with(|key| *key.borrow_mut() = Some(attempt.key.clone()));
    let writer = JournalWriter::start(JournalStore::open(journal_path).unwrap());
    writer
        .upsert_with_reply(attempt.clone())
        .recv_blocking()
        .unwrap()
        .unwrap();
    let (control_sender, controls) = std::sync::mpsc::channel();
    let mut backup_path = None;
    let _result = windows::replace_move_regular_file(
        &source,
        source_handle,
        &destination,
        target,
        &expected_parent,
        token,
        ItemId(0),
        &AtomicBool::new(false),
        &controls,
        &mut |fact| match fact {
            ExecutorFact::ReplaceBackupIntent { backup, .. } => {
                attempt.replace_backup = Some(JournalReplaceBackup {
                    source: JournalPath::from_path(&source),
                    destination: JournalPath::from_path(&destination),
                    backup: JournalPath::from_path(&backup),
                });
                writer
                    .upsert_with_reply(attempt.clone())
                    .recv_blocking()
                    .unwrap()
                    .unwrap();
                backup_path = Some(backup.clone());
                control_sender
                    .send(WorkerControl::ReplaceBackupJournaledExact {
                        token,
                        item: ItemId(0),
                        source: source.clone(),
                        destination: destination.clone(),
                        backup,
                    })
                    .unwrap();
            }
            ExecutorFact::CrossVolumeMoveReplacePhaseIntent {
                token: intent_token,
                ledger,
            } => {
                assert_eq!(intent_token, token);
                if checkpoint_phase == CrossVolumeMoveReplacePhase::StageOwned
                    && std::env::var("GPUI_FILER_CRASH_PHASE").as_deref()
                        == Ok("stage-owned-durable-unacked")
                    && ledger.phase == CrossVolumeMoveReplacePhase::StageOwned
                {
                    let durable = attempt
                        .cross_volume_move_replace
                        .clone()
                        .expect("StageCreateIntent was durably acknowledged");
                    assert_eq!(
                        durable.phase,
                        CrossVolumeMoveReplacePhase::StageCreateIntent
                    );
                    let checkpoint = serde_json::to_vec(&(attempt.key.clone(), durable)).unwrap();
                    use std::io::Write;
                    let checkpoint_temp_path = checkpoint_path.with_extension("json.tmp");
                    let mut file = std::fs::File::create(&checkpoint_temp_path).unwrap();
                    file.write_all(&checkpoint).unwrap();
                    file.sync_all().unwrap();
                    drop(file);
                    std::fs::rename(&checkpoint_temp_path, &checkpoint_path).unwrap();
                    let (_hold_sender, hold_receiver) = std::sync::mpsc::channel::<()>();
                    let _ = hold_receiver.recv();
                    unreachable!("child should stop after CREATE_NEW before StageOwned ACK");
                }
                if ledger.phase == checkpoint_phase
                    && checkpoint_phase != CrossVolumeMoveReplacePhase::StageOwned
                    && (checkpoint_phase != CrossVolumeMoveReplacePhase::StageReady
                        || durable_unacked_phase)
                {
                    if acknowledged_before_mutation {
                        require_journal_write!(
                            writer
                                .advance_cross_volume_move_replace(
                                    attempt.key.clone(),
                                    ledger.clone()
                                )
                                .recv_blocking(),
                            ledger.phase
                        );
                        attempt.cross_volume_move_replace = Some(ledger.clone());
                        CROSS_VOLUME_CRASH_ATTEMPT_KEY
                            .with(|key| *key.borrow_mut() = Some(attempt.key.clone()));
                        control_sender
                            .send(WorkerControl::CrossVolumeMoveReplacePhaseJournaledExact {
                                token,
                                ledger,
                            })
                            .unwrap();
                        return;
                    }
                    if durable_unacked_phase {
                        require_journal_write!(
                            writer
                                .advance_cross_volume_move_replace(
                                    attempt.key.clone(),
                                    ledger.clone()
                                )
                                .recv_blocking(),
                            ledger.phase
                        );
                        attempt.cross_volume_move_replace = Some(ledger.clone());
                    }
                    let checkpoint = serde_json::to_vec(&(attempt.key.clone(), ledger)).unwrap();
                    use std::io::Write;
                    let checkpoint_temp_path = checkpoint_path.with_extension("json.tmp");
                    let mut file = std::fs::File::create(&checkpoint_temp_path).unwrap();
                    file.write_all(&checkpoint).unwrap();
                    file.sync_all().unwrap();
                    drop(file);
                    std::fs::rename(&checkpoint_temp_path, &checkpoint_path).unwrap();
                    let (_hold_sender, hold_receiver) = std::sync::mpsc::channel::<()>();
                    let _ = hold_receiver.recv();
                    unreachable!("child should be terminated at the displacement checkpoint");
                } else {
                    if ledger.phase == CrossVolumeMoveReplacePhase::StageCreateIntent {
                        require_journal_write!(
                            writer
                                .register_cross_volume_move_replace(
                                    attempt.key.clone(),
                                    ledger.clone()
                                )
                                .recv_blocking(),
                            ledger.phase
                        );
                    } else {
                        require_journal_write!(
                            writer
                                .advance_cross_volume_move_replace(
                                    attempt.key.clone(),
                                    ledger.clone()
                                )
                                .recv_blocking(),
                            ledger.phase
                        );
                    }
                    attempt.cross_volume_move_replace = Some(ledger.clone());
                    control_sender
                        .send(WorkerControl::CrossVolumeMoveReplacePhaseJournaledExact {
                            token,
                            ledger,
                        })
                        .unwrap();
                }
            }
            other => panic!("unexpected Replace fact in crash child: {other:?}"),
        },
    );
    panic!("child escaped the crash boundary: backup={backup_path:?}");
}

