#[cfg(windows)]
const DIRECTORY_MOVE_REPLACE_CRASH_CHILD_ENV: &str =
    "GPUI_FILER_DIRECTORY_MOVE_REPLACE_CRASH_CHILD";

#[cfg(windows)]
#[test]
fn directory_move_replace_staging_route_chain_differential_releases_only_target_parent_pin() {
    let source_fixture = local_ntfs_fixture();
    let destination_fixture = local_ntfs_fixture();
    let source = source_fixture.path().join("incoming");
    let destination_parent = destination_fixture.path().join("destination-parent");
    std::fs::create_dir_all(&source).unwrap();
    std::fs::create_dir(&destination_parent).unwrap();
    std::fs::write(source.join("incoming.bin"), b"staged child remains pinned").unwrap();

    let target = destination_parent.join("target");
    let backup = destination_parent.join("backup");
    let stage_path = destination_parent.join("stage");
    std::fs::create_dir(&target).unwrap();
    std::fs::write(target.join("old.bin"), b"exact old target").unwrap();

    let cancelled = AtomicBool::new(false);
    let mut source_tree = windows::preflight_pinned_source_tree(&source, &cancelled).unwrap();
    let mut target_tree = windows::preflight_pinned_source_tree(&target, &cancelled).unwrap();
    let target_parent_index = target_tree
        .root_handle_index
        .checked_sub(1)
        .expect("target route includes its destination parent");
    let target_parent_route_identity = match target_tree
        ._handles
        .get(target_parent_index)
        .and_then(Option::as_ref)
    {
        Some(windows::PinnedSourceHandle::Directory(parent)) => {
            windows::directory_identity_text(parent).unwrap()
        }
        _ => panic!("target's immediate-parent route pin must be held"),
    };
    // Descendant handles are not needed for the root displacement and could
    // otherwise independently deny moving the approved directory root.
    for entry in &target_tree.entries {
        target_tree._handles[entry.handle_index] = None;
    }
    let (target_root, target_identity) = match target_tree
        ._handles
        .get(target_tree.root_handle_index)
        .and_then(Option::as_ref)
    {
        Some(windows::PinnedSourceHandle::Directory(root)) => {
            (root.0, windows::directory_identity_text(root).unwrap())
        }
        _ => panic!("target root handle must remain pinned"),
    };
    assert_eq!(target_tree.root_identity, target_identity);

    let blocked_stage = windows::create_attempt_staging_root(&stage_path);
    assert!(
        matches!(
            &blocked_stage,
            Err(CopyError::Io(message))
                if message.contains("0x80070020") || message.contains("ERROR_SHARING_VIOLATION")
        ),
        "stage creation should fail while the target immediate-parent read pin is held: {:?}",
        blocked_stage.as_ref().err()
    );
    assert!(!stage_path.exists());
    let target_after_blocked_stage = windows::open_published_root(&target).unwrap();
    assert_eq!(
        windows::directory_identity_text(&target_after_blocked_stage).unwrap(),
        target_identity
    );
    assert!(target.exists());
    drop(target_after_blocked_stage);

    target_tree._handles[target_parent_index] = None;
    assert!(
        target_tree._handles[..target_parent_index]
            .iter()
            .all(Option::is_some)
    );
    let destination_parent_lease =
        windows::open_pinned_destination_parent_for_test(&destination_parent).unwrap();
    assert_eq!(
        windows::directory_identity_text(&destination_parent_lease).unwrap(),
        target_parent_route_identity
    );
    let staging = windows::create_attempt_staging_root(&stage_path).unwrap();
    let staged = windows::stage_pinned_source_tree(&mut source_tree, staging, &cancelled).unwrap();
    assert_eq!(staged.nodes.len(), 1);
    assert!(!staged.root_chain.is_empty());

    windows::publish_no_replace_handle(target_root, &backup).unwrap_or_else(|error| {
        panic!("absolute rename should succeed after releasing only target parent route pin while staging and lease remain held: {error:?}")
    });
    assert!(!target.exists());
    assert!(backup.starts_with(&destination_parent));
    let backup_root = windows::open_published_root(&backup).unwrap();
    assert_eq!(
        windows::directory_identity_text(&backup_root).unwrap(),
        target_identity
    );
    assert_eq!(
        std::fs::read(backup.join("old.bin")).unwrap(),
        b"exact old target"
    );
    assert_eq!(
        std::fs::read(stage_path.join("incoming.bin")).unwrap(),
        b"staged child remains pinned"
    );

    drop(staged);
    drop(backup_root);
    drop(target_tree);
    drop(destination_parent_lease);
    drop(source_tree);
}

