#[test]
fn directory_move_replace_publish_rejects_external_destination_leaf_reuse() {
    if std::env::var_os(DIRECTORY_MOVE_REPLACE_CRASH_CHILD_ENV).is_some() {
        directory_move_replace_displacement_crash_child();
        return;
    }
    run_directory_move_replace_process_crash(
        "publish-leaf-reuse",
        "operations::executor::tests::directory_move_replace_publish_rejects_external_destination_leaf_reuse",
    );
}

