#[cfg(windows)]
#[test]
fn virtual_keep_both_publishes_staged_bytes_without_rereading_provider() {
    let root = tempfile::tempdir().unwrap();
    let original = root.path().join("virtual.txt");
    std::fs::write(&original, b"existing").unwrap();
    let expected = b"one-shot provider bytes";
    let source = super::super::virtual_transfer::install_fake_data_object_session(
        "virtual.txt".into(),
        Some(expected.len() as u64),
        [Ok(expected.to_vec())],
    );
    let mut runtime = super::super::runtime::OperationRuntime::default();
    let token = runtime
        .submit(OperationRequest {
            kind: OperationKind::Copy,
            virtual_source: Some(source.clone()),
            sources: Vec::new(),
            destination: Some(root.path().to_path_buf()),
            batch_rename_plan: None,
            move_identity_guard: None,
            clipboard_move_source_evidence: None,
            rename_reparse_guard: None,
            move_destination_identity_guard: None,
            move_replace_source_evidence: None,
            trash_source_guards: None,
            source_cleanup_identity_guard: None,
            initial_conflict_policy: None,
            copy_destination_identity_guard: None,
            create_parent_directory_identity_guard: None,
            zip_create_guard: None,
            shortcut_create_guard: None,
            seven_zip_create_guard: None,
            seven_zip_extract_guard: None,
            origin: None,
        })
        .unwrap();
    let worker = runtime.start_next().unwrap();
    let (fact_tx, fact_rx) = std::sync::mpsc::channel();
    let worker_thread = std::thread::spawn(move || {
        execute_prepare(
            worker.command,
            worker.cancellation.as_ref(),
            &worker.controls,
            |fact| {
                let _ = fact_tx.send(fact);
            },
        )
    });
    let conflict = loop {
        let fact = fact_rx.recv().unwrap();
        let is_conflict = matches!(fact, ExecutorFact::Conflict { .. });
        let _ = runtime.commit_fact(fact);
        if is_conflict {
            break runtime
                .job(token)
                .unwrap()
                .attempts
                .last()
                .unwrap()
                .pending_conflict
                .as_ref()
                .unwrap()
                .token;
        }
    };
    assert!(runtime.resolve_conflict(conflict, ConflictDecision::KeepBoth, false));
    loop {
        let fact = fact_rx.recv().unwrap();
        let terminal = matches!(fact, ExecutorFact::Terminal { .. });
        let _ = runtime.commit_fact(fact);
        if terminal {
            break;
        }
    }
    worker_thread.join().unwrap();
    let keep_both = super::super::model::keep_both_candidate_path(&original, 2).unwrap();
    assert_eq!(std::fs::read(&original).unwrap(), b"existing");
    assert_eq!(std::fs::read(keep_both).unwrap(), expected);
    assert_eq!(
        super::super::virtual_transfer::read_chunk(source.items[0].token, 1).unwrap_err(),
        super::super::virtual_transfer::TransferError::InvalidData(
            "virtual transfer session expired".into()
        )
    );
}

#[cfg(windows)]
#[test]
fn virtual_cancel_waits_for_blocked_read_then_cleans_and_releases_once() {
    let root = tempfile::tempdir().unwrap();
    let (source, read_started, release_read) =
        super::super::virtual_transfer::install_blocked_fake_data_object_session(
            "cancel.txt".into(),
            Some(4),
            [Ok(b"data".to_vec())],
        );
    let mut runtime = super::super::runtime::OperationRuntime::default();
    let token = runtime
        .submit(OperationRequest {
            kind: OperationKind::Copy,
            virtual_source: Some(source.clone()),
            sources: Vec::new(),
            destination: Some(root.path().to_path_buf()),
            batch_rename_plan: None,
            move_identity_guard: None,
            clipboard_move_source_evidence: None,
            rename_reparse_guard: None,
            move_destination_identity_guard: None,
            move_replace_source_evidence: None,
            trash_source_guards: None,
            source_cleanup_identity_guard: None,
            initial_conflict_policy: None,
            copy_destination_identity_guard: None,
            create_parent_directory_identity_guard: None,
            zip_create_guard: None,
            shortcut_create_guard: None,
            seven_zip_create_guard: None,
            seven_zip_extract_guard: None,
            origin: None,
        })
        .unwrap();
    let worker = runtime.start_next().unwrap();
    let (fact_tx, fact_rx) = std::sync::mpsc::channel();
    let worker_thread = std::thread::spawn(move || {
        execute_prepare(
            worker.command,
            worker.cancellation.as_ref(),
            &worker.controls,
            |fact| {
                let _ = fact_tx.send(fact);
            },
        )
    });
    read_started.recv().unwrap();
    assert_eq!(std::fs::read_dir(root.path()).unwrap().count(), 1);
    let stage_path = std::fs::read_dir(root.path())
        .unwrap()
        .next()
        .unwrap()
        .unwrap()
        .path();
    assert!(
        std::fs::OpenOptions::new()
            .write(true)
            .open(&stage_path)
            .is_err()
    );
    assert!(std::fs::remove_file(&stage_path).is_err());
    let moved_destination = root.path().with_extension("moved");
    assert!(std::fs::rename(root.path(), &moved_destination).is_err());
    let _ = runtime.cancel(token);
    assert!(
        fact_rx
            .try_iter()
            .all(|fact| !matches!(fact, ExecutorFact::Terminal { .. }))
    );
    release_read.send(()).unwrap();
    let terminal = loop {
        let fact = fact_rx.recv().unwrap();
        let terminal = matches!(fact, ExecutorFact::Terminal { .. });
        let _ = runtime.commit_fact(fact.clone());
        if terminal {
            break fact;
        }
    };
    worker_thread.join().unwrap();
    assert!(
        matches!(terminal, ExecutorFact::Terminal { report, .. } if report.outcome == TerminalOutcome::Cancelled)
    );
    assert_eq!(std::fs::read_dir(root.path()).unwrap().count(), 0);
    assert_eq!(
        super::super::virtual_transfer::read_chunk(source.items[0].token, 1).unwrap_err(),
        super::super::virtual_transfer::TransferError::InvalidData(
            "virtual transfer session expired".into()
        )
    );
}

