                    let checkpoint = serde_json::json!({
                        "kind": "backup_cleanup_durable_before_runtime_ack",
                        "attempt": durable_attempt,
                        "runtime_ack_issued": false,
                        "runtime_phase_pending": true,
                        "source": source,
                        "destination": destination,
                        "backup": backup,
                        "source_identity": identity_text(&source_identity),
                        "target_identity": identity_text(&target_identity),
                        "source_tree": original_source_tree,
                        "target_tree": original_target_tree,
                        "journal_bytes": durable_bytes,
                    });
                    let mut checkpoint_file = std::fs::OpenOptions::new()
                        .write(true)
                        .create_new(true)
                        .open(&checkpoint_path)
                        .expect("create BackupCleanup pre-ACK checkpoint");
                    use std::io::Write;
                    checkpoint_file.write_all(&serde_json::to_vec(&checkpoint).unwrap()).unwrap();
