                    let blocker = std::fs::OpenOptions::new()
                        .read(true)
                        .write(true)
                        .share_mode(FILE_SHARE_READ.0 | FILE_SHARE_WRITE.0)
                        .open(&journal_path)
                        .unwrap();
                    let before = std::fs::read(&journal_path).unwrap();
                    let result = writer
                        .complete_directory_move_replace_rename_backup(key.clone(), item.0)
                        .recv_blocking()
                        .unwrap();
