                    let runtime_attempt = runtime.journal_attempt(token).unwrap().clone();
                    let runtime_ledger = runtime_attempt.directory_move_replace_rename.as_ref().unwrap();
                    assert_eq!(runtime_attempt.state, crate::operations::journal::JournalState::Running);
