                    assert!(durable_attempt.terminal_outcome.is_none());
                    assert!(!durable_attempt.receipts_recorded);
                    assert_eq!(durable_ledger.phase, Phase::BackupComplete);
                    assert!(durable_ledger.pending_cleanup.is_none());
                    assert!(durable_ledger.backup_root_disposed);
                    assert!(durable_ledger.approved_target_children.iter().all(|child| child.disposition_recorded));
                    let backup = PathBuf::from(std::ffi::OsString::from_wide(&durable_ledger.backup.units));
