            serde_json::from_value(checkpoint["completed_cleanup_receipts"].clone()).unwrap();
        if is_second_child_cleanup {
            assert_eq!(intent.ordinal, 1);
            assert_eq!(intent.node_kind, crate::operations::journal::JournalDirectoryNodeKind::Directory);
            assert_eq!(intent.relative_components.len(), 1);
            assert_eq!(std::ffi::OsString::from_wide(&intent.relative_components[0]), "nested");
            assert_eq!(completed_cleanup_receipts.len(), 1);
            assert_eq!(completed_cleanup_receipts[0].ordinal, 0);
        }
        assert_eq!(attempt.state, crate::operations::journal::JournalState::Running);
        assert!(attempt.terminal_outcome.is_none());
