    fn is_fixed_ntfs(path: &Path) -> bool {
        use ::windows::{
            Win32::Storage::FileSystem::{GetDriveTypeW, GetVolumeInformationW},
            core::PCWSTR,
        };
        use std::os::windows::ffi::OsStrExt;
        let root = path.ancestors().last().unwrap();
        let wide = root
            .as_os_str()
            .encode_wide()
            .chain(Some(0))
            .collect::<Vec<_>>();
        let mut fs = [0u16; 32];
        (unsafe {
            GetDriveTypeW(PCWSTR(wide.as_ptr())) == 3
                && GetVolumeInformationW(
                    PCWSTR(wide.as_ptr()),
                    None,
                    None,
                    None,
                    None,
                    Some(&mut fs),
                )
                .is_ok()
        }) && String::from_utf16_lossy(&fs)
            .trim_end_matches('\0')
            .eq_ignore_ascii_case("NTFS")
    }
